WordHunterWoW_QuestEN = WordHunterWoW_QuestEN or {}
WordHunterWoW_QuestEN[48016] = { title = "Ascending Alchemy", description = "I've seen other alchemists come through our camp carrying interesting looking trinkets. I believe they refer to them as... \"alchemist stones\"?\n\nI can sense the power they radiate, but they appear fel-tainted. The herb that grows on this planet is particularly good at cleansing corruption. I use it to purify the primal sargerite that's often found amongst the herbs.\n\nI'm certain that if we used a purified sargerite with one of those stones, we could elevate the power within it.", objectives = "Bring Funen 75 Astral Glory, 5 Primal Sargerite and a Bound Infernal Alchemist Stone.", progress = "I know it's a lot of materials to ask for, but it's necessary.", completion = "And there you have it! I believe this will be far more useful for you in your fight against the Legion.\n\nAllow me to explain how it's done..." }
WordHunterWoW_QuestEN[48021] = { title = "Chromie", description = "{name}. Is that you?\n\nI'm convinced that something unusual has happened in the timelines. I need your help!\n\nCome find me at Wyrmrest Temple, in Dragonblight, and I'll show you.", objectives = "Reach \"Timehopper\" friendship rank with Chromie in Dragonblight.", progress = "Any luck traversing the timeways?", completion = "Despite her troubles, this has been a welcome reminder that, although our battle with the Legion remains at the forefront of our concerns, the rest of the world does not simply wait for us." }
WordHunterWoW_QuestEN[48022] = { title = "Tracking Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[48023] = { title = "Orders Received", description = "We need ta be knowin' who be leadin' da naga in snatchin' all dese cute frogs. \n\nDey got chests around here dat have some kind of scroll dey be readin'. Da ladies be tellin' da men to remember dem orders.\n\nGet me some of dem scrolls so we can be seein' who be callin' da shots.", objectives = "Recover 5 Explicit Orders." }
WordHunterWoW_QuestEN[48025] = { title = "Saving for Later", description = "We need time to recover the artifacts from this place. Time the naga will not let us have.\n\nHowever, we do have a plan.\n\nWe simply hide what we don't want them to find, and then come back in a decade or two. They will have forgotten about this place by then.\n\nTake this illusion scroll and use it to conceal the notable artifacts of power.", objectives = "Conceal the antiquities of Gral.", progress = "How is that scroll working out?", completion = "Naga may be long lived, but their attention spans are not what they once were.\n\nThese antiquities should remain safe and preserved until we return." }
WordHunterWoW_QuestEN[48026] = { title = "Beneath the Waves", description = "Those witches dare! In my temple? \n\nSiavass is stretching past the realm of that which she can comprehend. There is a darkness seeking them, and they call to it! Her kind will become no more than a hollow tool to those who may answer.\n\nI feel it moving beneath us, around us. I feel it like a tremor through my being. \n\nThere is a pressure there, it has a weight greater than that of the deepest ocean. \n\nWe must stop them. They are not welcome here!", objectives = "Slay Summoner Siavass and the Whispering Horror.", completion = "The naga are trying to hide something. My strength may be waning, but one should never underestimate a loa." }
WordHunterWoW_QuestEN[48027] = { title = "The Glory of Argus", description = "<Amazed that anything so pure could continue to grow on this planet, you pick the flower from the ground. You feel a small power radiate from it and then vanish.>\n\n<As it falls apart in your hands, you wonder if anyone on this Light-forsaken place knows how to handle this precious herb.>", objectives = "Find someone on Argus who might be able to train you on how to handle Astral Glory.\n\nProvided item:", completion = "So you were trying to gather astral glory I see. Yes, there is a method to doing it correctly.\n\nThe flower has a power to it, allowing it to protect itself from anything it thinks may seek to destroy it. If it feels truly threatened, it extinguishes itself.\n\nYou mustn't try to pick it with intent to harm, but to protect. It's an unfortunate irony as we eventually destroy it in the process of making items with it.\n\nHowever, this deception is necessary for it to yield itself to you." }
WordHunterWoW_QuestEN[48028] = { title = "Youthful Resistance", description = "<As you begin to gather the flowers, you realize that some of the younger blooms are still resistant to your approach and refuse to yield. Perhaps Funen might know more about how to handle the herb in its adolescent stages.>", objectives = "Ask Funen about how to handle the younger Astral Glories.\n\nProvided item:", completion = "Indeed, the newer blooms are particularly stubborn and would rather give up their life than live in servitude to those who pick them.\n\nTo handle the herb in this form, one must coax the herb into submitting, as it can't quite fully read the intentions of those who wish to gather it." }
WordHunterWoW_QuestEN[48029] = { title = "The Heart of It", description = "<Having handled astral glory for a while now, you've picked up on something interesting about its roots. Tightly wound in a cocoon, small flecks of light permeate through the cracks creating a shimmering effect.>\n\n<Perhaps Funen might be able to expand on the nature of these lights.>", objectives = "Ask Funen about the shimmering roots of the Astral Glory.\n\nProvided item:", completion = "I see the glory has come to trust you fully. It is now exposing its heart to you.\n\nFocus your intentions here and you will gather it in its entirety." }
WordHunterWoW_QuestEN[48030] = { title = "FLAG - Stratholme Scene Seen", description = "", objectives = "" }
WordHunterWoW_QuestEN[48031] = { title = "FLAG - Andorhal Scene Seen", description = "", objectives = "" }
WordHunterWoW_QuestEN[48032] = { title = "FLAG - Hyjal Scene Seen", description = "", objectives = "" }
WordHunterWoW_QuestEN[48033] = { title = "FLAG - Well of Eternity Scene Seen", description = "", objectives = "" }
WordHunterWoW_QuestEN[48034] = { title = "Empyrium Deposit Chunk", description = "<As you swing your pickaxe into the ore, it hits with a resounding thud, sending a small chunk of it to the ground. At this rate, it would take you all day to get a sufficient amount of ore from this deposit.>\n\n<Perhaps someone can give you some insight into how to mine this deposit properly.>", objectives = "Find someone on the Vindicaar who might be able to train you on how to mine an empyrium deposit.\n\nProvided item:", completion = "Empyrium requires a precise strike to yield the best results. Aim your pick at the brightest bits of the ore, which also happen to be very small, hence the precision.\n\nThis will break the deposit apart faster and you'll be able to harvest ore quicker." }
WordHunterWoW_QuestEN[48035] = { title = "Angling For a Better Strike", description = "<Looking at the empyrium dust from taking down this deposit, you wonder if there's a way to prevent part of the deposit from shattering with each impact.>\n\n<Perhaps Khamir will know something further that he can share with you.>", objectives = "Speak with Khamir and see if there's a better way to mine empyrium deposits.\n\nProvided item:", completion = "As I mentioned before, precision is key with mining empyrium. You've learned to strike at the correct spots, now you must learn to strike at the correct angle.\n\nTake out your pick and I'll show you what I mean..." }
WordHunterWoW_QuestEN[48036] = { title = "Precision Perfected", description = "<While you've learned to extract as much of the deposit as you can, the core of the deposit is always left unusable. Looking closely, you can see where your strikes were causing fractures in its structure.>\n\n<One more lesson from Khamir might be needed to correct this problem.>", objectives = "Speak with Khamir and see if there's an even better way to mine empyrium deposits.\n\nProvided item:", completion = "You've learned where to strike and at what angle to strike, but should you wish to leave the core intact to mine, you must finally learn how hard to strike.\n\nThe fractures you found in this core are the result of striking the ore too hard. As I'm sure you no doubt know by now, mining empyrium is not just a task, but an art.\n\nCome, let us practice your swing until it's just right." }
WordHunterWoW_QuestEN[48037] = { title = "Empyrium Seam Chunk", description = "<At first you thought the ore to have a mirrored surface, reflecting the starry space above you. After breaking off a chunk, you realize that the ore itself has a starry quality all of its own.>\n\n<Perhaps someone back at the Vindicaar can give you some insight on how to better extract these seams more efficiently.>", objectives = "Find someone at the Vindicaar who might be able to train you on how to mine empyrium seams.\n\nProvided item:", completion = "Empyrium is quite a sight to behold once it's been mined. And while the deposits of this ore require precision, the seams require exposure.\n\nIf you spend some time picking away the surrounding rock, you'll find much more ore to harvest." }
WordHunterWoW_QuestEN[48038] = { title = "Don't Just Pick At It", description = "<Even though you've learned to expose the ore, large chunks of it still seem to be embedded in the surrounding rock. Picking those pieces away may not result in the pure form of empyrium that you're looking for.>\n\n<Perhaps Khamir can show you a way to remove the ore from these sections of the seam.>", objectives = "Speak with Khamir about a way to extract more ore from empyrium seams.\n\nProvided item:", completion = "Empyrium seams can be tricky in that regard. The ore is very good at interweaving itself into the surrounding elements.\n\nI've found that striking those areas with the shaft of the pick loosens the empyrium's grip on it, so that when you pick at it, the rock should just fall away." }
WordHunterWoW_QuestEN[48039] = { title = "Balancing the Break", description = "<Getting down to the root of the seam, you're left with nothing but small bits and pieces. Collectively though, they would have been enough to work with.>\n\n<Khamir might know a way to prevent this from happening.>", objectives = "Speak with Khamir about a way to extract even more ore from empyrium seams.\n\nProvided item:", completion = "Much like the deposit, empyrium requires a balanced extraction. Its core is its most fragile section.\n\nIf you swing too hard, it breaks, too soft and you'll be there forever. The same is true for loosening it from its surrounding rock.\n\nHere, let me show you a method which balances both." }
WordHunterWoW_QuestEN[48040] = { title = "Tainted Scraps", description = "<As you begin to carefully remove the skin from the corpse, you notice it quickly becoming corrupted by the decay of the creature.>\n\n<Pulling away, you were only able to extract a small amount of leather and something foul smelling. Perhaps someone on the Vindicaar might know more about this foul hide.>", objectives = "Find someone at the Vindicaar who might be able to train you on how to skin fiendish leather.\n\nProvided item:", completion = "If you haven't already guessed, the key to skinning these creatures properly is speed. They're born of foul energies and those spill out once you begin to cut into the corpse.\n\nI would suggest training your hand to become faster at removing the hide." }
WordHunterWoW_QuestEN[48041] = { title = "A Larger Cut", description = "<While you've become quicker at removing pieces of the hide, there is still much that is spoiled before you're able to remove it.>\n\n<Enstraa might have a better idea of how to remove more of the hide before it becomes tainted.>", objectives = "Speak with Enstraa about a better way to remove fiendish leather.\n\nProvided item:", completion = "So you've become faster, but you're still thinking in your old ways.\n\nInstead of cutting away small pieces at a time, try making one large cut and removing as much of the hide in as few cuts as possible. Move away from the corpse and begin cutting the large pieces into smaller, usable pieces." }
WordHunterWoW_QuestEN[48042] = { title = "Order of Operations", description = "<The skins have been more abundant, but you're only able to gather a couple teeth and claws before they take on the corruption.>\n\n<Unsure as to how to extract as many teeth and claws as possible, you find yourself wanting to have one last conversation with Enstraa back at the Vindicaar.>", objectives = "Speak with Enstraa about a better way to dissect the beasts of Argus.\n\nProvided item:", completion = "So it's just more teeth and claws you're after? This should be simple to explain then.\n\nThe teeth receive the greatest exposure to the creature's foul insides, so removing them first will still give you time to dissect the rest of the beast. Next, remove the hide. And lastly the claws, as those take the longest to take on any corruption." }
WordHunterWoW_QuestEN[48043] = { title = "FLAG - Plating Cleared", description = "", objectives = "" }
WordHunterWoW_QuestEN[48044] = { title = "FLAG - Shields Cleared", description = "", objectives = "" }
WordHunterWoW_QuestEN[48053] = { title = "Weigh Anchor", description = "{name}, I was hoping to ask you for a small favor. The naval fleet at Stormwind Harbor have been requesting large amounts of felslate to help construct supplies for their ships.\n\nI'm pretty busy here coordinating the gathering efforts and all my couriers are still out. I was wondering if you wouldn't mind taking that shipment over there to them?\n\nI heard there's a portal to Stormwind in the Greyfang Enclave here in Dalaran so it shouldn't be a long trip or anything.", objectives = "Bring the Crate of Felslate to Walcott Sutton at Stormwind Harbor.", progress = "Did Alard send you?", completion = "Whaddya got for me?\n\nMore felslate, fantastic! This stuff weighs a ton, and is perfect for anchors.\n\nI see you have the arms of a blacksmith. Perhaps you'd like ta have a hand at making a few anchors as well, eh?" }
WordHunterWoW_QuestEN[48054] = { title = "Weigh Anchor", description = "{name}, I was hoping to ask you for a small favor. The naval fleet at Bilgewater Harbor have been requesting large amounts of felslate to help construct supplies for their ships.\n\nI'm pretty busy here coordinating the gathering efforts and all my couriers are still out. I was wondering if you wouldn't mind taking that shipment over there to them?\n\nI heard there's a portal to Orgrimmar in the Windrunner's Sanctuary here in Dalaran so it shouldn't be a long trip or anything.", objectives = "Bring the Crate of Felslate to Kruda Thunderhand at Bilgewater Harbor.", progress = "Did Vridiel send you?", completion = "More felslate, fantastic! This stuff weighs a ton, and is perfect for anchors.\n\nI see you have the arms of a blacksmith. Perhaps you'd like to have a hand at making a few anchors as well, eh?" }
WordHunterWoW_QuestEN[48055] = { title = "Empyrial Strength", description = "I see my armor's caught your interest. It's made from the finest material on Argus: empyrium. I actually specialize in crafting breastplates.\n\nI could show you how to craft one, but you'll need to bring your own supplies, I'm afraid. Our stores of the ore are low and we need all that we have.\n\nBut here are the plans so you'll know what you need to find...", objectives = "Craft an Empyrial Breastplate. You can find the materials from gathering the ore from Argus, from other players, or from the auction house.", progress = "I hope those plans weren't too complicated for you to understand.", completion = "This is quality work. It appears you even solved an issue I was having with the spacing between the front and back chest plates.\n\nYou wouldn't mind if I kept this, would you? A fair trade for the recipe, yes?" }
WordHunterWoW_QuestEN[48056] = { title = "A Harsh Mistress", description = "So there I was thinkin' about how to get everyone ready for movin' around Argul or whatever it's called, since I figure its gravity is different than ours, and I come up with a design for a device you slip onto your shoes, or hooves or whatever you're wearin' down there.\n\nNext thing I hear, the gravity on that planet? Completely the same as ours!\n\nRegardless, I figure I could get the prototype workin'. Mind givin' me a hand? Maybe when we're done you can like, sell 'em to kids or somethin'.", objectives = "Help Hobart calibrate the Prototype Gravitational Reduction Slippers around Dalaran.", progress = "This is gonna be fun... to watch!", completion = "That last jump looked about what I had in mind for how the gravity was gonna be.\n\n<Hobart scribbles some notes on the schematic.>\n\nAnd there ya have it. They'll only last ya a few minutes before they're spent, so use 'em wisely." }
WordHunterWoW_QuestEN[48058] = { title = "Mana-Etched Regalia", description = "", objectives = "" }
WordHunterWoW_QuestEN[48059] = { title = "Der'izu Armor", description = "", objectives = "" }
WordHunterWoW_QuestEN[48060] = { title = "Righteous Battleplate", description = "", objectives = "" }
WordHunterWoW_QuestEN[48061] = { title = "Obsidian Prowler's Garb", description = "", objectives = "" }
WordHunterWoW_QuestEN[48062] = { title = "Scarlet Crusader", description = "", objectives = "" }
WordHunterWoW_QuestEN[48064] = { title = "Goroth Intro", description = "", objectives = "" }
WordHunterWoW_QuestEN[48065] = { title = "Extraterrestrial Exploration", description = "{name}, I hear you've been over to that large green planet in the sky already. Swarming with demons too, I hear.\n\nI was thinking maybe we could put together another wormhole generator for it. Make it easier to zip around the planet.\n\nProblem is we need to get readings on the landscape, and I'd go, but uh... well I need to stay here and run the shop. Can't leave it to these bozos to handle.\n\nHere, take this and get some readings for me, will ya?", objectives = "Use the Ionized Geographical Recorder at the locations marked on your map. Return to Didi when you're finished.", completion = "Oh, this is great stuff. That's some landscape up there! Let me just get this information written down...\n\n<Didi begins to scribble some notes on some blueprint paper.>\n\nThat should do it. As with all generators, you'll need to use local materials for it, so whatever you can find on that planet should work." }
WordHunterWoW_QuestEN[48066] = { title = "A Feast for Our Kin", description = "Ah, the Highmountain tauren. They have been our allies ever since we felled the Legion.\n\nAre you interested in hearing how they joined the Horde? It is quite the tale!\n\nIt all began with Baine Bloodhoof and Mayla Highmountain. Baine was hosting a great feast in Thunder Bluff to welcome the Highmountain tauren...", objectives = "Meet Baine Bloodhoof at Thunder Bluff in Mulgore.", completion = "Welcome, <name>.\n\nMayla speaks of you as a trusted ally. Your presence will surely help convince her of the merits of joining the Horde." }
WordHunterWoW_QuestEN[48067] = { title = "Shadow Over Thunder Bluff", description = "A dark force has descended upon us. I refuse to believe that the Highmountain are behind it.\n\nThe cacophony out there is disturbingly familiar. Could it be... \n\nNo! The minions of the Old Gods are attacking! We must fight for Thunder Bluff, {name}!", objectives = "Slay 4 Dark Tendrils and 12 Shadows of Uul in Thunder Bluff.", progress = "For the Old Gods to manifest even these fledgling minions is troubling.", completion = "The Old Gods are known for subversion and duplicity. To attack so brazenly...\n\nWhatever they seek, they want it badly." }
WordHunterWoW_QuestEN[48068] = { title = "A Cure for Ebonhorn", description = "A dark force holds Spiritwalker Ebonhorn in its grip. I do not know if we possess the means to cure him, but we must try.\n\nI can think of a few of my kin who might have experience in dealing with such maladies.\n\nSeek out Nara Wildmane, Kador Cloudsong, and Aponi Brightmane. By combining their wisdom, I hope we find the answer we need.", objectives = "" }
WordHunterWoW_QuestEN[48069] = { title = "The Wrench Calls", description = "{name}, Didi the Wrench is looking for you back in Dalaran. You might want to see what she's working on. Pretty fancy stuff from what I heard.", objectives = "Meet with Didi the Wrench in Dalaran.", completion = "<name>, you came at the perfect time. I just finished creating this Ionized Geographical Recorder.\n\nNow, here's how you're gonna use it..." }
WordHunterWoW_QuestEN[48070] = { title = "The Norwington Festival", description = "To whomever receives this invitation,\n\nYou are cordially invited to the 15th annual Norwington Equestrian and Hunt Festival!\n\nPeople of all walks of life from across Kul Tiras shall gather to delight in life's greatest competitions, equestrianism and hunting, while meeting those of like minds and fine tastes.\n\nHunting events shall start first, led by Abbey Watkins in Foxhollow Woods. They shall be followed by equestrian events at the Norwington Estate.\n\nWe hope to see you there posthaste!", objectives = "Meet Abbey Watkins at the edge of Foxhollow Woods.", completion = "Welcome, traveler! Care to join in the hunt?" }
WordHunterWoW_QuestEN[48074] = { title = "Looming Over Me", description = "When I rallied to the Xenedar, I left behind a valuable tool. My lightweave loom. Without it, I'm forced to labor for much longer to make garments of power for our allies.\n\nBut you are powerful, much more so than I. Perhaps you could do me a favor. Should you happen to be in the Arinor Gardens, could you retrieve my loom and return it to me?\n\nI'd be more than willing to share my knowledge of sewing lightweave with you.", objectives = "Go to the Arinor Gardens and retrieve Khaela's Lightweave Loom.", progress = "Any luck in finding my loom?", completion = "You have no idea the time you've just saved me, <name>. You have my utmost gratitude.\n\nAnd as promised, here is my most coveted design." }
WordHunterWoW_QuestEN[48075] = { title = "A Colorful Key", description = "{name}, I hear you're a jewelcrafter. I too am a master cutter, but I fear my designs will be lost to the Legion.\n\nI hurried out of my home with the intention of returning, but I fear that may not be a possibility. You see, I left my most prized possession, a book of jewelcrafting designs.\n\nBut you, you're strong, you could fight your way into my home and recover my book!\n\nHowever, I locked it away in a special chest that requires the gems of this land to unlock. You'll need one of each to open it.", objectives = "Travel to Vorel's home and unlock his chest using each of the six gems that come from prospecting empyrium. Recover his jewelcrafting book and return to him on the Vindicaar.", progress = "The combination isn't that difficult, just put the gems in their appropriate settings.", completion = "My book! And it doesn't appear to be damaged either, thank the Light.\n\nLook here, <name>.\n\n\n\nHere are the designs for turning those gems into accessories of power." }
WordHunterWoW_QuestEN[48076] = { title = "A Crowning Achievement", description = "With my book nearly being lost forever, it occurs to me that I shouldn't keep all this knowledge in one place. I would like to pass it along to you, {name}.\n\nMy most recent designs are ones that I am particularly proud of. I call them Empyrial Crowns. Each one uses a different combination of gems to render different effects of power.\n\nLet me show you how to construct one and then I'll show you how different combinations of gems create different results.", objectives = "Craft an Empyrial Crown for Vorel. You can find the materials from gathering and prospecting the ore from Argus, from other players, or from the auction house.", progress = "Perhaps in time you too will find a student whom you may pass all your knowledge unto.", completion = "Excellent work, <name>. Now, onto the different combinations..." }
WordHunterWoW_QuestEN[48077] = { title = "The Stoat Hunt", description = "One of the greatest hunting sports amongst the nobles of Boralus is the stoat hunt. It is a sport of determination, patience, and skill. Do you think you can rise to the challenge?\n\nStoats are agile, sneaky, and sharp. They're next to impossible to catch out in the forest, so the best way to find one is to find its burrow and scare it out.\n\nFind their burrows and bring back their pelts. Their fur is soft and much loved amongst the nobles.", objectives = "Collect 5 Soft Stoat Pelts from Faintstep Stoats.", progress = "Have you collected enough stoat pelts?", completion = "Not only will these pelts please the nobles, they also prove your worth as a hunter." }
WordHunterWoW_QuestEN[48078] = { title = "Counterbalancing", description = "In the past, I was able to make glorious items from the beasts of this land. But then the Legion came and wiped out all those amazing beasts.\n\nNow I'm forced to use their polluted hides to craft armor for my allies. I have, however, found a way to remove their taint.\n\nThe cloth we use is made from special thread infused with Light energy. I devised an oil which when combined with the cloth purifies the leather and makes it usable.\n\nHere, take my oil and see for yourself.", objectives = "Gather Fiendish Leather and Lightweave Cloth and use Enstraa's Tanning Oil to create 12 Purified Fiendish Leather.", progress = "I often dream of working with unsullied leather again. But who knows when that will ever be...", completion = "An interesting balance, but necessary. You may keep the oil, I have plenty.\n\nOh, and now that you know how to purify the leather, let me show you how to use it. Here are some shoulder patterns my allies ask for regularly." }
WordHunterWoW_QuestEN[48079] = { title = "Return to Highmountain", description = "Spiritwalker Ebonhorn remains in great danger. He and Mayla have returned to Highmountain, but I believe they still need our aid.\n\nLet us journey to Thunder Totem and do whatever we can to mend Ebonhorn. Perhaps our deeds will strengthen the bond between our peoples.", objectives = "Meet Mayla Highmountain at Thunder Totem in Highmountain.", completion = "Ebonhorn has spoken of ancient wards that must be maintained in Highmountain. Wards that hold back a great darkness.\n\nThis may be tied to the evil that grips him now.\n\nWe must hope that Spiritwalker Graysky can tell us more." }
WordHunterWoW_QuestEN[48080] = { title = "An Element of Danger", description = "These nobles really think killing weasels is the mark of a good hunter? Ha!\n\nIt ain't hunting if there isn't a bit of danger involved. There are boars in these woods. That's more our speed out in the mountains! Why don't you kill some of those, then bring me their tusks as proof?", objectives = "Collect 8 Rugged Boar Tusks.", progress = "Boars actually present some semblance of challenge to the hunter.", completion = "<Harold lets out a hardy laugh.>\n\nNow that's what I'm talking about!" }
WordHunterWoW_QuestEN[48081] = { title = "A Floating Ruin", description = "We knew the Legion to be a formidable foe, but recent events demonstrate that we do not possess the necessary strength to continue. We have come too far to fail at this critical moment.\n\nI know of a relic on Eredath, my ancient home, that may be our salvation. We must take the Vindicaar beyond the surface of Argus, to the floating ruin suspended above us.\n\nPerhaps there we will find the salvation we so desperately need.", objectives = "Travel to Eredath.", completion = "<Velen's gaze is drawn to the ruins spread out before him.>\n\nI am home." }
WordHunterWoW_QuestEN[48082] = { title = "Tracking Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[48083] = { title = "Tracking Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[48084] = { title = "Tracking Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[48085] = { title = "Tracking Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[48086] = { title = "Poaching the Poachers", description = "Da orders say Skrathax be da one snatchin' most of dem cute frogs.\n\nHe be haulin' lots of frogs ta da main camp. Ya need ta save dem cute dings from Skrathax before it be too late.\n\nI'll be workin' on scoutin' dere camp more. Dis Skrathax can't be da one leadin' all da naga here, but it'll help ta take him down.", objectives = "" }
WordHunterWoW_QuestEN[48087] = { title = "Equine Retrieval", description = "I like the cut of your jib, friend!\n\nI'll tell you what. The rest of the partygoers should be arriving any time now. Would you do me the honor of retrieving my favorite horse from the estate on the hill?\n\nImagine, our guests' first impression of you to be on the most regal horse in all of Tiragarde! Wondrous!", objectives = "Retrieve Lord Norwington's favorite horse Rose from his hilltop estate.", progress = "<name>! The troggs have invaded!", completion = "I don't believe I'm saying this, <name>, but troggs are invading the estate!" }
WordHunterWoW_QuestEN[48088] = { title = "No Party Like a Trogg Party", description = "Troggs? At my party?\n\nMy grandfather pushed them back to that cleft years ago to build this estate. To think that they would attack in such force after all these years?\n\nThis is just what we needed to make this year's festival the greatest ever!\n\nShow us your heroism firsthand, {name}! Mount Cooper and defeat these troggs! Drag them behind you, jab them with your harpoon... whatever it takes!", objectives = "Kill 20 Grimestone troggs in Norwington Estate.", completion = "A grand showing! You had me on the edge of my seat!" }
WordHunterWoW_QuestEN[48089] = { title = "Mountain Sounds", description = "Kul Tirans won't go down without a fight!\n\nTake this horn. We use it in the mountains to warn each other of danger and lead the charge into battle. Use it to rally our allies against the troggs!", objectives = "Use the Horn of the Mountain to rally 8 Kul Tirans.", progress = "We are stronger together!", completion = "Our people defend the estate with renewed vigor!" }
WordHunterWoW_QuestEN[48090] = { title = "Krag'wa's Chosen", description = "Dis be a real mess, {name}. Da naga be drainin' da magic of Krag'wa's frogs ta feed demselves!\n\nDere be three frogs, Krag'wa's champions, dat dey be torturin' as we speak.\n\nTake dis potion, it be returnin' da power of dem noble frogs. Dey deserve better dan bein' drained by dese snake bastards.\n\nI be stayin' here. Da naga got in some lucky hits on me. All me life, I wanted ta see Krag'wa, and I let meself get hurt by some naga!", objectives = "Rescue Krol'dra the Wise, Wok'grug the Clever, and Wag'shash the Bold.", completion = "Ya did it! Krag'wa gonna be pleased wit' dis, I be sure of it." }
WordHunterWoW_QuestEN[48091] = { title = "Vagath the Betrayed", description = "", objectives = "" }
WordHunterWoW_QuestEN[48092] = { title = "Vengeance of the Frogs", description = "Da naga here be led by a priestess, Zaldraxia. She be da one dat figured out how ta drain da frogs of their magic.\n\nZaldraxia be stoppin' at nothin' ta drain every frog here.\n\nDo what I could not, and kill dis priestess. Show da naga dat Krag'wa ain't a loa ta be takin' lightly.\n\nI be prayin' ta Krag'wa for ya success.", objectives = "Defeat Priestess Zaldraxia.", completion = "Wit' Zaldraxia dead, da naga should be leavin' soon. Ya did what I couldn't, and for dat ya have me thanks.\n\nKrag'wa's blessin' be on ya, I be hopin' soon he recognizes me devotion ta him." }
