WordHunterWoW_QuestEN[48106] = { title = "No Love Lost", description = "", objectives = "" }
WordHunterWoW_QuestEN[48107] = { title = "The Sigil of Awakening", description = "This relic is too powerful to keep it out in the open.\n\nWe must return to the Vindicaar at once. The Prophet will know what to do.\n\nI did want to thank you, {name}. Without you this would not be possible. Quoram would have ensured I never got near the Sigil. Perhaps some day I will share that story with you.", objectives = "Return to the Vindicaar and secure the Sigil of Awakening.", progress = "Did you recover the Sigil of Awakening?", completion = "We are that much closer to restoring the Crown of the Triumvirate to its former glory." }
WordHunterWoW_QuestEN[48108] = { title = "The Waycrest Daughter", description = "You seek House Waycrest? Oh, your timing could not be worse!\n\nI had just received a raven regarding Lord Waycrest's daughter, Lucille, shortly before this... curse came upon us.  They apprehended her in Fletcher's Hollow and are taking her to trial.\n\nThey say she is a witch, herself! \n\nIf she's found guilty, she will surely hang! You must make haste to Hangman's Point.  With what you've seen here, maybe you can convince them of her innocence.", objectives = "Meet with Constable Henry Framer at Hangman's Point in Drustvar.", completion = "Can't you see that we're busy here, <class>?\n\nI assume you have a reason for interrupting this trial..." }
WordHunterWoW_QuestEN[48109] = { title = "The Woods Have Eyes", description = "The sooner I can return the lady Waycrest to Highroad Gate the better, but I will honor her wishes if we can assure her safety.\n\nThere are dark things happening in these lands that you don't fully understand. If we must dally, then there are measures that need be taken.\n\nFirst, the wildlife here can serve as eyes to dark powers. Kill them.", objectives = "Kill 4 Watchful Ravens and 6 Darkmaw Prowlers in the Watchman's Wood.", progress = "Has our foe been sufficiently blinded?", completion = "Not a beast in sight. Good.\n\nThe foes of this land must not find us here in the open." }
WordHunterWoW_QuestEN[48110] = { title = "In Case of Ambush", description = "There is more to worry about in these woods than simple beasts. Our enemy employs constructs of wicker and bone that can rip a man apart.\n\nFortunately for us, these constructs are not very perceptive.\n\nTake these traps and set them up throughout the woods behind us.  If our enemies do seek to ambush us here, at least these will slow their minions down.", objectives = "Place 6 traps in the Watcher's Wood.", progress = "We must be prepared. Anywhere can harbor an ambush here.", completion = "Good, those traps should alert us in case anything tries to sneak up on us through the woods.\n\nYou have bought us a modicum of safety, <class>." }
WordHunterWoW_QuestEN[48111] = { title = "Trial by Superstition", description = "Witchcraft has long lived in the superstitions of the people here. It is only recently that some of these superstitions have become reality.\n\nAccording to tradition, one who is tried for witchcraft is allowed to choose the means by which they are tested from among the requests of her peers.\n\nThe villagers here no doubt have some strange beliefs of what witches can and cannot do. Speak with them, and see what we can do to prove my innocence.", objectives = "Question 5 Fletcher's Hollow Villagers in Hangman's Point.", progress = "What have you learned from the villagers?", completion = "Well, those are certainly some interesting beliefs. I think it's safe to rule out the fire and drowning, don't you think?\n\nLooks like that leaves us with three tests..." }
WordHunterWoW_QuestEN[48113] = { title = "A Pungent Solution", description = "The first test should be simple enough. While I may not do so often, I am certainly capable of crying.\n\nThough to be honest, I've never had to cry on cue.\n\nMaybe you could help with that, though. Nearby there is an onion field that belonged to one of the local farmers. It's abandoned, and most of it is dried up by now, but you might be able to find one onion ripe enough in there to cause some tears.", objectives = "Collect a Juicy Onion from Hawthorne's Plot near Hangman's Point.", progress = "Have you had any luck at the onion field?", completion = "Great, you found one! I was worried that there wouldn't be much left growing on that farm. \n\nThe people of Drustvar could learn a thing or two from that hardy onion." }
WordHunterWoW_QuestEN[48165] = { title = "Harmful If Swallowed", description = "This last test I am not looking forward to, but it is certainly better than being set on fire. \n\nThey say that a witch can't get sick. We will prove to them that I can.\n\nA venom comes from the saurolisks nearby that is used by our healers when a child swallows something they shouldn't. When ingested, it will make you immediately ill, emptying the contents of the stomach.\n\nYou'll need several of their venom glands to get enough venom for an appropriate dose. Removing them intact may prove difficult.", objectives = "Collect 5 Intact Venom Glands from the Shallows Saurolisks near Hangman's Point.", progress = "Is the deed done?", completion = "Good. This toxin should have the... desired effect.\n\nGah, I can't believe I'm going to go through with this." }
WordHunterWoW_QuestEN[48170] = { title = "Once Bitten, Twice Shy", description = "I am all too familiar with the bloodfly's bite. We had them all over the fields surrounding Waycrest Manor.\n\nThough I'm loath to subject myself to them on purpose, if it will help convince these people, I am willing to deal with that nuisance. \n\nFind a jar and collect as many bloodflies as you can. They are common in these parts, and shouldn't be hard to find.", objectives = "Find an Empty Jar and use it to catch 6 Hovering Bloodflies near Hangman's Point.", completion = "Well done. \n\nWith this many bloodflies at least one is bound to bite." }
WordHunterWoW_QuestEN[48171] = { title = "The Curse of Fletcher's Hollow", description = "It's obvious the constable won't be swayed until we discover what happened at Fletcher's Hollow. I know very little myself--only that the village has been overrun by monstrous creatures.\n\nI must ask that you travel there in my stead and try to uncover what befell the village. I'm sure Marshal Reade will prevent the constable from harming me while you're away.\n\nDo this for me, and I will help you as I can.", objectives = "Speak with Evelyn Pare at the Timbered Strand in Drustvar.", completion = "You're looking to help solve this curse? Well, that's good to hear. We can surely use all the help we can get.\n\nI'm happy to help you get to the bottom of this. First things first, though, we need to save some of our villagers.\n\nCare to lend a hand?" }
WordHunterWoW_QuestEN[48175] = { title = "Hidden in the Hollows", description = "", objectives = "" }
WordHunterWoW_QuestEN[48176] = { title = "Big Trouble in Little Tortolla", description = "I received a message asking for a sword hand in Little Tortolla. The Tortollan Seekers there are greatly admired by King Rastakhan and have special privileges assigned to them.\n\nGo see what they want and you will have the favor of the King.\n\nAnd {name}, be respectful. Tortollans live long enough they can hold your children's children accountable for your actions.", objectives = "Speak with Toki in Little Tortolla.I received a message asking for a sword hand in Little Tortolla. The Tortollan Seekers there are greatly admired by King Rastakhan and have special privileges assigned to them.\n\nGo see what they want and you will have the favor of the King.\n\nAnd $p, be respectful. Tortollans live long enough they can hold your children's children accountable for your actions.You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[48179] = { title = "Rescue Rangers", description = "We're barely holding off those monsters here. If it hadn't been for the Thornspeakers, we'd surely be dead. I was worried Rebecca hadn't made it!\n\nYou've brought Rebecca's supplies just in time. We have many injured out in the field, Thornspeaker, ranger, and companion alike. I'll hold the line here. Go into the ruins and heal as many of the wounded as you can!", objectives = "Save 10 injured Thornspeakers, rangers, and pets.", completion = "Thank you for helping us, Mainlander." }
WordHunterWoW_QuestEN[48180] = { title = "Really Big Problem", description = "Hey! Mainlander!\n\nI know I'm supposed to be trying to knock over cairns and hauling out lost rangers, but d'you see that massive stone monster? I'm thinking that's gonna be a problem.\n\nYou look like you know how to handle yourself. Think between the two of us we can take it down?", objectives = "Defeat the Ancient Sentinel.", completion = "I suppose I'm not really surprised Arthur didn't exactly follow orders. But I don't think I can complain with the results.\n\nThanks for making sure he wasn't entirely in over his head." }
WordHunterWoW_QuestEN[48181] = { title = "Nooooope", description = "", objectives = "" }
WordHunterWoW_QuestEN[48182] = { title = "Total Cairnage", description = "My mentor sensed the activation of ancient powers here. We came to stop them but were too late. We banded together with the rangers for mutual protection, but our task remains unfinished.\n\nThere is a set of ancient cairns here. These help empower the Drust constructs. Destroying them will also help to settle the undead stirring from the land.\n\nDestroy the cairns and we'll be able to bring sanity to this place.", objectives = "Destroy the Ancient Cairns.", progress = "Power within those cairns does not bode well for anyone in Drustvar.", completion = "Thank you for destroying those cairns. We should be able to dismantle the Drust constructs and risen dead more easily now." }
WordHunterWoW_QuestEN[48183] = { title = "The Hills Are Alive", description = "The Drust constructs are drawn from the land, but the heart of these constructs is a runic power core. \n\nWe have been trying to collect and destroy as many of these cores as we can. We know of a way to disrupt the magic in the core. Doing so will prevent more of these monstrosities from being created around the dark hearts and protect the land and all living in this region.\n\nBring me as many Runic Power Cores as you can find and the Thornspeakers will see they are put to good use.", objectives = "Collect 6 Runic Power Cores from Awoken Guardians.", progress = "We would appreciate any runic power cores from the Awoken Guardians you might find.", completion = "Excellent, <name>. We can use these to protect the land and the people and creatures living here." }
WordHunterWoW_QuestEN[48184] = { title = "Pieces of History", description = "There is an opportunity here.\n\nLearning more about the Drust can not only help us understand the texts that Lady Lucille found, we might be able to discover greater details about how they and their constructs were finally defeated. Filling in the gaps of history could be key to victory now.\n\nThis was one of their settlements before it became the place of their final defeat. Let's look for clues in the ruins.", objectives = "Search the ruins for information about the Drust.", completion = "Gorak Tul's death shattered his army! The carvings here all show that, but now I wonder... Did Gorak Tul actually die?" }
WordHunterWoW_QuestEN[48185] = { title = "Shadow of the Sepulcher", description = "Ebonhorn spoke of another ward safeguarding the lands of the Skyhorn tribe. Somewhere close to the Sepulcher of the Sky, he said. It was there that this \"Darkness\" once manifested.\n\nMeet me there, {name}. I will show you how to walk in the memories of a great Skyhorn hero.", objectives = "Meet Spiritwalker Graysky in Sepulcher of the Sky.", completion = "The next ward is nearby. I can sense it." }
WordHunterWoW_QuestEN[48190] = { title = "Huln's Mountain", description = "We have made progress reactivating the wards, but more must be done.\n\nI sense Ebonhorn's struggle. Though he fights with all his strength, he is slipping away. Should this \"Darkness\" emerge into our realm, I fear our friend will be lost.\n\nEbonhorn spoke of another ward somewhere within Snowblind Mesa. Meet me there, so that I might guide you along another journey into the memories of the past.", objectives = "Meet Spiritwalker Graysky at Snowblind Mesa.", completion = "Do you sense it, <name>? Such strength... such courage.\n\nThe echo of Huln Highmountain's spirit is all around us." }
WordHunterWoW_QuestEN[48192] = { title = "Tar Spitter", description = "", objectives = "" }
WordHunterWoW_QuestEN[48195] = { title = "Troublesome Troglodytes", description = "Troggs are base creatures. They barely have any brain process, living mostly on survival instinct alone. They are pests through and through, and need to be dealt with.\n\nThe fewer of them there are, the better.", objectives = "Kill 8 Grimestone Bullies and 3 Grimestone Throwers in Mistfall Cleft.", completion = "Fewer troggs means fewer of our people getting attacked." }
WordHunterWoW_QuestEN[48196] = { title = "Following Eddie's Trail", description = "My life is equestrian. I'm not a fighter. I could maybe take a trogg or two, but not a whole tribe.\n\nPlease, go into Mistfall Cleft and see if you can find Eddie. Lord Norwington would be furious if something happened to him, and nobody wants to bear witness to that!", objectives = "Follow the trail of Eddie Norwington.", progress = "Are... are you here to save me?", completion = "You saved me! Those troggs are really scary. They took Hotshot and dragged me through their camp!" }
WordHunterWoW_QuestEN[48198] = { title = "The Burden of Proof", description = "I think we have everything we need to conduct three of the villagers' tests. Let us hope this is enough to convince them.\n\nI'm sure Constable Framer is champing at the bit to proceed with his trial, and I would prefer it if you were the one to administer the tests. I may not know you well, but I trust you farther than the constable.\n\nSpeak with him when you're ready to begin.\n\n...and do me a favor. Make this quick.", objectives = "Administer the tests to prove Lucy Waycrest's innocence in Hangman's Point.", completion = "That... didn't turn out as expected.\n\nIt appears that my absolution may truly be in your hands." }
WordHunterWoW_QuestEN[48199] = { title = "The Burning Heart", description = "The loss of Xe'ra is a blow, especially to Turalyon. But even the Light Mother could not be allowed to force destiny upon us.\n\nI wish Illidan had found another way to refuse her... but I too have had choices imposed upon me by the naaru.\n\nThis must not distract us from our mission. Now that we have the Army of the Light survivors with us, it is time to press our attack.\n\nWe need a foothold on the Antoran Wastes from which we can assault the Burning Throne. It is time to deprive Sargeras of his prize!", objectives = "Use the Navigation Console to travel to the Antoran Wastes.", completion = "I never imagined such destruction... such horror." }
WordHunterWoW_QuestEN[48200] = { title = "Securing a Foothold", description = "Alleria and I have scouted this area before, alongside some of our best soldiers. We stationed encampments on either side of our current position, but I fear they will have come under heavy attack. They need reinforcements.\n\nOur first order of business is to set up a teleportation beacon directly below the Vindicaar. From there, we will have access to both fronts.\n\nSpeak to Romuul when you are ready to head down to the surface.", objectives = "Travel to the Antoran Wastes and place the Lightforged Beacon.", progress = "We need that teleportation beacon set up if we are to reinforce our positions.", completion = "Good. From here we can quickly access and reinforce each of the encampments." }
WordHunterWoW_QuestEN[48201] = { title = "Reinforce Light's Purchase", description = "Now that we have established a foothold, we need to rendezvous with our soldiers in the field.\n\nWe have an Army of the Light encampment to the south, near where the Legion is keeping their strongest warriors in some sort of stasis.\n\nAlleria went to scout the area. Find her, and see what information she has gathered.", objectives = "Speak with Alleria at Light's Purchase.", progress = "The camp lies to the south. When you find the large stasis capsules, look for a passage on the left.", completion = "We have a foothold here... for now.\n\nI am unsure how long it could hold out against a sustained assault." }
WordHunterWoW_QuestEN[48202] = { title = "Reinforce the Veiled Den", description = "The foothold you established allows us to check in with our field operatives.\n\nOn our last mission here, we set up a bastion to the northeast. It should be defensible for now, but that could change at any moment.\n\nIllidan has gone ahead to assess the situation. I suggest you go there and see if he needs a hand.", objectives = "Speak with Illidan at the Veiled Den.", progress = "The camp lies to the northeast.\n\nIt may appear hidden at first glance, but you can find the Light shining in the darkest places.", completion = "So many demons. So much work to do." }
WordHunterWoW_QuestEN[48203] = { title = "The Burning Throne", description = "The time has come, {name}, to begin our assault upon Antorus. Everything we have fought for, everything our friends and family have sacrificed, has brought us to this moment.\n\nWe will fire Light's Judgment upon the walls of the accursed citadel and storm their seat of power. We will end the Legion.\n\nAfter all you have done, it is fitting that you have the honor. Activate the Crown of the Triumvirate and let us finish our mission.", objectives = "Use the Crown of the Triumvirate while above the Antoran Wastes to open the way to Antorus.", completion = "After so many years... so many sacrifices... victory is finally within our grasp." }
WordHunterWoW_QuestEN[48230] = { title = "Fragment of the Past", description = "<Your eye is drawn to the faint glow of the crystalline fragment. Examining the piece, you trace the partial pattern of a rune that had been inscribed upon its surface.\n\nThe fragment appears similar to the argunite crystals used by the Army of the Light to power their armaments. Could this crystal have belonged to the eredar who fought to escape Argus so long ago?\n\nPerhaps Captain Fareeya would be able to tell you more about the crystal.>", objectives = "Take the Glowing Key Fragment to Captain Fareeya.", completion = "<Fareeya examines the crystal fragment.>\n\nThis is old... very old. It is a piece of an elaborate key, the sort my people use to secure our most prized and sacred places.\n\nI wonder..." }
WordHunterWoW_QuestEN[48231] = { title = "The Seat of the Triumvirate: Armor of the Triumvirate", description = "This reforged key will grant entry into the armory inside the Seat of the Triumvirate.\n\nLocked away inside is the Armor of the Triumvirate, crafted in the days before Sargeras brought ruin to our world. We cannot let this armor be stolen by the Void's forces.\n\nOnce the armor is in your possession, please bring it to Archivist Ionaa. He has collected our most sacred relics in the cave just up the path. No doubt he would be very glad to receive it.", objectives = "Secure the Armor of the Light and bring it to Archivist Ionaa.", progress = "Have you brought me something, <class>?", completion = "The Armor of the Triumvirate! I never believed I would see it again. It is a reminder of our proud history, one which the evil of the Legion will never overshadow.\n\nGaal told me of your dedication, <name>. It is fitting that you don this armor. May it serve as a beacon of the Light in these dark times." }
WordHunterWoW_QuestEN[48237] = { title = "Defeat Nekthara", description = "", objectives = "" }
WordHunterWoW_QuestEN[48261] = { title = "The Power to Reforge", description = "I forged the key using a pristine argunite crystal. Unfortunately, the only ones remaining are used by the Army of the Light's defenses.\n\nHmm... dendrite clusters might be an alternative. They were used by the elite of Eredath to power simple devices. If enough of the city ruins are still intact, I'd wager the fallen magi or the broken may still have some in their possession. \n\nOf course, I would need a great many clusters to reforge the key. It seems you have your work cut out for you.", objectives = "Obtain a stockpile of Dendrite Clusters.", progress = "Were you able to find enough clusters?", completion = "Ah, yes. Combined, these clusters should provide just enough power for me to fuse the key fragments back together." }
WordHunterWoW_QuestEN[48271] = { title = "Recovering the Pieces", description = "The fragment you found is only one part of the key. I fear the other pieces have fallen into the hands of these ethereal beings you speak of... the Shadowguard. \n\nWe must recover them all. The Shadowguard leaders and lieutenants in and around the Seat of the Triumvirate may well have the fragments in their possession.\n\nGet those key fragments, {name}... any way you have to.", objectives = "Secure the missing key fragments from the ethereals around the Seat of the Triumvirate.", progress = "Did you find all the fragments?", completion = "Nice work, Huntmaster. Those ethereals stood no chance against you.\n\nNow that we have the fragments, I can prepare them for reforging." }
WordHunterWoW_QuestEN[48272] = { title = "Visions of Fear", description = "I've done it, lad. I've reached him again! \n\nOh, but it's so painful. So painful! He's not doin' well, not one bit!\n\nYou'll have to listen on in with me to understand.", objectives = "Witness Argus' vision with Magni.", progress = "It's a lot to take in, I know, but it might help us while we can still be helped.", completion = "The Pantheon has been dead for thousands of years... I fear this plan has been in the works for a very, very long time." }
WordHunterWoW_QuestEN[48273] = { title = "The Speaker Listens", description = "Magni has sent for you in Krokul Hovel once more. He seems to have made a new breakthrough in trying to reach Argus.\n\nI suggest you find him immediately. His last vision foretold Aggramar's coming, and there is still so much we do not know of Sargeras' plans.", objectives = "Meet Magni in the Krokul Hovel.", completion = "Thank ye fer joinin' me, lad. There's somethin' ye have to see." }
WordHunterWoW_QuestEN[48277] = { title = "The Speaker Seeks", description = "Our forces are ready for battle, but we still do not know where Eonar's spirit lies.\n\nYou should seek Magni out at once and see if you can find her while we still have a chance. If she falls, nothing we muster will be able stand against Sargeras.", objectives = "Meet Magni in the Krokul Hovel.", completion = "Ye came just in the nick of time." }
WordHunterWoW_QuestEN[48278] = { title = "Fate of the Life-Binder", description = "I don't even want to think about what happens if Aggramar can find Eonar's spirit before we do. The fate of far more'n Azeroth may hinge on her safety.\n\nLet Turalyon know what we saw right away. We're going to need to bring all we can to bear to save her.You will receive:", objectives = "Return to Turalyon on the Vindicaar.I don't even want to think about what happens if Aggramar can find Eonar's spirit before we do. The fate of far more'n Azeroth may hinge on her safety.\n\nLet Turalyon know what we saw right away. We're going to need to bring all we can to bear to save her.You will receive:" }
WordHunterWoW_QuestEN[48280] = { title = "Visions of Another", description = "Whoever's tryin' to reach us now might give us the information we need to find Eonar.\n\nWe need to see what's goin' on right away!", objectives = "Witness Argus' vision with Magni.", progress = "Eonar's still out there somewhere, but I don't know how much longer she'll last.", completion = "Our answer lies in the Legion's own portal network in the heart of Antorus." }
WordHunterWoW_QuestEN[48281] = { title = "Tracking Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[48282] = { title = "Imp Mother Laglath", description = "", objectives = "" }
WordHunterWoW_QuestEN[48283] = { title = "Standing Accused", description = "So you wish to speak with the accused?  I see no reason why not.\n\nBe quick about it, though. I will not have our trial delayed. This woman will answer for the fate of our village!", objectives = "Speak with Lucy Waycrest in Hangman's Point.", progress = "What is your business here, mainlander?", completion = "So Lady Waycrest has asked that you convince me to let her stand trial?\n\nI think she underestimates the danger of this situation..." }
WordHunterWoW_QuestEN[48284] = { title = "Reap the Fields", description = "", objectives = "" }
WordHunterWoW_QuestEN[48285] = { title = "Aerial Superiority", description = "", objectives = "" }
WordHunterWoW_QuestEN[48286] = { title = "Crystal Methods", description = "", objectives = "" }
WordHunterWoW_QuestEN[48287] = { title = "Harvesters of Sorrow", description = "", objectives = "" }
WordHunterWoW_QuestEN[48288] = { title = "Antoran High Command", description = "The Legion has spent over 10,000 years planning their invasion of Azeroth. Defeat their leaders so they can never threaten our world again.", objectives = "Defeat the Antoran High Command in Antorus, the Burning Throne.", progress = "Have you vanquished the enemy in Antorus?", completion = "Did you triumph in Antorus?" }
WordHunterWoW_QuestEN[48292] = { title = "The Soulhunter", description = "Imonar is the deadliest bounty hunter the Twisting Nether has ever produced. Find a pit to throw him down.", objectives = "Defeat Imonar the Soulhunter in Antorus, the Burning Throne.", progress = "Have you vanquished the enemy in Antorus?", completion = "Did you triumph in Antorus?" }
