WordHunterWoW_QuestEN[48313] = { title = "Nature's Remedy", description = "Your friend doesn't have much time left. The scorpid venom is likely rotting his veins right now. \n\nHe will certainly meet death without a cure.\n\nI will help. \n\nThe first ingredient I'll need is the root of the prickly plum cactus. Its natural healing properties will make a suitable base for the salve.", objectives = "Harvest 6 Prickly Plum in Zul'Ahjin.", progress = "Do you have the prickly plum for the salve?", completion = "These cactus roots will do nicely." }
WordHunterWoW_QuestEN[48314] = { title = "Creeping Death", description = "Scorposhi venom usually induces a slow, creeping death.\n\nIt's remarkable that your friend has survived this long.\n\nAs with most antivenoms, the thing that kills is also the thing that heals. \n\nI'll need to extract the venom from several scorpashi stingers to craft the cure.\n\nWhen the extracted poison is mixed with cactus root salve, we will have the antivenom we need to treat his wounds.", objectives = "Collect 7 Scorpashi Stingers in Zul'Ahjin.", progress = "Do you have the scorpashi stingers?", completion = "Be gentle with the scorpashi stingers, it will only complicate matters worse if one of us become poisoned. The venom of the scorpashi is highly toxic." }
WordHunterWoW_QuestEN[48315] = { title = "Hollow, Empty Eyes", description = "<Carved into the ancient statue are two eye sockets that look like they once held gems. \n\nPerhaps the missing gems can be found within the ruins?>", objectives = "Find the statue's missing gems.", progress = "<Carved into the ancient statue are two eye sockets that look like they once held gems.>", completion = "<The gems slot perfectly into place.>" }
WordHunterWoW_QuestEN[48316] = { title = "Tracking Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[48317] = { title = "A Nose for Magic", description = "I have it! The readings from the ruins are unmistakable. Somewhere to the south and west of the ah... \"foot\", as it were, is a source of great magical energy.\n\nIt can be nothing but the Eye of Xibala!\n\nWe will need to place a few more scrying vessels to pinpoint the Eye's exact location.\n\nMeet me deeper in the ruins. I will personally oversee this effort.", objectives = "Meet Apprentice Telemancer Astrandis in western Xibala and aid him in his search for the Eye of Xibala.", completion = "I seem to have overestimated the ah... accuracy... of my scrying.\n\nAnd thus, our enemies have located the Eye first." }
WordHunterWoW_QuestEN[48318] = { title = "Work Order: Lightblood Elixirs", description = "", objectives = "Are you here to deliver supplies?", progress = "Are you here to deliver supplies?", completion = "Thank you for assisting us, alchemist. We needed these potions badly." }
WordHunterWoW_QuestEN[48320] = { title = "The Best Kill is Overkill", description = "I watched you kill those Sandfury earlier, {name}. You have blood instinct. I like dat.\n\nI bet de others have you hunting frivolous luxuries for de inn. I'll give you an assignment worth your talents.\n\nDis oasis is full of dangerous beasts dat'll scare away guests and harrass my pterrordaxes flying in and out.\n\nKill dem.\n\nOnce de skies are clear, my pterrordaxes can fly you wherever you want.", objectives = "Kill 15 predators in the Whistlebloom Oasis.", progress = "Are de skies clear?", completion = "Dere are still plenty of things for our guests to kill for recreation. At least now, dey won't be hunted on their way in." }
WordHunterWoW_QuestEN[48321] = { title = "Creative Marketing", description = "De Goldtusk Gang is de best gang in all of Zandalar.\n\nI know dat. You know dat. Everyone in de gang knows dat.\n\nBut we need to make sure dat everyone who sees our inn knows dat too.\n\nWe need something big... Something like a massive gold tusk!\n\nI don't know where we'd find one of those, but I got a plan.\n\nDere's a huge saurolisk in de oasis. Bring me one of its giant bones and I'll take care of de rest.", objectives = "Collect Bloodcrest's Giant Rib in the Whistlebloom Oasis.", progress = "If dis doesn't work, we can always be de Bloody Rib Gang.", completion = "Oh yeah, I can work with dis." }
WordHunterWoW_QuestEN[48322] = { title = "A Goldtusk Greeting", description = "Thanks to you, de Goldtusk Inn has never looked better!\n\nWe got food, we got beds, we got piles of dead Sandfury nearby. Dis is everything I ever dreamed it be!\n\n<Rhan'ka looks out into the oasis.>\n\nYou hear dat? Sound like we got our first guest of de day!\n\nWhy don't you greet dis one? Show 'em all de great amenities ya built here!", objectives = "Greet the approaching guest and show them around the Goldtusk Inn.", progress = "Our first guest of de day. So exciting! Don't kill 'em!", completion = "De Goldtusk Inn be open to all exiles. We stick together out here." }
WordHunterWoW_QuestEN[48323] = { title = "Work Order: Tears of the Naaru", description = "", objectives = "Are you here to deliver supplies?", progress = "Are you here to deliver supplies?", completion = "Thank you for assisting us, alchemist. We needed these potions badly." }
WordHunterWoW_QuestEN[48324] = { title = "Lost in Zem'lan", description = "Legends say that a mountain of treasure sits deep inside the Port of Zem'lan, pillaged from every corner of Azeroth. But it's guarded by unkillable, eternal monsters.\n\nNo vulpera or exile has ever stolen treasure from the Port of Zem'lan and made it out alive.\n\nMy caravan was going to be the first. Our scout, Meeki snuck in to figure out a route, but he never came back.\n\nIt would be wisest for you to leave here and never return. But, if you go into the port, please find Meeki.", objectives = "Find Meeki.", completion = "<Meeki has been stabbed multiple times. He is clearly dead.>" }
WordHunterWoW_QuestEN[48326] = { title = "This Be Mutiny", description = "It be time to face Pirate-King Zem'lan and bring dis mutiny to bear, {name}.\n\nZem'lan keeps a gong at de top of his treasure isle dat any crew member can ring to challenge him to a fight. I only ever seen one lass brave enough to ring it, and it didn't end well for her.\n\nBut you and me, we be de scourge of de seven seas, aye? Even mighty Zem'lan be no match for de two of us together.\n\nRing de gong, and let's make Zem'lan pay for cursin' his crew and treatin' us like dogs.\n\nMutiny or de yard arm!", objectives = "Ring the Gong of Zem'lan and kill Pirate-King Zem'lan.", completion = "Yarr! Vengeance and treasure!" }
WordHunterWoW_QuestEN[48327] = { title = "A Strange Delivery", description = "The last time our caravan rolled through the Whistlebloom Oasis, we found an odd Zandalari living in a cave. We traded a few things and he paid me upfront to bring him a pineapple. I don't know why.\n\nIt took me a long time to find one, but a vulpera holds up her end of the trade.\n\nI was planning to stop by and drop it off after we finished here. But, thanks to your help, we've got a lot more treasure hunting to do here at the port.\n\nIf you have time, would you deliver it for me?", objectives = "Deliver the pineapple to Rhan'ka in the Whistlebloom Oasis.\n\nProvided item:", completion = "<Rhan'ka closely inspects the pineapple.>\n\n This... is... the perfect pineapple!" }
WordHunterWoW_QuestEN[48329] = { title = "Beaten But Not Broken", description = "<Beastbreaker Hakid's crystal-encrusted key looks like it will open the large cage nearby.\n\nThe pterrordax inside that cage, Scion of Rakjan, is stronger than the other hatchlings you've seen in the Crackling Ridge. He holds his head high and doesn't seem bothered by the myriad scars and fresh wounds that cover his body.\n\nIf you release him, he'll likely want to return to Rakjan the Unbroken at the top peak of Crackling Ridge.>", objectives = "Free the Scion of Rakjan and lead him to Rakjan the Unbroken.", completion = "<Rakjan lowers his head in respect.>" }
WordHunterWoW_QuestEN[48330] = { title = "Zandalari Treasure Trove", description = "We've looted some quality goods already, but the real reward is still ahead. The big chamber in the back of the ruins is filled with powerful artifacts.\n\nA treasure trove like that is the sort of thing that can save lives and sell for a fortune out here in Vol'dun.\n\nBut those specters you killed weren't lying. Their master or king or whatever is very well-protected in there.\n\nWe'll have to take this one down as a group. Let me know when you're ready to head up to the chamber.", objectives = "Kill Zak'rajan the Undying in his throne room.", progress = "I'm glad you're with us on this one.", completion = "With Zak'rajan out of the way, we've got first claim on all the treasure he's been hoarding here!\n\nYou get your fair share, of course. A worker's worth his wage." }
WordHunterWoW_QuestEN[48331] = { title = "Siphoning Souls", description = "<Tacha rummages through her sack of scavenged supplies.>\n\nSo these golems are powered by Zandalari souls?\n\nNo problem... I've had to deal with that before... I've got just the tool for it.\n\n<Tacha pulls out an eerie Zandalari totem.>\n\nHere it is! Found this ol' soulcatcher totem in one of the southern ruins years ago. It's gotten us out of a few jams.\n\nDisable the golems and throw down this totem next to it. It'll siphon off the souls.\n\nKeep the totem. We'll need it later.", objectives = "Kill 5 Soul-Trapped Guardians and use the Soulcatcher Totem to siphon their souls from their corpse.", completion = "See? I told you that the soulcatcher totem would make it easy. A tool for every problem, I say." }
WordHunterWoW_QuestEN[48332] = { title = "Ranishu Are Resources", description = "We can't afford to waste resources out here.\n\nOver time, we've learned to take anything that looks even remotely useful, and be creative using what we have. I've turned a skull into a boat and a sethrak into a tent flap.\n\nI can't spit dust when it comes to magic, but I can mix poisons and potions with the best of 'em.\n\nRanishu stomach acid makes wicked poison, but it's nasty to collect. Don't try to bottle it. Just bring me their stomachs whole and intact. No leaks!", objectives = "Collect 25 Intact Ranishu Stomachs.", progress = "It looks like you've still got all your fingers. That's good.", completion = "Can't say I've seen someone carry that many stomachs at once.\n\nI don't know if I'm impressed or disgusted." }
WordHunterWoW_QuestEN[48334] = { title = "They've Got Golems", description = "I've sacked countless ruins across Vol'dun. Everything from saurolisk-infested dens to the cursed Port of Zem'lan.\n\nI don't say this to brag. I want you to understand that I know what I'm doing.\n\nI've survived this long because I take my time, avoid risks, and only take what I need.\n\nThat's what we'll be doing here today.\n\nOmi reported heavy golem activity on her first scouting trip into the ruins. Zandalari golems are formidable. We need to learn what's powering them before we head in.", objectives = "Find a Malfunctioning Golem and discover its power source.", progress = "Did you discover the golems' power source?", completion = "The golems are powered by souls? Hmm... \n\nWe're dealing with a very powerful enemy. We should take extra precautions." }
WordHunterWoW_QuestEN[48335] = { title = "The Strongest Rope in Vol'dun", description = "You ever tried tying up a sethrak with vulture string? Won't hold 'em for long.\n\nWhen you really gotta keep something, or someone, tied down, you need sandspinner silk.\n\nThick, pliable, and not as sticky as you'd think.\n\nThis isn't a tailoring lesson. Omi's scouting report showed a lot of sandspinners inside the ruin courtyard. Get their silk and bring it back to me.", objectives = "Collect 6 Sandspinner Silks.", progress = "Don't even bother trying to tear it. You can't do it.", completion = "Not every treasure is gold, <name>. We vulpera have learned to recognize value wherever it hides in Vol'dun." }
