WordHunterWoW_QuestEN[48344] = { title = "We Have a Problem", description = "We have a problem, {name}. The Legion has come to Eredath.\n\nWhen you claimed the Sigil it was as if we announced our presence to all of Argus. The eyes of Antorus are firmly upon us.\n\nJust wait. It gets worse.\n\nVelen took Captain Fareeya and her forces into the Arinor Gardens area to search for the Crest of Knowledge. To my knowledge, they are all now behind enemy lines.\n\nCome with me to the Conservatory. We need to bring Velen and the others back before it is too late.", objectives = "Meet Turalyon at the Conservatory of the Arcane.", completion = "There is no room for error here, <name>." }
WordHunterWoW_QuestEN[48345] = { title = "Talgath's Forces", description = "I must continue to seek the Crest of Knowledge, my friend. Nothing short of the whole Crown of the Triumvirate can turn the tide in the battle we face.\n\nTalgath's forces stand between us and that goal. I will need you to clear a path.\n\nWe can let nothing stand in our way. Not even Talgath.", objectives = "Slay 12 of Talgath's forces.", completion = "<Velen does not seem to notice your presence.>" }
WordHunterWoW_QuestEN[48346] = { title = "Tracking Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[48347] = { title = "Anglepoint Wharf", description = "HELP WANTED.\n\nAn unidentified illness has cropped up in Anglepoint Wharf. Those experienced with medicine or healing should report to the Therold Wavestone at their earliest convenience.\n\nCitizens are advised against visiting Anglepoint on personal business until further notice.\n\nThank you for your cooperation.", objectives = "Meet Brother Therold at Anglepoint Wharf.", completion = "Oh! Are you here because of my posting?\n\nThank the sea, I need all the able-bodied help I can get." }
WordHunterWoW_QuestEN[48348] = { title = "Stinging Barbs", description = "The Outrigger hunters exhibit the pinnacle of Kul Tiran brawn. But they would indubitably be unable to succeed in taking down the most impressive of their prey without my own inventions!\n\nI present to you, the most ordinary of harpoons. However, with just a tad of gnomish ingenuity, this average weapon can become so much more! \n\nAll that I need are barbs from the rays in the harbor. Using them, I can fashion a poison that can stun even the most colossal of sea monsters!", objectives = "Collect 4 Venomous Barbs from Barbtail Stingrays.", progress = "Be careful with those stingers, <name>! They'd put someone of your frame down easily!", completion = "Well throw me a hammer and call me Nancy!\n\nThank you kindly pal. This should be plenty! I'll get to work!" }
WordHunterWoW_QuestEN[48349] = { title = "Work Order: Empyrium", description = "", objectives = "Are you here to deliver supplies?", progress = "Are you here to deliver supplies?", completion = "Thank you for assisting us, miner. We needed this empyrium badly." }
WordHunterWoW_QuestEN[48350] = { title = "Tracking Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[48351] = { title = "Tracking Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[48352] = { title = "A Cure from the Sea", description = "You may not believe it, but seaweed is one of the most important gifts the sea grants to us. Without it, my tonic shall be useless.\n\nI know it is much to ask, but can you go into the harbor and collect some for me? The water is tumultuous in this trying time, but I will give you my blessing.", objectives = "Collect 8 Bunches of Seaweed from Harbor Seaweed.", progress = "The sea cannot offer its guidance when it is in such pain. I feel as if one of my senses is blinded.", completion = "Glorious! This should be plenty." }
WordHunterWoW_QuestEN[48353] = { title = "Pulse of the Wharf", description = "I am at a loss for ideas, {name}. The tides churn, and I can feel their pain as if it is my own.\n\nWhile I am out of ideas, perhaps the merchants in town may have seen something? They are always watching and gossiping, making them quite good sources of information.", objectives = "Talk to Julian Nichols, Ginger Freelin, and Aaron Gutier in Anglepoint Wharf.", completion = "In the name of the sea! Did you see that?" }
WordHunterWoW_QuestEN[48354] = { title = "Tainted Shipments", description = "If one shipment was compromised, who knows how many of the others are.\n\nNearby, the fishpackers prepare shipments to be sent to the rest of Kul Tiras. We must check the rest of the shipments before this plague can spread!", objectives = "Check 5 Barrels of Fish.", completion = "I am... aghast. How could this happen right under our very noses?" }
WordHunterWoW_QuestEN[48355] = { title = "Evacuate the Premises", description = "The people of Anglepoint need me to stand tall, to not panic in the face of the unknown.\n\nI will admit to not being the best at this.\n\nEven now, the fishpackers are handling the tainted product and preparing it for shipment. They are in great danger, and we cannot allow them to stay in harm's way.\n\nWe must get them to safety!", objectives = "Evacuate 8 Anglepoint Fishpackers.", completion = "If there is even a chance of harm to innocents, we must protect them at all cost." }
WordHunterWoW_QuestEN[48356] = { title = "Possessive Headgear", description = "It is fortunate that we have found Alby. He has filled me in on the situation in the packing district.\n\nIt's not good, {name}.\n\nThe workers walk, yes. They work as if nothing is out of the ordinary, yet they are controlled by parasites. Mindstealers that force them to do their bidding.\n\nIt is they who contaminate the shipments.\n\nYou must destroy as many of those mindstealers as you can. Free the minds of the possessed!", objectives = "Kill 10 Parasitic Mindstealers controlling Possessed Dockworkers in the Anglepoint Packing District.", completion = "This has never been a simple illness. There is foul magic at work here." }
WordHunterWoW_QuestEN[48357] = { title = "Tracking Quest", description = "", objectives = "" }
