WordHunterWoW_QuestEN[48573] = { title = "Crocolisk Life", description = "I need my shaman mojo back if we are going to kill Urok. He beat me bad de last time I tried to put him down.\n\nYou help me get my power back, and I help you make Urok dead. Deal?\n\nFirst step, I need you to use dis dagger to absorb what is left of de life force of any crocolisk you kill.\n\nWhen de dagger seems full, come find me.\n\nHeh heh, dat's right Sur'jan. Dey gonna help us, den Urok will see who de strongest is!", objectives = "Absorb essence of 8 primal snapjaw corpses with Sur'jan's Ritual Dagger.", completion = "Ah, dat looks good! Dis will make de ritual go by real nice." }
WordHunterWoW_QuestEN[48574] = { title = "Pulling Fangs", description = "I need more things to help me get strong. I need you to get me some saurid teeth.\n\nNo, Sur'jan, you're not trusting him TOO much. Just enough. I won't be betrayed again.\n\nI need dese teeth for a ritual I'm gonna perform to help me get my power back. Once I'm not so weak, you and I are gonna take down dis undead monster.", objectives = "Recover 40 Saurid Teeth.", progress = "You got enough teeth for me?", completion = "Lemme count dem... good! Dis will work.\n\nShh, I said it will work, not dat we'd be done. Stop annoying me, Sur'jan!" }
WordHunterWoW_QuestEN[48576] = { title = "Safe Flying", description = "I'm feeling... stronger! But I need more power before we take down Urok.\n\nNo, Sur'jan, YOU are scared of Urok more than me. I'm not scared of nothing!\n\nYou got an attachment to me now after dat ritual. I need you to go kill de skyterrors nearby. Their deaths will fuel my strength.\n\nTake my grappling hook. You can drag de skyterrors down from de sky with it, and it'll put de hurt on dem too.", objectives = "Kill 8 Primal Skyterrors.", completion = "Good! I am feeling stronger already. De three of us make a good team." }
WordHunterWoW_QuestEN[48577] = { title = "Terrorizing their Eggs", description = "Sur'jan, I should be doing dis! What do you mean, I need to recover? Bah, fine.\n\nI need more power, and de skyterrors have eggs nearby. I need you to bash some of their eggs to fuel my energy.\n\nThose eggs got lots of life force in dem. You destroy dem, and I will feel de energy coming back to me.\n\nCome on, Sur'jan, dis will be easy! I can do dis! Hmph... well, you make a good point. You always were de smarter one out of us.", objectives = "Destroy 5 Skyterror eggs.", completion = "I feel better already! Maybe I should destroy more of those eggs in de future." }
WordHunterWoW_QuestEN[48578] = { title = "There's No Eye in Skyterror", description = "There's a real big skyterror dat I name Jarkadiax. I need his tongue...\n\nWhat's dat, Sur'jan? Not his tongue? His eye? You sure? Hrm.\n\nI need his eye for my next ritual. I know what you're thinking. De tongue makes more sense. Dat's what I--\n\nLook, Sur'jan, I still think it's his tongue. We'll see which of us is right!\n\nGo get Jarkadiax's eye and bring it back to me for de next ritual.", objectives = "Recover Jarkadiax's Eye.", progress = "I need dat eye. You get it yet?", completion = "You got de eye!\n\nI feel de power coming from dis thing. Can you see it?\n\nShut up, Sur'jan. I know YOU can see it, I was talking to him!" }
WordHunterWoW_QuestEN[48579] = { title = "Tracking Quest", description = "", objectives = "You will learn:" }
WordHunterWoW_QuestEN[48581] = { title = "A Good Spanking", description = "Pinky is contained in de direhorn pen for now, but de handlers are having a real hard time with him!\n\nDis calls for some tough love.\n\nWill you help dem?", objectives = "Help the handlers subdue Pinky.", completion = "You're certainly de talk of de kraal, <name>!\n\nDat Pinky will be great in battle when he grows up, don't you think?" }
WordHunterWoW_QuestEN[48584] = { title = "The Blood of My Enemies", description = "I feel my power returning, but we aren't done yet. We need more power to kill dis undead Urok.\n\nWe'll be pushing in to Urok's lair. Dreadticks are swarming in de area. I want you to bring me their blood for de final ritual.\n\nTake dis. It's my trusty dreadtick gasser. Throw it in de area, dreadticks sniff it... den DIE! Hahaha! Now get going!\n\n...Sur'jan, you keep telling me to let him do dis sorta work, but I could do it too! Fine, I'll just work on getting de ritual ready.", objectives = "Collect 45 Coagulated Dreadtick Blood.", progress = "You get me dat blood yet?", completion = "Dis will work. We are so close to getting my power back!" }
WordHunterWoW_QuestEN[48585] = { title = "Wasteland Survivor", description = "<The leather has become dry and cracked in the sun, but the supplies inside are mostly intact.\n\nIt's unknown what gruesome death befell the backpack's former owner, but supplies like these are in high demand among the outcasts.\n\nThe desert has claimed many lives... perhaps there are more supplies to be found among the dunes. >", objectives = "Collect 10 Scavenged Supplies.", progress = "What do you have for me?", completion = "I see you made a scavenging run and came back alive!\n\nWe will put these supplies to good use among the tribe. You have my thanks." }
WordHunterWoW_QuestEN[48588] = { title = "Purge the Infection", description = "", objectives = "" }
WordHunterWoW_QuestEN[48590] = { title = "My Head and Shoulders", description = "If we're going to fight Urok, I will need my gear back. It was all lost when I was running from Urok de first time.\n\nShut UP, Sur'jan! I had to ditch it in order to run faster.\n\nBring my gear back to me, and I'll be ready to fight Urok with you.", objectives = "Recover Sur'jan's head and shoulder gear.", progress = "You got my gear?", completion = "My gear! Ah, dey smell brand new, too. Did you clean dem?" }
WordHunterWoW_QuestEN[48591] = { title = "Urok's True Death", description = "This is it! My power is back; we are ready to put down Urok. He used to be a noble beast, you know. Big, strong.\n\nNow Urok is just a mindless undead. It isn't right. We'll put him to rest.\n\nI'm going to run up ahead. When you get near Urok, I'll hop out to ambush him. Let's do dis!\n\nShut up, Sur'jan. Of course we're going to win! If we don't, I'll just find another {class} to help me out.", objectives = "Defeat Urok.", completion = "We did it! Urok is gone for good. It was a shame to put him down, but dat sort of creature isn't supposed to be.\n\nI have lots of other things to do, like finding de two other trolls out here and killing dem.\n\nWhat do you think, Sur'jan? Should I tell him? No? Okay, fine.\n\nI'll be seeing you. Oh, and don't stay in Nazmir. Only crazy people come here." }
WordHunterWoW_QuestEN[48592] = { title = "Holding the Spire", description = "", objectives = "" }
WordHunterWoW_QuestEN[48597] = { title = "Saurolisk Escape", description = "You cautiously approach a saurolisk tied to a post. It doesn't snap at you, but looks at you with defeat in its eyes.\n\nThe troggs seem to be keeping these saurolisks against their will. They should be freed before they are abused further.", objectives = "Free 6 Trapped Saurolisks.", completion = "Troggs training saurolisks to be ridden? Seems they've learned from watching us after all.\n\nIt's better that you freed them. I don't particularly want to imagine what would happen if the troggs were widely successful in their new riding endeavors!" }
WordHunterWoW_QuestEN[48600] = { title = "Take the Edge Off", description = "The demons streaming out of Antorus equip themselves at Felfire Armory. We need to deny those weapons. Will your {class}s fight alongside the Army of the Light once again?\n\nBefore the assault, gather materials. My smiths will craft your soldiers more powerful armor. The Legion won't give up Felfire without a fight.", objectives = "Raise 6 Champions to 950 Item Level.", progress = "Make your preparations, <name>.", completion = "One step closer to defeating the Legion." }
WordHunterWoW_QuestEN[48601] = { title = "Felfire Shattering", description = "A thin series of stone bridges connects the Burning Breach to Felfire Armory over Fiend's Run. The Army of the Light will stem Legion reinforcements while your people deal with the armory itself.\n\nWork swiftly.", objectives = "Use the Scouting Map and complete the mission, \"Assault on Felfire Armory.\"", completion = "There's nothing more beautiful than a lightburst charge erupting in a Legion stronghold. Your people afforded themselves well." }
WordHunterWoW_QuestEN[48604] = { title = "Home Again, Home Again", description = "I can't thank you enough for the help here! You showed up just in time.\n\nHere is Elijah's sausage order. Don't worry, it's just regular sausage- nothing questionable.\n\nNow if you'll excuse me I have to see to my workers.", objectives = "Return to Elijah Eggleton in Fallhaven.\n\nProvided item:" }
WordHunterWoW_QuestEN[48605] = { title = "Commander's Downfall", description = "A champion of the Legion is vulnerable within an invasion point! Track it down and destroy it before it can return to fight on Argus.", objectives = "Complete a Greater Invasion Point scenario.", progress = "The Legion must fall.", completion = "Their commanders fall before us!" }
WordHunterWoW_QuestEN[48606] = { title = "Loaded for Bear", description = "<This glittering cannonball stands out from the others. You notice the familiar sheen of Azerite across the surface.\n\nYou can't help but notice the nearby cannon, conveniently pointed at the ships loaded with stores of Ashvane Company weapons.>", objectives = "Use the Ashvane Cannon to destroy 6 Ashvane Co. Supplies. Azerite Cannonballs are required to fire the cannon.", completion = "<Better to destroy these new weapons than to let them fall into the wrong hands.>" }
WordHunterWoW_QuestEN[48613] = { title = "Tracking Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[48614] = { title = "Woeful Implications", description = "", objectives = "" }
WordHunterWoW_QuestEN[48615] = { title = "War Never Changes", description = "", objectives = "" }
WordHunterWoW_QuestEN[48616] = { title = "Bolas and Birds", description = "Up in the mountains we know the value of a good hunting companion. We use bolas to shoot down our flying prey, then our retrievers go and bring us our kill!\n\nYou want to take a shot? Nickel can accompany you. Shoot down some of the falcons in the woods. My dog will finish the job.", objectives = "Shoot down 6 Hollowbeak Falcons with the Bola Launcher.", completion = "There's nothing like man and beast working together for a clean hunt!" }
WordHunterWoW_QuestEN[48620] = { title = "Greater Invasion Point: Mistress Alluradel", description = "", objectives = "You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[48622] = { title = "The Vanishing Lord", description = "Unfortunately, we don't have any contacts within House Waycrest, so our efforts in Drustvar will have to start from the ground up.\n\nWe have arranged for a ferry to take you to Fallhaven - a farming village in eastern Drustvar. The mayor there, Cyril White, is a longtime friend of the Proudmoores, and I think he can help us get in touch with someone from the house.\n\nI hope you can get to the bottom of their absence, {name}. Their martial might is invaluable to the Kul Tiran fleet.", objectives = "Meet with Cyril White in Fallhaven in Drustvar.", completion = "<The effigy is protected by powerful magic. \n\nIt seems it will take more than brute force to break this curse.>" }
WordHunterWoW_QuestEN[48624] = { title = "Who Let The Dogs Out?", description = "", objectives = "" }
WordHunterWoW_QuestEN[48627] = { title = "Tracking Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[48628] = { title = "Tracking Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[48629] = { title = "Tracking Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[48631] = { title = "Securing Krokuun", description = "Legion patrols are an ever-present threat. Eradicate demon commanders you encounter, and I will grant you a ridgestalker guide.You will receive:", objectives = "Slay 4 Rare Elites on Krokuun." }
WordHunterWoW_QuestEN[48632] = { title = "Void Extract", description = "The void calls to its own. \n\nWhen they are destroyed, powerful creatures of shadow leave behind vast amounts of undiluted void. It's lure is powerful enough to draw out the noxious influence polluting my brethren. Not all survive the purge, but the alternative is worse than death - you've seen the voidscarred roaming Oranaar.\n\nDestroy a powerful agent of shadow, collect its essence, and bring it to me. I will use it draw out the corruption.You will receive:", objectives = "Gather an Orb of Undiluted Void.The void calls to its own. \n\nWhen they are destroyed, powerful creatures of shadow leave behind vast amounts of undiluted void. It's lure is powerful enough to draw out the noxious influence polluting my brethren. Not all survive the purge, but the alternative is worse than death - you've seen the voidscarred roaming Oranaar.\n\nDestroy a powerful agent of shadow, collect its essence, and bring it to me. I will use it draw out the corruption.You will receive:" }
WordHunterWoW_QuestEN[48634] = { title = "Further Supplying Krokuun", description = "This desolate place offers little for my people. Every hour is spent scraping together enough to survive. If I had more supplies, I could offer you another ridgestalker.\n\nWhat say you, offworlder?", objectives = "Collect 900 Order Hall Resources.", progress = "You seek the aid of another ridgestalker?", completion = "You must value our aid greatly, to part with such a bounty." }
WordHunterWoW_QuestEN[48635] = { title = "More Void Inoculation", description = "All entities touched by shadow leave behind traces of void when they are defeated, If you collect enough in your travels through the city, return to me, and I will distill it into its undiluted form. \n\nWe can save more of my kin.", objectives = "Collect 100 Fragments of Condensed Void.", progress = "Many of my brethren are deeply touched by shadow. It will take a tremendous effort to free them. Will you help?", completion = "I am humbled by your generosity." }
WordHunterWoW_QuestEN[48636] = { title = "Fueling the Antoran Campaign", description = "The Legion requires raw materials from conquered words to fuel their crusade. Travel through Legion portals, destroy demons you encounter, and deny them the resources required to maintain their war machine.", objectives = "Complete 10 Invasion Points.", progress = "War is costly work. Have you gathered additional supplies for our efforts here?", completion = "Another lightforged to fight alongside your forces." }
WordHunterWoW_QuestEN[48637] = { title = "Cleansing Fire", description = "", objectives = "" }
WordHunterWoW_QuestEN[48639] = { title = "Army of the Light", description = "Assist the Army of the Light by completing 4 world quests.", objectives = "Complete 4 Army of the Light world quests on Argus.", completion = "The Army of the Light thanks you." }
