WordHunterWoW_QuestEN[48668] = { title = "Lightforged Beacon: City Center", description = "Hail, friend!\n\nCaptain Fareeya sent us ahead to secure this area. We were just about to call down a beacon and report back to the Vindicaar.\n\nWe would be honored if you would help us complete our mission.\n\nThe signal beacon just needs a light touch. The Grand Artificer will do the rest.", objectives = "Activate the Vindicaar Beacon.", progress = "Grand Artificer Romuul is a reliable soul. We would be lost on this planet without him.", completion = "This beacon will be added to the Navigation Console.\n\nA contingent of the Army of the Light will remain to hold this location for future use." }
WordHunterWoW_QuestEN[48669] = { title = "Urok, Terror of the Wetlands", description = "You! You can help me!\n\nI know, Sur'jan, he looks like a {class}, but I know we can trust him.\n\nUrok, de terror of de wetlands, is undead now. We have to put it down before it tries to destroy dis entire place.\n\nJust give me a minute, and you will see dat Urok is bad news.\n\nShhh, Sur'jan, dey gonna see, dey are all gonna see!", objectives = "See Urok, Terror of the Wetlands.", progress = "Just give me a chance and you'll see!", completion = "Now you see? We must beat Urok. I know how to do it, but I can't do it alone." }
WordHunterWoW_QuestEN[48670] = { title = "Runaway Rider", description = "Lord Norwington demanded I take Eddie out riding in the woods, but I knew it was too soon! I just knew it!\n\nWe've got to go find him. Meet me across the river!", objectives = "Meet Melissa Kenny near Mistfall Cleft.", completion = "How could this get any worse?\n\nThe troggs have captured Eddie!" }
