WordHunterWoW_QuestEN[48677] = { title = "Wicker Worship", description = "Hail, traveler! You look like just the sort who might be able to help me out with a predicament!\n\nIt's my son Edwin, you see. We were travelling through Drustvar to ply our wares when the damned fool ran off to join some cult here in Autumnvale! Since then we haven't seen a trace of him, and the brown-robed loons won't speak a word of his whereabouts!\n\nCould you see if you could persuade them to talk? His poor mother is worried sick!", objectives = "Meet Lord Autumnvale in Autumnvale.", completion = "What brings you to our valley, <class>?" }
WordHunterWoW_QuestEN[48678] = { title = "Questionable Offerings", description = "So the traders sent you? As I told them, I only discuss the happenings of our family with those who understand our cause.\n\nIf you wish to know his whereabouts, you must prove that you do.\n\nBehind us are several items gathered for offering to the Wicker Man. Bring us the items you feel will most appease it, so that it might give us its blessing.\n\nChoose the correct offerings, and we will know your intent.", objectives = "Bring the correct offerings to the Wicker Man in Autumnvale.", progress = "You must bring the correct offerings if you wish to show us your understanding.", completion = "Your offerings pleased the Wicker Man. \n\nVery well, ask your questions, <class>." }
WordHunterWoW_QuestEN[48679] = { title = "Mind the Hives", description = "The one called Edwin came to us not long ago, seeking to earn the blessings of the Wicker Man.  He wandered off into the hills looking for his own offering.\n\nUnfortunately, he managed to disturb one of the nearby beehives, causing the insects to become rather frenzied.\n\nThat was the last I saw of him, I'm afraid.", objectives = "Find Edwin Maldus in Barbthorn Ridge.", progress = "Yes?", completion = "You were the one looking for Edwin, weren't you!?\n\nYou must help him!" }
WordHunterWoW_QuestEN[48680] = { title = "Not the Bees!", description = "", objectives = "" }
WordHunterWoW_QuestEN[48682] = { title = "A Simple Sacrifice", description = "You must hurry! Lord Autumnvale brought Edwin off to that cave right when he returned, saying something about \"an offering of blood!\"\n\nI think they mean to sacrifice him to appease the Wicker Man!\n\nJust what kind of crazy cult is this?!", objectives = "Rescue Edwin Maldus from the Wickerite cultists in Autumnvale.", progress = "Help me!", completion = "Those cultists tried to kill me!\n\nI don't know about you, but I've had about enough of this Wicker Man business!" }
WordHunterWoW_QuestEN[48683] = { title = "Changing Seasons", description = "I appreciate you saving me again, but we should do something to prevent this from happening to anyone else.\n\nSo long as that Wicker Man stands, it will attract more like Autumnvale to it.\n\nWe should destroy it! Are you with me?", objectives = "Burn the Wicker Man in Autumnvale.", progress = "The Wicker Man must be destroyed!", completion = "Well I've certainly learned my lesson.\n\nThank you, friend. I will return to Boralus with my parents now.  \n\nHere, take this for your troubles." }
WordHunterWoW_QuestEN[48684] = { title = "On the Move", description = "Jorak's wounds have healed enough for him to travel.\n\nHe has agreed to guide us to de temple. \n\nDe sooner we leave, de better. Rakera won't survive in dis desert for long.", objectives = "Travel with Meerah's Caravan in search of Warguard Rakera.", completion = "Dis temple is not quite what I expected it to be." }
