WordHunterWoW_QuestEN[48699] = { title = "Sneaking into Zalamar", description = "I know you might think nothing has changed, but trust me, de voodoo worked... I think.\n\nYou should transform into one of de blood trolls when you are near Zalamar, one of their villages.\n\nJo'chunga should be dere somewhere, most likely near a large gathering of blood trolls.\n\nFind Jo'chunga and tell him I have sent you, den see what he knows about de situation dere.", objectives = "Sneak into Zalamar to find Jo'chunga.", completion = "Good, we will be safe in here. I am happy dat you are here, because I am not able to stop dis alone." }
