WordHunterWoW_QuestEN[48715] = { title = "Akunda Awaits", description = "I've spoken to every troll out here, asking if they've seen Rakera. As you might have guessed, Akunda is de only name dey know. \n\nLet's hope someone within de temple will be able to tell us something useful.", objectives = "Investigate the Temple of Akunda.", completion = "Dis is Rakera. I have no doubt. But for some reason, she does not remember me... or herself, it would seem..." }
