WordHunterWoW_QuestEN[48837] = { title = "All-Seer Xanarian", description = "", objectives = "" }
WordHunterWoW_QuestEN[48840] = { title = "Ruins-Level Marketing", description = "Now dat de Goldtusk Inn be open for business, we gotta make sure everyone in Vol'dun knows about it!\n\nI think we should focus on those wagon-riding vulpera first. Dey don't even have real homes!\n\nIn fact, I saw a pack of vulpera up at de ruins to de north de other day, and dey barely had anything.\n\nTake dem dis coupon and tell dem to stop by for a free first stay.", objectives = "Deliver the Goldtusk Inn coupon to Kenzou.\n\nProvided item:", completion = "<Kenzou looks skeptically at the leaf you handed him.>\n\nNo, I will not be going there. But are you looking for some real work?" }
WordHunterWoW_QuestEN[48846] = { title = "Liquid Motivation", description = "<Zauljin motions for you to come closer. He is clearly drunk.>\n\nIf I had information concerning Mojambo...<hick!>...how much would dat be worth to you?\n\nYou don't...<hick!>...believe me? Nobody suspects a drunk. I hear all sorts of things...\n\nWhat do you have to lose? All it will cost is a bottle of...<hick!>...Zanchuli Reserve!\n\nWhaddya say, mon?", objectives = "Bring a bottle of Zanchuli Reserve to Zauljin.", progress = "What do you have for me?", completion = "Mojambo is teaming up with an outside gang to attack us? I knew he meant business, but I didn't expect him to go dis far. We need to come up with a plan as soon as possible..." }
WordHunterWoW_QuestEN[48847] = { title = "Arming the Tribe", description = "We spotted some of Tongo's gang scouting de arena while you were away. It seems dis may be de calm before de storm.\n\nWe need to get de weapons you brought back from Tongo's hideout into de hands of our fellow outcasts. Mojambo's gang could attack any minute now.\n\nWe need to be prepared. Take de weapons and get dem to de unarmed members of de tribe.\n\nIf Mojambo thinks he can raid our home without a fight, he's got another thing coming.", objectives = "Arm 8 Scorched Sands Outcasts.", progress = "De time for war is nearly upon us.", completion = "It's a good thing you armed de tribe! Mojambo and his gang are attacking as we speak!" }
WordHunterWoW_QuestEN[48850] = { title = "Tongo", description = "If Mojambo hired Tongo's gang as reinforcements, we're in even more trouble than we first thought.\n\nTongo is a cruel and sadistic marauder who takes great delight in suffering. His gang is notorious for torturing their prey.\n\nWe won't be able to defend ourselves against both gangs at once. Our only chance of survival now is to strike first.\n\nIf you take out Tongo before de ambush, Mojambo will be expecting reinforcements dat never arrive. We may be able to use dat to our advantage...", objectives = "Retrieve Tongo's Head.", progress = "Has Tongo been defeated?", completion = "With Tongo out of de way, all we have to worry about now is Mojambo..." }
WordHunterWoW_QuestEN[48852] = { title = "Stopping Zardrax", description = "", objectives = "" }
WordHunterWoW_QuestEN[48853] = { title = "Terminal Degree", description = "That's everyone but Nigel.\n\nHe's in the big cave! I bet he went in there to look for relics, but now he's tied up!\n\nWould you save him too?", objectives = "Slay Cragg the Stoneshaker and free Nigel Rifthold.", progress = "Thanks! Negotiation is a lot harder than Brann's book makes it out to be.", completion = "Thank you for saving my grandson and his friends.\n\n I'm sure they will make fine explorers when they're adults.\n\nWhich will be about the time they are no longer grounded!" }
WordHunterWoW_QuestEN[48854] = { title = "Offer of Power", description = "Ah... a {class}. You must be {name}... I have heard whispers of your name. Maybe you are smarter than dese two.\n\nZuldazar will fall to de blood trolls. You know dis. \n\nYou can be saved, if you promise to serve me. I can give you more power than you have ever imagined.\n\nListen to what I can offer you...", objectives = "Listen to Zardrax's speech.", completion = "Zardrax be temptin' us ta join him, but dat ain't gonna work. We gonna stop dis lich and anyone else who wants ta help da blood trolls!" }
WordHunterWoW_QuestEN[48855] = { title = "Humbling the Terrors", description = "When we first got here, I be findin' a whole buncha problems on da other side a Zardrax's barrow. \n\nDere be dese monstrous zombies walkin' around da area. We gotta take 'em down ta make sure dey don't get ta Zuldazar.\n\nI used me voodoo ta be modifyin' dat fetish ya just found. Use dis new fetish ta weaken and kill dem zombies.", objectives = "Defeat 3 Reconstructed Terrors by weakening them with the Modified Blood Fetish.", completion = "Good work. We be savin' lots a people in Zuldazar from bein' crushed by dem zombies." }
WordHunterWoW_QuestEN[48856] = { title = "Conduit Interruption", description = "Dere be skeletons dat be funnelin' blood magic inta Zardrax's barrow. Me guess be Zardrax created dem ta help gather more power.\n\nYa gotta kill dese skeletons if ya want any shot at killin' dis lich. He should be gettin' weaker if he not be havin' dem as a source a power.\n\nI be stayin' here in da meantime ta be watchin' our backs, no tellin' if dere be blood trolls comin' ta attack us.", objectives = "Defeat 8 Zardrax Conduits.", completion = "I can be tellin' from here dat Zardrax's power be gettin' weaker. We close ta endin' dis." }
WordHunterWoW_QuestEN[48857] = { title = "All Hope is Lost", description = "I am not doing dis anymore! You and Da'jul are WRONG! Dere is no stopping Zardrax!\n\nI am leaving, and you cannot stop me. Zardrax will save us all from destruction and give us new power!", objectives = "Calm down Kal'dran.", progress = "Did ya find where Kal'dran ran off ta?", completion = "We got no time ta be mournin' Kal'dran. He made his choice, so now we be makin' ours ta defeat Zardrax." }
WordHunterWoW_QuestEN[48858] = { title = "Tracking Quest", description = "", objectives = "You will learn:" }
WordHunterWoW_QuestEN[48859] = { title = "Tracking Quest", description = "", objectives = "You will learn:" }
WordHunterWoW_QuestEN[48860] = { title = "Tracking Quest", description = "", objectives = "You will learn:" }
WordHunterWoW_QuestEN[48864] = { title = "The Broken Blacksmith", description = "{class}, I believe this may be a piece of the key to the Armory of the Triumvirate. We locked it behind us as we made our escape from Argus. The last time I saw it, my second in command, Atalaa, was leading a force to secure the armory. That was so long ago...\n\nI cannot be certain, but there may be another who would know. The smith who forged the key was called Gaal. With the reports of broken surviving on Krokuun, he may still live.", objectives = "Find the blacksmith Gaal.\n\nProvided item:", completion = "I am glad to hear Fareeya is well.\n\nShe is right... this is a fragment of the armory key I forged her so long ago." }
WordHunterWoW_QuestEN[48865] = { title = "Tracking Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[48866] = { title = "Void Warden Valsuran", description = "", objectives = "" }
WordHunterWoW_QuestEN[48867] = { title = "Chief Alchemist Munculus", description = "", objectives = "" }
WordHunterWoW_QuestEN[48869] = { title = "Payback's a Lich", description = "We can't be focusin' on da loss of Kal'dran. He be givin' up hope, and dat be someting we not gonna do.\n\nDis be da time ta strike at Zardrax. His power be waning. \n\nGo inta da heart of his barrow and destroy him, once and for all. Dat should show dem blood trolls who dey messin' with!\n\nI'd help ya, but I be weakened from da blood trolls dat be attackin' me when ya were gone. \n\nDon't worry 'bout me, I can still be handlin' dem animals if dey come back.", objectives = "Defeat Zardrax the Empowerer.", progress = "We need ta destroy Zardrax. Dis be our chance!", completion = "Ya did it! Zardrax be gone, and now da blood trolls be losin' a major source of their power.\n\nI be makin' my way back ta da camp ta let Princess Talanji know 'bout Kal'dran.\n\nShe deserves ta be knowin' dat he lost hope in our cause... might be good ta be seein' if anyone else is havin' doubts about what we be doin'." }
WordHunterWoW_QuestEN[48870] = { title = "The Many-Faced Devourer", description = "<The scroll's runes shift to a more intelligible form.>\n\nAn effigy. The Many-Faced One requires it.\n\nSteal from the Imps. Steal from the Fiends. Steal from the Ur'zul.\n\nHe comes.", objectives = "Collect bones from the Antoran Wastes to form a bone effigy." }
WordHunterWoW_QuestEN[48871] = { title = "Rescue the Relics", description = "According to the information you brought us, we should be adding those relics to our collection.\n\nExplore the ruins and see if you can find any of these \"tokens of affection\" the sethrak may have left for their Keepers. \n\nBetter we find hands that will cherish them, than ones that will destroy.\n\nPlus, add a little time, and anything becomes interesting... to the right people.", objectives = "Collect 8 Ahjani Relics in Zul'Ahjin.", progress = "Did you find the relics?", completion = "Perfect. The power of nostalgia is fascinating. These relics will hold great sentimental value. The monetary value won't be bad, either." }
WordHunterWoW_QuestEN[48872] = { title = "Expedite the Excavation", description = "Everywhere we go, there they are. Sethrak. And it's never the ones you want to see.\n\nIt seems they are looking for some key. With this new information, I do not think they are looking in the right place.\n\nReally, as entertaining as it is to confound them, we need to wrap up our work here and move on.\n\nIf you could remove some of them, it would greatly help our crew!", objectives = "Slay 12 Sethrak in the Ruins.", progress = "I need to mark this down. \n\nHow many sethrak have you killed?", completion = "Well done! They must be so irritated. This is great fun!" }
WordHunterWoW_QuestEN[48873] = { title = "A Grizzly End", description = "This lodge serves as the largest supplier of furs and leather to Boralus.\n\n<Kennings puffs out his chest a bit.>\n\nAnd as its proprietor, it is my duty to ensure every request is met on time. With recent delays, I've decided to take a trip out here to see if the Holtons need my assistance.\n\nWe could use any available hands! Take this knife and bring back some pelts from the bears in the nearby pass.", objectives = "Skin 6 Monstrous Grizzlies.", progress = "I see that Lord Kennings' idea of assistance hasn't changed since his last visit.", completion = "These furs appear to be in fine shape. Your skills should easily make up for any setbacks caused by 'accidents'." }
WordHunterWoW_QuestEN[48874] = { title = "Pardon Our Rust", description = "The traps we've set up in the field require routine maintenance checks. Some of them are fairly old and will spring at incorrect times. If only we could get more funding for these sort of supplies. \n\n<The huntmistress glances towards Lord Kennings.>\n\nWhile you're out hunting, could you reset any sprung ones that you find?", objectives = "Arm 5 Bear Traps.", completion = "It seems that you still have all of your limbs attached, and here I was hoping that I could talk Kennings into buying us new traps. Fair work." }
WordHunterWoW_QuestEN[48875] = { title = "Mix It Up", description = "", objectives = "" }
WordHunterWoW_QuestEN[48876] = { title = "Tracking Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[48877] = { title = "Tracking Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[48878] = { title = "Tracking Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[48879] = { title = "A Hunt for Hawk Eggs", description = "Before Alanna sends us on our grand hunt, there is something more immediate demanding our attention...\n\nI'm absolutely famished! No good man can hunt on an empty stomach.\n\nThere are hawks in the area, which means that there are also hawk eggs. I'm not sure how well they'll do in an omelet, but I'm always one for a culinary adventure!\n\nGood {class}, could you bring back a few before we get started?", objectives = "Gather 12 Hawk Eggs.", progress = "Have you found enough eggs yet? You know what those small goblins say, time is money!", completion = "Fantastic! Here's hoping that hawk eggs aren't too gamey..." }
WordHunterWoW_QuestEN[48880] = { title = "Mean Gulls", description = "Must... catch... Need more...\n\nThe gulls... they bite... scratch... take...\n\nI need them gone... but... I must... catch...", objectives = "Kill 10 Territorial River Gulls near Mudfish Lodge.", completion = "The gulls are... no more...\n\nNow... I can catch more...\n\nYes... catch more..." }
WordHunterWoW_QuestEN[48881] = { title = "The Reel Deal", description = "<These fishing rods must have been left behind when Art moved from the beach.  Most of them seem to have bites.\n\nMaybe you should reel them up and see what's hooked?>", objectives = "Reel in 5 Fishing Rods in Snapclaw Shore.", completion = "<That looks like the last of Art's rods.\n\nYou manage to salvage some of Art's bait with your catch. \n\nWaste not, want not>" }
WordHunterWoW_QuestEN[48882] = { title = "I Like Fish Guts and I Cannot Lie", description = "<It looks like some of the fish the gulls have been stealing from Art are still intact.\n\nHe'd probably be happy to get the innards from these as well.>", objectives = "Collect 9 Mudfish Innards from Intact Mudfish near Mudfish Lodge.", progress = "What's... this?", completion = "Yes... yeeesss...\n\nMore entrails... more innards... only the best..." }
WordHunterWoW_QuestEN[48883] = { title = "Big Gulls Won't Die", description = "Still one more... takes my bait... my fish...\n\nMy finger...\n\nKill him... you will be... rewarded...", objectives = "Kill Brinebeak in Mudfish Lodge.", progress = "Must... catch...", completion = "Is he dead?\n\nYes... now I can catch... and gut... and catch...\n\nMore entrails... only the best for the sisters..." }
WordHunterWoW_QuestEN[48884] = { title = "Tracking Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[48885] = { title = "Tracking Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[48886] = { title = "Tracking Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[48887] = { title = "Cleanse the Mind", description = "If you wish to invite Akunda into your mind, it can't be bogged down by fear or regret. \n\nMeditate at de Shrine of Thunder and confront whatever demons linger in de dark recesses of your mind.", objectives = "Meditate at the Shrine of Thunder and confront your inner demons.", progress = "Some who meditate at de shrine hear de voice of de loa himself, though most only hear silence or de sounds of their failings.", completion = "I can tell you found success. You are at peace." }
WordHunterWoW_QuestEN[48888] = { title = "It Springs Eternal", description = "Water is a sacred resource in dese dunes, but those within dis temple never know thirst. \n\nAkunda commands de storm, allowing de nearby spring to never run empty. \n\nUnfortunately, our eternal water source attracts a variety of animals dat are a plague upon our temple. \n\nRid de valley of their presence before you return.", objectives = "Kill Redrock Scavengers and Redrock Howlers near The Eternal Spring.", completion = "De spring is a gift from de loa and must be preserved at all costs." }
WordHunterWoW_QuestEN[48889] = { title = "Repairing the Past", description = "Dis explains why de loa has been silent. Akunda himself has forgotten who he is!\n\nSomeone or something must be abusing his power. \n\nWe won't know how to help without speaking to de loa.\n\nI can perform a ritual dat may repair Akunda's mind, but it is not without risk.", objectives = "Protect Meijani while she repairs Akunda's mind.", completion = "I seek your help, <name>." }
WordHunterWoW_QuestEN[48890] = { title = "How to Be a Blood Troll", description = "You will have to blend in if you don't want anyone getting suspicious. This won't be pretty.\n\nDere are drudges around de camp who have been tied up as part of a ritual. Dey get beaten as a test to make dem stronger.\n\nAny who fail de ritual are sacrificed. De ones who succeed are allowed to fight de Zandalari.\n\nIf you are going to blend in, you need to \"test\" dese drudges as part of de ritual. It's weird, but dat's how dey work.", objectives = "Test 5 Unproven Drudges.", progress = "It is not a pretty task, but dese trolls are not our allies.", completion = "Good work, nobody suspects a thing. Did any of dem crack under de pressure?" }
WordHunterWoW_QuestEN[48894] = { title = "Trial of Truth", description = "Those within our temple have left their past lives behind. They devote themselves entirely to Akunda. \n\nDis final test is perhaps de most important. \n\nDis is de moment of truth. \n\nYou will speak your name, as you will be known from dis day forth.", objectives = "Speak your name to Akunda the Exalted.", completion = "You have proven worthy of entering our temple, Akunda." }
WordHunterWoW_QuestEN[48895] = { title = "The Perfect Offering", description = "Dis offering is all dat I have to my name, but it wouldn't be right for me to use it for myself when I know your friend is in danger. \n\nShe saved my life, now I can save hers.\n\nTake de offering. Don't make me ask twice.", objectives = "Deliver the offering to Akunda the Exalted at the Temple of Akunda.", progress = "Do you come bearing gifts to our loa?", completion = "Dis is a generous offering, but a gift alone isn't enough to enter our temple. \n\nRedemption can't be bought, it must be earned. \n\nLucky for you, dere is much work to be done." }
WordHunterWoW_QuestEN[48896] = { title = "Knowledge of the Past", description = "An old friend of mine came to de sands willingly to gain knowledge of de past. \n\nIf anyone can locate dis weapon, it would be Julwaba. \n\nLast I heard, she planned to excavate de ruins surrounding de great pyramid.", objectives = "Travel with Meerah's Caravan in search of Julwaba.", progress = "How did Jarka'zet's men know where we'd be?", completion = "It's clear dat Jakra'zet won't stop until I'm dead." }
WordHunterWoW_QuestEN[48897] = { title = "The Bargain is Struck", description = "Now dat you have declared a patron loa for your time here in Zuldazar, you should inform de king of your decision.\n\nHe will appreciate dat you chose to follow de mighty Gonk.", objectives = "Speak with King Rastakhan.", completion = "So, you have chosen de path of Gonk. May de loa forever reveal de tracks of your enemies.\n\nFor myself, I follow Rezan, de devilsaur loa of kings. He and I have not spoken for many years, though.\n\nPerhaps I shall pay him a visit one of dese days." }
WordHunterWoW_QuestEN[48898] = { title = "Lucky Charm", description = "My daddy would never admit it, but he's really superstitious. I don't think he'll ever feel safe on a horse unless he has a lucky charm!\n\nI heard about a fox somewhere around here that's been eating a lot of chickens, and escaping everybody trying to catch him. I bet he's really lucky! Maybe if you got his tail and gave it to my dad, he'd feel lucky too!", objectives = "Collect Lucktail's Tail from Lucktail in Rockskip Falls.", progress = "Tails are real lucky, <name>. I think this one will give my dad heaps of courage!", completion = "I think I can feel the luck too!" }
WordHunterWoW_QuestEN[48899] = { title = "Safety First", description = "The connection between horse and rider is fascinating to me, and I will never truly understand until I experience it.\n\nBut, well, you know... armor! How could I possibly even think to mount one of these beauties without some proper protection?\n\nI saw some waterfalls nearby. There must be shells near the banks of its pools! Would you entertain an old Tortollan by collecting some for his safety?", objectives = "Collect 8 Durable Seashells in Rockskip Falls.", progress = "Protection, yes. Can't put yourself in a dangerous situation without the proper protection!", completion = "Ah yes, these shells will help keep me well safeguarded!" }
WordHunterWoW_QuestEN[48902] = { title = "Monstrous Energy", description = "Have you ever heard about eel juice? I don't know if it's safe for {race}s like you, but tortollans love it! It gives us a burst of energy, and puts a spring in the step of even the oldest tortollan.\n\nI saw some eels to the north of the estate when we were traveling. Can you go collect some of their venom for my dad?", objectives = "Collect 6 Pulsating Extract from Venomscale Slitherers in Rockskip Falls.", progress = "My dad will be so excited when he sees his favorite drink!", completion = "Oh boy oh boy! He's gonna be pumped!" }
WordHunterWoW_QuestEN[48903] = { title = "The Perfect Horse, of Course", description = "With all that you've collected for me... I guess it is time to mount, isn't it?\n\nHoo! I haven't felt such nerves for three hundred years! Would you mind assisting me in finding a suitable equine partner? I could not trust myself to make the decision alone!", objectives = "Assist Majo in choosing and mounting a horse.", progress = "My dad thinks horses can have lots of personalities, just like us. We gotta find him the perfect horse for his first ride!", completion = "He's on! He's on!\n\nDon't worry, <name>. I'm sure he'll be fine! Thanks for all of your help!" }
WordHunterWoW_QuestEN[48904] = { title = "Take the Bait", description = "The bait... almost gone now... must catch...\n\nThe crabs... find them... get more...", objectives = "Collect 15 Snapclaw Meat from Snapclaw crabs in Snapclaw Shore.", progress = "Almost gone...", completion = "Yes... more meat!\n\nI must not... can not... stop!" }
WordHunterWoW_QuestEN[48905] = { title = "Unappreciated Scrolls", description = "Since you're here in Natha'vor, you might as well help out the rest of the pilgrimage with a problem.\n\nThese trolls have stolen several of our scrolls. Why they would, I have no idea, I doubt they're smart enough to even read.\n\nI want you to get them back. I'm not young anymore, I can't just be casting magic off the top of my head! \n\nEspecially healing magic... which I'm sure Shoak is going to need when you rescue his dumb shell.", objectives = "Recover 8 Tortollan Scrolls." }
WordHunterWoW_QuestEN[48906] = { title = "Tracking Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[48909] = { title = "Noble Responsibilities", description = "From the state of this body, I would say a beast with formidable claws or fangs ravaged this camp. You say the trail leads westward? This camp usually houses more than one of Alanna's hunters. I wonder if they are tracking the beast down as well.\n\nHurry it up! I don't want to spend the day waiting around. Track our dangerous quarry!", objectives = "Track and kill the murdering monster.", completion = "Thank you for dealing with the threat. I'll see that the men who died out there have a proper send off." }
WordHunterWoW_QuestEN[48910] = { title = "Supplying Krokuun", description = "This desolate place offers little for my people. Every hour is spent scraping together enough to survive. If I had more supplies, I could offer you another ridgestalker.\n\nWhat say you, offworlder?", objectives = "Collect 150 Order Hall Resources.", progress = "This desolate place offers little for my people. Every hour is spent scraping together enough to survive. If I had more resources, I could offer you a ridgestalker.\n\nI can only part with a Krokul-Ridgestalker for this few resources once per week. Next week, I will offer you this trade again.", completion = "What say you, offworlder?" }
WordHunterWoW_QuestEN[48911] = { title = "Void Inoculation", description = "All entities touched by shadow leave behind traces of void when they are defeated, If you collect enough in your travels through the city, return to me, and I will distill it into its undiluted form. \n\nWe can save more of my kin.", objectives = "Collect 100 Fragments of Condensed Void.", progress = "If you bring the necessary supplies, I can begin the distillation process, <name>.\n\nI can only free one of the Void-Touched with this few resources once per week.", completion = "Another soul freed from the cruelty of the void." }
WordHunterWoW_QuestEN[48912] = { title = "Supplying the Antoran Campaign", description = "The Legion requires raw materials from conquered words to fuel their crusade. Travel through Legion portals, destroy demons you encounter, and deny them the resources required to maintain their war machine.", objectives = "Complete 10 Invasion Points.", progress = "The campaign against the Legion has taxed our existing resources heavily. Bring me supplies and I will place a lightforged under your command.\n\nI can only spare a lightforged for this few resources once per week.", completion = "A lightforged soldier can wade through a sea of demons. They will serve you well." }
WordHunterWoW_QuestEN[48913] = { title = "Monalite Deposit - Rank 1 Unlock", description = "Amazed that anything so pure could continue to grow on this planet, you pick flower from the ground. You feel a small power radiate from it and then vanish.\n\nAs it falls apart in your hands, you wonder if anyone on this Light-forsaken place knows how to handle this precious herb.", objectives = "Find someone on Argus who might be able to train you on how to handle Astral Glory." }
