WordHunterWoW_QuestEN[49058] = { title = "One-of-Many", description = "", objectives = "" }
WordHunterWoW_QuestEN[49059] = { title = "The Bones of Xibala", description = "Our allies in the Explorers' League have alerted us to an exciting find. They have set up camp in the Xibala region of Zuldazar.\n\nMake your way to the camp and help them uncover anything that may advance our cause.", objectives = "Travel to Xibala and meet with Acadia Chistlestone.Our allies in the Explorers' League have alerted us to an exciting find. They have set up camp in the Xibala region of Zuldazar.\n\nMake your way to the camp and help them uncover anything that may advance our cause.You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[49060] = { title = "Xibalan Ecology", description = "I want to take me boys out and really dig our picks in, but every scout I've sent into the ruins just came back half mauled to death.\n\nSome didn't come back at all.\n\nFrom what I can tell, the ruins are home to more'n just these spiky grass-eaters. Do you think you could be a peach an' thin their numbers a bit?\n\nI'd caution ye against tamperin' with the local ecology an' all, but in the interest of not gettin' eaten I think I'll let ye make the call.", objectives = "Slay 12 Xibalan predators.", completion = "Glad it weren't me, but here's a nice little reward for yer trouble!" }
WordHunterWoW_QuestEN[49064] = { title = "Torga, the Turtle Loa", description = "Name's Lashk.  We're not here to join any cause, we just want to hear Torga's legendary stories.\n\nI don't know if he'll help, but you can try persuading Torga, loa of the turtles, and see if he'll help you fight these blood trolls.\n\nYou can join on our pilgrimage to Torga, just keep quiet. Follow the path and find Kisha, she'll tell you where to go.", objectives = "Follow the tortollan pilgrimage path to reach Torga, loa of the turtles.", completion = "Dis is de work of de blood trolls, I am certain of it. We will get to de bottom of dis." }
WordHunterWoW_QuestEN[49066] = { title = "Encase of Emergency", description = "The cliffs here are well known for the crystal clear ice which forms at their base, and even more so for the elementals that are responsible for such. The hunters in my lodge use shards from the primal bodies to keep their stock frozen for transport. \n\nMore importantly, think of how useful it could be for making and serving drinks!\n\nLet's see if we can't find some elementals and gather shards from them.", objectives = "Collect 20 Pristine Ice Chunks from ice elementals.", progress = "I've heard that destroying some of the larger ice structures in the area angers them, so do what you do best and destroy any that you come across!", completion = "Perfectly chilled drinks, here I come! And there is enough for the hunters here too." }
WordHunterWoW_QuestEN[49067] = { title = "Beseeching Bwonsamdi", description = "We must talk to Torga's spirit and find out what exactly happened here... and how we can stop it.\n\nHrm, you mentioned dat you are linked to Bwonsamdi now.\n\nIt is time to test dat link. We need Bwonsamdi to get us Torga's spirit.", objectives = "Summon Bwonsamdi to ask for his help.", progress = "We must get started summoning Bwonsamdi.", completion = "For better or worse, we have Bwonsamdi's aid. Let us get to de killing." }
WordHunterWoW_QuestEN[49068] = { title = "Quelling the Cove", description = "", objectives = "" }
WordHunterWoW_QuestEN[49069] = { title = "WANTED: Ol' Frostclaw", description = "Old Frostclaw has once again been spotted near the edge of the pass. Hunters in the area are advised to keep caution. This larger than average bear has killed four people to date, I'd hate for you to make it a fifth. \n\nAny individual who kills the beast will be rewarded, regardless of their occupation.\n\n-Alanna  \n\n<Below the huntmistress' signature is a child's drawing of a bear with the words \"Ol' Frostclaw\" above it.>", objectives = "Slay Old Frostclaw.", progress = "Is this about the wanted sign? You better hurry, a good number of hunters are after it as well.", completion = "I'll let the hunters know they were beaten to the kill by a passerby. That should humble some of them." }
WordHunterWoW_QuestEN[49070] = { title = "Souls for the Death Loa", description = "Dere be blood trolls swarmin' all over dis place. Dey really be pickin' Torga clean, even eatin' his meat.\n\nDat be dark, even for me. \n\nDa souls of dese blood trolls be corrupted by eatin' a loa. Somethin' ya should be rememberin' for future reference.\n\nDese souls be worth a lot ta me, more dan just da normal souls of dese blood trolls. \n\nGet me da corrupted souls of dese blood trolls and I be callin' da spirit of Torga to ya.", objectives = "Claim 10 blood troll souls within Torga.", progress = "Ya haven't killed enough blood trolls!", completion = "Good! I be collectin' all their souls now." }
WordHunterWoW_QuestEN[49071] = { title = "Dreadtick Combustion", description = "This whole thing is crazy, you know that? I don't think any story can top this one...\n\nBah! Do you hear that insufferable sound?\n\nIt's those stupid dreadticks sucking on Torga's meat. Makes my skin crawl! \n\nWhat? You can't hear it? Meh, trust me, they're around, and they need to be taken care of.\n\nHere, take this scroll. We've had to deal with these dumb insects in the past. Read it near them and it'll cause them to explode.", objectives = "Blow up 5 Dreadtick Leechers with Lashk's Scroll of Combustion.", progress = "Blow those dreadticks up! Less of them overall is good for existence.", completion = "I can rest a little easier knowing there are fewer of those... things in the world." }
WordHunterWoW_QuestEN[49072] = { title = "Westward Noble", description = "While I am loath to involve you in this further, I don't have the men to afford an escort for Lord Kennings. If he gets hurt, we'll all be out of a job. Can you make sure he at least made it to the west camp?", objectives = "Find Lord Kennings.", completion = "Oh, you finally made it! I think we have more pressing matters on our hands than hunting deer." }
WordHunterWoW_QuestEN[49073] = { title = "Ritualistic Denial", description = "I can't believe we're dealing with a death loa, a DEAD loa, and blood trolls. This isn't what I had planned today!\n\nLook, some of the other tortollans have said there are some blood rituals going on. They were spooked and started heading for the coast when they saw it.\n\nTake this scroll and read it near any blood rituals. It should cause it to disperse.\n\nBe careful with my scroll! It's old and they don't make them like they used to.", objectives = "Disrupt 3 blood rituals with Kisha's scroll of purging." }
WordHunterWoW_QuestEN[49075] = { title = "Antorus, the Burning Throne: Dark Passage", description = "Despite the dangerous energies pulsing out from the heart of Argus, the Soulhunter travels unhindered through the Burning Throne. Our scouts report that his vessel harnesses the power of demonic runes to safely reach the Hallowed Felworks.\n\nIf we obtain those runes, it would allow the Vindicaar to follow the same route. This could save our forces valuable time.", objectives = "Collect 4 Runes of Passage from Imonar the Soulhunter in Antorus, the Burning Throne on Heroic Difficulty.", progress = "Without the runes, we must face Sargeras' army head on.", completion = "Magnificent work!\n\nOnce these runes are integrated into our shielding matrix, the Vindicaar will be able to bypass the Burning Throne's defenses and strike directly at the felworks." }
WordHunterWoW_QuestEN[49076] = { title = "Antorus, the Burning Throne: Dark Passage", description = "Despite the dangerous energies pulsing out from the heart of Argus, the Soulhunter travels unhindered through the Burning Throne. Our scouts report that his vessel harnesses the power of demonic runes to safely reach the Hallowed Felworks.\n\nIf we obtain those runes, it would allow the Vindicaar to follow the same route. This could save our forces valuable time.", objectives = "Collect 4 Runes of Passage from Imonar the Soulhunter in Antorus, the Burning Throne on Mythic Difficulty.", progress = "Without the runes, we must face Sargeras' army head on.", completion = "Magnificent work!\n\nOnce these runes are integrated into our shielding matrix, the Vindicaar will be able to bypass the Burning Throne's defenses and strike directly at the felworks." }
WordHunterWoW_QuestEN[49077] = { title = "Moments of Reflection", description = "<The crystal calls to you, resonating with sorcerous magic.\n\nAs you take hold of it, you hear the echo of a message left behind, a duty Illidan entrusted to you.>", objectives = "Bring Illidan's crystal to the people and places closest to him." }
WordHunterWoW_QuestEN[49078] = { title = "Poisoning the Brood", description = "Now we have room for our plan to kill Hir'eek. You see, {name}, my specialty is in making potions and poisons.\n\nI am working on a poison to use on Hir'eek, when de time comes. I have no idea if it will work or not.\n\nI want you to take what I already made and use it on de bats around here. It should kill dem instantly. \n\nIf it works, den I can make it stronger with my voodoo and give us a chance at killing Hir'eek.", objectives = "Use the Poisoned Mojo Flask to Poison 5 Tamed Warspawn.", progress = "Did you poison de bats yet?", completion = "I knew my poison would work! I just need to put a bit more of my voodoo in dere for it to be ready for Hir'eek." }
WordHunterWoW_QuestEN[49079] = { title = "Hir'eek, the Bat Loa", description = "Hir'eek knows we are here. If my knowledge of Hir'eek is correct, he will personally kill us after we present ourselves.\n\nIt is time, den. You and I will walk out dere into a horde of blood trolls who want to watch their loa kill us.\n\nTake dis dagger. It is coated with de poison I made. I trust you to survive longer than me to use it.\n\nYou pretend to cower to Hir'eek, and I will do de talking. On my signal, you jump on Hir'eek and start stabbing!\n\n...And den we hope for de best.", objectives = "Face Hir'eek with Jo'chunga.", completion = "<Cough> Well... at least my spine wasn't snapped." }
WordHunterWoW_QuestEN[49080] = { title = "Cease all Summoning", description = "I feel something dark and powerful being summoned in de husk of Torga. You need to stop it!\n\nDere must be a summoner using Torga's blood to finish a ritual.\n\nDo what you can to stop dem. I will stay here to keep dese tortollans safe from de blood trolls.", objectives = "Kill Summoner Yarz.", progress = "Did you kill dat summoner?", completion = "We are too late? Den we can only hope Torga can help us destroy... whatever it is dat you saw." }
WordHunterWoW_QuestEN[49081] = { title = "To Kill a Loa", description = "I am badly hurt... I don't think I can move. Don't worry, I have some potions dat can heal me... slowly.\n\nHir'eek is just down de cavern dere. De poison injured him, but he is a loa, and it will take more than dat to take him down.\n\nI can't believe we... YOU are going kill a loa. It's just not someting we do... but Hir'eek serves G'huun. We have no choice! \n\nIt's all up to you, now. Kill Hir'eek and end dis madness!", objectives = "Defeat Hir'eek, the loa of bats.", progress = "Hir'eek still lives! Go kill him!", completion = "I know. It is done. Hir'eek is dead. Nazmir is a cursed place, <name>. We never were meant to kill a loa... but here we are." }
WordHunterWoW_QuestEN[49082] = { title = "Upward and Onward", description = "It is sad dat Hir'eek had to die, but at least de blood trolls are weaker now.\n\nMy potions are healing me up nicely. I did some looking around and came across dis guy.\n\nHe's skittish, but not hostile. I think you can use him to get out of here.\n\nHurry up and jump on, before he breaks de rope! I'll find my own way out; you don't have to worry.", objectives = "Return to Zo'bal Ruins and inform Witch Doctor Kejabu as to what happened.", progress = "Hurry up, dis guy is strong!", completion = "Sorry. You did what you had to do... I can't believe dat dis G'huun could  corrupt a loa, of all things.\n\nNazmir is a cursed place... for everybody." }
WordHunterWoW_QuestEN[49091] = { title = "Invasion Point: Val", description = "", objectives = "You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[49096] = { title = "Invasion Point: Naigtal", description = "", objectives = "You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[49097] = { title = "Invasion Point: Sangua", description = "", objectives = "You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[49098] = { title = "Invasion Point: Cen'gar", description = "", objectives = "You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[49099] = { title = "Invasion Point: Bonich", description = "", objectives = "You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[49120] = { title = "Speaking with the Dead", description = "Ya be livin' up ta ya part of da bargain. I be ready ta show ya what remains of Torga's soul. \n\nI gonna need a little part of ya ta act as a conduit ta be summonin' Torga. Don't worry, I be givin' ya all back.\n\nMostly.\n\nAfter we be done, I be headin' out. Ya always welcome ta call on me again... but only if ya got another deal ready.", objectives = "Ask Bwonsamdi to summon Torga's spirit.", progress = "Ya ready ta speak ta Torga's spirit?", completion = "We may not have Torga's aid, but we can stop whatever de blood trolls are planning." }
WordHunterWoW_QuestEN[49122] = { title = "A Port in Peril", description = "A group of mogu have taken hold of Warport Rastari and now threaten to encroach further into my city.\n\nIt would seem Zul is losing his grip over his pets. \n\nDat port is vital to our military fleet. If de brutes succeed, Zuldazar will fall, and dere won't be a fleet to aid your precious Horde.\n\nYou wish to prove yourself an ally of de Zandalari? Meet my blade and shield at de port and clean up dis mess.", objectives = "Meet Habutu and Zolani at Warport Rastari.", completion = "Things are worse than we thought.\n\nMuch worse." }
WordHunterWoW_QuestEN[49123] = { title = "Killer Crawgs", description = "You heard Torga. We need to be taking de fight to de blood trolls if we want to stop dis herald of G'huun.\n\nDe blood trolls have monstrous crawgs in a camp nearby. We destroy dem, we weaken de blood trolls! \n\nDe rest of us will move ahead to find out what else de blood trolls have planned around dis place.", objectives = "Kill 12 Blood Crawgs or their riders." }
WordHunterWoW_QuestEN[49124] = { title = "Tortollan Rescue", description = "If Torga wants us to help you kill the herald of G'huun, then I guess we'll help. First, we need to rescue our people.\n\nI found out that the blood trolls are draining the blood of our friends nearby and then feeding them to crawgs! \n\nThis is no way for a tortollan to die, not after hundred of years gathering stories on Azeroth. \n\nTake this scroll. It'll purge whatever blood magic the blood trolls using on my friends.\n\nBe careful with my scroll! I want it back in one piece.", objectives = "Rescue 6 Tortollan Captives from the blood trolls using Lashk's Scroll of Purging." }
WordHunterWoW_QuestEN[49125] = { title = "Negative Blood", description = "Okay, you want to kill the herald of a blood god? We can figure something out.\n\nThere's corrupted blood nearby that's feeding this monster's power. Lucky for you, I've heard stories of this sort of thing before.\n\nTake this scroll, but be careful with it! It'll destroy the corrupted blood that's feeding Jungo.\n\nOh, and I need you to find a scroll Holbruk was carrying, called the Scroll of Fate's Hand. It's REALLY powerful. We'll need it.", objectives = "Destroy 8 Corrupted Loa's Blood with the Scroll of Purification and recover the Scroll of Fate's Hand.", progress = "Did you get that scroll and deal with the corrupted blood?", completion = "Good! Looks like that herald was weakened by what you did, and you got the scroll! Be careful, it's ancient! \n\nHolbruk always talked about how powerful that scroll was. We're going to see if he was right." }
WordHunterWoW_QuestEN[49126] = { title = "Forcing Fate's Hand", description = "I got some good news and bad news for you about this whole quest to destroy the herald of G'huun. Bad news first.\n\nThere's an entire army of skeletons between us and the next area. I'm guessing they used Torga's blood to animate them.\n\nGood news is that scroll you recovered from Holbruk can summon the powerful Hand of Fate.\n\n...and the bad news is that the scroll got damaged when Holbruk died and is only good for one more use.\n\nMeh. Take this scroll and destroy that skeleton army!", objectives = "Use the Scroll of Fate's Hand to summon the Hand of Fate to destroy 50 undead along the Blood Coast.", completion = "I saw the destruction from here! Hrm, maybe I should try to fix that scroll up, you know, for future use." }
WordHunterWoW_QuestEN[49130] = { title = "Loa-Free Diet", description = "Princess Talanji thinks we're almost ready to kill this herald of G'huun. Maybe she's right, maybe we're all dead, who knows?\n\nWhat I do know is the blood trolls here are... are carving and carrying away parts of Torga. Ugh!\n\nFrom what I can tell, they're using poor Torga's meat to power their blood rituals. This has to stop!\n\nGo out there and steal those pieces of meat from the blood trolls. I'll figure out a way to dispose of it.", objectives = "Recover 6 Parts of Torga from the blood trolls.", progress = "You... get that loa meat yet?", completion = "This is no way for Torga's remains to be treated, <name>. I'll make sure this is properly destroyed." }
WordHunterWoW_QuestEN[49131] = { title = "Sanctifying Ground", description = "We are so close to weakening dis herald, {name}. Dis is our final push. De nearby area is brimming with blood magic.\n\nWhile you were fighting, I was working on creating totems dat can cleanse de area of blood magic.\n\nTake dese totems and place dem nearby. Dey should drain some of de blood magic out of de area.\n\nDe herald should be weak enough for us to actually kill after all dis.", objectives = "Place 4 Sanctifying Totems down in the area.", progress = "Have you put de totems down yet?", completion = "De blood magic is dissipating from dis place. It is time for us to strike, before de blood trolls gain any more advantages." }
WordHunterWoW_QuestEN[49132] = { title = "Crushing the Skullcrushers", description = "Look, {name}, I'll be happy once we've killed this herald and we can have things go back to normal.\n\nUntil then, you need to deal with these monstrous blood trolls called \"skullcrushers\". Lovely, right?\n\nAs far as I can tell, these things have some sort of connection to this herald, might be why they're so huge.\n\nYou kill these skullcrushers and maybe we weaken this herald a bit more. Or maybe it gets even angrier and kills us all. \n\nWe'll have to see.", objectives = "Kill 4 Blood Skullcrushers.", progress = "Those skullcrushers aren't going to kill themselves.", completion = "Princess Talanji was saying something about feeling the blood magic dissipating from inside of Torga. I sure hope she's right." }
WordHunterWoW_QuestEN[49133] = { title = "Antorus, the Burning Throne: The Heart of Argus", description = "Hatuun tells me that after Argus fell, Sargeras ordered a temple of darkness to be built deep within the planet's core. Little is known of it, for only the titan's most devoted acolytes are given sigils that permit entrance.\n\nIf we lay claim to these sigils, they could be infused into the Vindicaar. This would allow our forces to stage a direct assault upon the fetid heart of Argus.", objectives = "Collect 4 Sigils of the Dark Titan from Aggramar in Antorus, the Burning Throne on Normal Difficulty.", progress = "Have you located the sigils?", completion = "With these sigils, the Vindicaar can bypass the Burning Throne's defenses.\n\nThe time has come to press our advantage and end this war." }
WordHunterWoW_QuestEN[49134] = { title = "Antorus, the Burning Throne: The Heart of Argus", description = "Hatuun tells me that after Argus fell, Sargeras ordered a temple of darkness to be built deep within the planet's core. Little is known of it, for only the titan's most devoted acolytes are given sigils that permit entrance.\n\nIf we lay claim to these sigils, they could be infused into the Vindicaar. This would allow our forces to stage a direct assault upon the fetid heart of Argus.", objectives = "Collect 4 Sigils of the Dark Titan from Aggramar in Antorus, the Burning Throne on Heroic Difficulty.", progress = "Have you located the sigils?", completion = "With these sigils, the Vindicaar can bypass the Burning Throne's defenses.\n\nThe time has come to press our advantage and end this war." }
WordHunterWoW_QuestEN[49135] = { title = "Antorus, the Burning Throne: The Heart of Argus", description = "Hatuun tells me that after Argus fell, Sargeras ordered a temple of darkness to be built deep within the planet's core. Little is known of it, for only the titan's most devoted acolytes are given sigils that permit entrance.\n\nIf we lay claim to these sigils, they could be infused into the Vindicaar. This would allow our forces to stage a direct assault upon the fetid heart of Argus.", objectives = "Collect 4 Sigils of the Dark Titan from Aggramar in Antorus, the Burning Throne on Mythic Difficulty.", progress = "Have you located the sigils?", completion = "With these sigils, the Vindicaar can bypass the Burning Throne's defenses.\n\nThe time has come to press our advantage and end this war." }
WordHunterWoW_QuestEN[49136] = { title = "Jungo, Herald of G'huun", description = "Dis is it, {name}. De blood magic is weakened enough dat we can actually hurt de herald of G'huun.\n\nIt is going to take all of us fighting dis thing to stop it. We will meet you inside of Torga. \n\nWe cannot lose here. If de blood trolls control Torga's blood, den dere will be no way for us to stop dem.", objectives = "Defeat Jungo, Herald of G'huun.", completion = "It is done, <name>. De blood trolls no longer have de blood of Torga as a resource to fuel their army.\n\nI know we were hoping to have Torga's aid, but at least we stopped de blood trolls.\n\nWe must find Rokhan and de others, along with Krag'wa, if he is still alive.\n\nEh? It looks like Lashk wants something..." }
WordHunterWoW_QuestEN[49138] = { title = "Captain Gulnaku's Treasure", description = "<This map is poorly drawn and covered in stains, but appears to identify three possible locations where a pirate captain may have buried treasure around the Port of Zem'lan. The treasure could be at any of the three locations.\n\nAt the bottom of the map, someone scrawled an order: Set traps!>", objectives = "Search for Captain Gulnaku's treasure chest.", progress = "<It's firmly locked. You'll need the captain's key to open this.>", completion = "<The chest is filled with shiny treasure.>" }
WordHunterWoW_QuestEN[49139] = { title = "An Army's Arsenal", description = "It's my job to scout out the ruins to identify threats and figure out the best way in.\n\nTwo storehouses contain the majority of the valuable weaponry in the ruins.\n\nUnfortunately, they're guarded by specters, powerful Zandalari spirits bound to this place.\n\nI... we need those weapons. Take out the specters so I... we can get to them.", objectives = "Kill the specters of Mugabu and Jam'jen, so Omi can ransack the storehouses.", completion = "You and I make a good team, <name>.\n\nHave a little extra reward, on me." }
WordHunterWoW_QuestEN[49141] = { title = "Diplomacy and Dominance", description = "May I entrust you with my staff, {name}? I do not offer this lightly, so do not accept it lightly either.\n\nWe will need every advantage when we face Emperor Korthek, and I've identified an opportunity to increase the power at our disposal.\n\nThe Faithless maintain a series of suppression spires on the ridge above us to subjugate the pterrordax. My staff can drain power from the spires to bolster its own potency.\n\nMeanwhile, I will recruit a much-needed ally for the next stage of our mission.", objectives = "Use Vorrik's Staff to drain power from 6 Faithless Suppression Spires.", completion = "<Vorrik smiles as he takes the staff back from you.>\n\nThank you, <name>. I must confess I was anxious for your return. It's been many years since this staff has left my side.\n\nMy trust in you was well placed, however. The staff is practically rippling with power." }
WordHunterWoW_QuestEN[49143] = { title = "Essence of the Light Mother", description = "This is a crucial moment, {name}. Our campaign must not lose momentum.\n\nThough she has fallen, I still sense Xe'ra's presence all around us. The Light that shone within her heart can yet be a source of strength for our cause.\n\nNo doubt the loss of Xe'ra has deeply wounded Turalyon. I will do what I can to ease his troubled spirit while you gather the vestiges of the naaru that remain.", objectives = "Collect 3 Vestiges of Light.", progress = "Though Xe'ra is gone, her essence can still aid us in our struggle.", completion = "Ah yes, I sense the Light within these fragments. Do not lose hope, <name>!" }
WordHunterWoW_QuestEN[49144] = { title = "Wrath of the Zandalari", description = "Dere is no reasoning with de mogu. Dey only value one thing: strength.\n\nDat is something de Zandalari have like no other, but our forces are spread thin. We are simply not prepared to fight dem.\n\nYou have proven yourself a capable warrior, for a {race}. Would you be our \"ambassador\" to dese brutes? Show dem dat de Zandalari do not stand alone!", objectives = "Slay 8 Kao-Tien Marauders, Subjugators, or Charged Sentinels.", completion = "You fight well, but our work is far from over." }
WordHunterWoW_QuestEN[49145] = { title = "No Troll Left Behind", description = "Dis is de primary port for de Zandalari fleet. Thankfully most of our ships were out when de mogu came, but Rastari is still an active fortification for de city.\n\nDe mogu did not land on abandoned shores, {class}. Dere are all manner of brave warriors stationed here, fighting for their lives.\n\nTake dis whistle and rally all you can. Our warriors will hear its scream and know dat dey are not alone.", objectives = "Rally 12 Rastari Defenders.", progress = "Our strength is in unity. It is what makes us Zandalari.", completion = "Our warriors won't soon forget you risking your own life to save theirs. Thank you." }
WordHunterWoW_QuestEN[49146] = { title = "Spirits' Belongings", description = "You are no Zandalari, but your spirit burns with a passion I have not seen in many years.\n\nI am de wavebinder. It is through me dat de loa bless our ships. I will not see my home tainted by dese talking rocks.\n\nGather my bijous, my grimoire, and some of our fallen I set aside for just such an occasion.\n\nDe brutes think dey have won. Dey will answer to Bwonsamdi soon enough.", objectives = "Find Kaza'jin's Reclaimed Bijous, Grimoire of the Other Side, and Venerated Remains.", progress = "You have my things?", completion = "You have done well. My friends on de Other Side are pleased.\n\nNow for de fun part." }
WordHunterWoW_QuestEN[49147] = { title = "Show of Strength", description = "Their leader's time is coming soon now, but we need to dispose of his lieutenants first. Our momentum will be lost if dey reform ranks.\n\nJao-Ti is de first. Legend has it Lei Shen himself said he showed a great connection to de storms. He is leading de mogu's stormbinders.\n\nDe other is Subjugator Zheng, a slaver dat would make de Kul Tirans blush. You have never seen depravity like his.\n\nKill dem both, and make dem suffer. De mogu are no strangers to war, but neither are we.", objectives = "Kill Jao-Ti the Thunderous and Subjugator Zheng.", progress = "Is de deed done?", completion = "Dey deserve worse fates, I assure you." }
WordHunterWoW_QuestEN[49148] = { title = "Crumbling Apart", description = "De mogu army grows with each passing moment thanks to their animated stone warriors. It is only a matter of time before their forces are back at full strength.\n\nA thousand curses upon Zul. He was forbidden from bringing his pets here--and from resurrecting de Thunder King in Pandaria.\n\nWe are de only thing standing between dem and de city. We've got to stop dis while we still can!", objectives = "Destroy 8 Stormbound Conquerors.", completion = "Dey will reinforce their lines if we do not act soon. Dis may be our only opportunity." }
WordHunterWoW_QuestEN[49149] = { title = "Embrace the Voodoo", description = "Dese heathens think we are weak. Dey think we are broken.\n\nBut Zandalari never truly die.\n\nI've blessed dat skull Habutu gave you with a bit of voodoo dat will let it break through to de Other Side. You will need to use my spirit obelisks to channel its power. Dey will take it from dere.", objectives = "Use the Rastari Skull Whistle to activate 5 Spirit Obelisks.", progress = "Nobody will ever take dis land from us.", completion = "Can you feel it? De spirits are flowing through you, and dey are pleased." }
WordHunterWoW_QuestEN[49160] = { title = "Torga's Eternal Return", description = "Well, we did it. Doesn't make the plan we had any less crazy. But there's still one more thing left to do.\n\nI've been visiting Torga for years. He told me stories of powerful scrolls, one in particular that he said was meant to be used to put a loa's spirit to rest.\n\nI think you should be the one to read it. I mean, if you're SMART enough to read it. \n\nBah! Just take the scroll and read it before I have second thoughts.", objectives = "Use Lashk's Scroll of Eternal Return to put Torga's spirit to rest.", progress = "You can read that scroll, can you?", completion = "I guess we're in this for the long haul. Lashk and I have a lot to take care of if we're going to help.\n\nI even know where you could go to find that troll friend of yours... and Krag'wa." }
WordHunterWoW_QuestEN[49178] = { title = "My Favorite Things", description = "It's tough out here.\n\nPirates. Deadly monsters. \n\nHungry Sam's seemingly endless battle with indigestion.\n\nNothing sets the nerves at ease like an old keepsake. Somethin' to remind you of home. Somethin' to keep you going.\n\nAsk around the camp. Find out what folks might have lost out there in the tideways. If you can bring any of it back, it'd be a mighty kind gesture.\n\nMe? Oh... I had a locket... \n\nNever mind, it's too small, you'd never find it. It's nothing. Don't worry about it.", objectives = "Ask Friendly Pete, Hungry Sam and Handy Bill about their missing keepsakes, then collect those items from the Wailing Tideway.", progress = "We've all lost something in the tides.\n\nSome more than others.", completion = "I didn't think you'd actually find all this stuff!\n\nWe don't have much, but here's a little something for your troubles." }
WordHunterWoW_QuestEN[49181] = { title = "Glimmering Locket", description = "<A glint of metal catches your eye among the gently bobbing flotsam. Digging into the tangled seaweed, you discover a locket of simple, yet sturdy design.\n\nOpening the locket reveals a hand-drawn picture of a woman with fiery red bangs. \n\nHer arm is around a woman with short-cropped auburn hair, and the two are proudly displaying warm smiles for the artist.>", objectives = "Return the Glimmering Locket to Stabby Jane.", progress = "Hm? What's that you've got there?", completion = "Is that?\n\n<Jane takes the locket and opens it tenderly. Tears begin to well up in her eyes as she closes it and tucks it away in her jacket.>\n\nThank you." }
WordHunterWoW_QuestEN[49185] = { title = "Catching Up", description = "Good to see you in one piece, {name}. Nazmir is a place of nightmares, but you seem to be surviving.\n\nRokhan and I convinced your Horde dat we need more support. He is getting ready to meet with reinforcements.\n\nWe still need to get de loa's aid. What happened with Bwonsamdi and Hir'eek?", objectives = "Tell Talanji about your experience with Bwonsamdi and Hir'eek.", progress = "Well? What happened?", completion = "Our luck may be looking up. Perhaps we can get Torga's aid." }
WordHunterWoW_QuestEN[49189] = { title = "Intact Demon Eyes", description = "", objectives = "What's this? An offering?", progress = "What's this? An offering?", completion = "Yes... I shall see what they saw, mortal. Would you care for a taste?" }
