WordHunterWoW_QuestEN[49191] = { title = "Many More Intact Demon Eyes", description = "", objectives = "You have become quite talented at harvesting these eyes, off-worlder.", progress = "You have become quite talented at harvesting these eyes, off-worlder.", completion = "These shall keep me busy for a while... Take this, for your loyalty." }
