WordHunterWoW_QuestEN[49218] = { title = "The Castaways", description = "I see the sirens have made another catch. You're lucky they haven't stripped your bones yet.\n\nIf you need to trade supplies or just warm yourself by the fire, there's a camp up the hill behind me.\n\nEveryone there washed up in the tides, just like you. Figure we've got folks from at least four or five shipwrecks now. All banded together, just tryin' to survive.\n\nTalk to Stabby Jane. Don't worry about her nickname, she's actually real nice.", objectives = "Speak with Stabby Jane at Castaway Point.", completion = "Ah, you must be from the latest wreck. Those damn sirens are getting bolder by the day." }
WordHunterWoW_QuestEN[49223] = { title = "The Long Con", description = "Hello again my young friend! I have good news.\n\nOur mutual acquaintance Carentan -- the man who scammed us in Freehold -- has finally come out of hiding.\n\nI have been communicating with him in letters delivered by various middlemen and even completed a few proxy trades to earn his trust. In our last correspondence, he agreed to meet for an in-person trade.\n\nHe thinks he is meeting with a Ms. Pixy Spindlespark, gnomish hairdresser with a weakness for poached furs.\n\nBut he'll be meeting you instead.", objectives = "Slay Carentan.", progress = "Don't let him get away this time!", completion = "Slow and steady, my friend." }
WordHunterWoW_QuestEN[49224] = { title = "The Netherlight Crucible", description = "The crucible thrums with power. Soon our weapons will shine like the stars themselves!\n\nWe will need that strength if we are to have any hope of defeating the Legion here.\n\n{name}, you have endured great hardship to bring us to this moment. The honor of first tapping the crucible's power must be yours.", objectives = "Imbue a relic with Netherlight Fortification using the Netherlight Crucible.", progress = "We need every advantage we can muster if we are to see the Legion's end.", completion = "As your weapon increases in strength we will be able to infuse it with even greater power, but its new strength should be more than enough for now." }
WordHunterWoW_QuestEN[49225] = { title = "Chasing the Leader", description = "The locals and the league have been working together tae reclaim relics in this here cave up the hill. But it seems that we've angered the previous residents. I think the marines can keep the expedition safe fer now, but I dinna how long they can keep it up. \n\nWe need yer help before things go south! Find Hilde Firebreaker, the leader of our expedition. She ran back into the cave fer somethin' or another.", objectives = "Find Hilde Firebreaker.", completion = "Yer here to help? Finally!" }
WordHunterWoW_QuestEN[49226] = { title = "Silencing the Sisters", description = "The sirens in this tideway have drawn countless ships to their doom. Wiping them out would be a boon to all seafaring folk.\n\nBut you can't very well kill all of them. Only a fool would try that.\n\nThe real dangerous ones are the elders. The \"sisters\" as they're known. Bigger, smarter, and stronger than the younger ones. Their voices carry far out to sea and bring in all the big \"catches.\"\n\nI managed to track two of them to a den at the northern end of the tideway, but I can't take them alone.", objectives = "Slay Patheope and Nolpe.", progress = "Sirens can be handled with relative ease. The older ones take a bit more work.", completion = "By quieting their deadly song, you have saved countless lives." }
WordHunterWoW_QuestEN[49227] = { title = "The Master Key", description = "None of the keys you found were the right fit! We're going to need another plan...\n\nI've heard that Overseer Morrison has a master key that can open any lock in the compound. It's dangerous, but I need you to get that key for me!\n\nYou'll find her running the mining operation inside the cave. Once you get the key, make sure you rescue any vulpera captives that you find.\n\nOnce you've rescued my friends, meet me back here and release me. Good luck!", objectives = "Obtain Morrison's Master Key and use it to free 8 Vulpera Captives.", progress = "You keep your end of the bargain, and I'll keep mine.", completion = "Sure am glad to see you again, <name>. A reliable rescuer has been hard to come by.\n\nI'll pay you as promised, I but won't be sticking around for long!" }
WordHunterWoW_QuestEN[49229] = { title = "The Ruins Fought Back", description = "Something set off a trap in the cave, and then the ruins themselves came tae life. I expect that most of our lads still in that cave aren't in fightin' form.\n\nCould ye clear out some of the livin' ruins tae help them escape?", objectives = "Kill 6 Ancient Protectors.", completion = "I've fought off spirits afore, but ne'er the actual ruins themselves." }
WordHunterWoW_QuestEN[49230] = { title = "Local Flavor", description = "I'm STARVING.\n\nNot actually starving, like when I first got here, but you know... Emotionally starving.\n\nHaven't had any luck with the oysters lately, and seaweed soup really upsets my guts. If I eat any more of that stuff, I think the other castaways might actually feed me to the sharks.\n\nHow about them tidelurkers? They look pretty juicy. Bet you could steam those up real nice.\n\nCan you get me some? I'm not much of a hunter. But I'll share it with you!", objectives = "Gather 5 Juicy Lurker Tails.", progress = "<Sam's stomach growls audibly.>", completion = "Oh, you're a lifesaver!\n\nHang on just a sec, I'll cook these up in no time!" }
WordHunterWoW_QuestEN[49232] = { title = "Salvaging a Disaster", description = "Birch and I are helping out the expedition with field studies. I'm not much of a fighter, but I can't make another mistake, they might demote me!\n\nCould you recover some of the relics we packed up in boxes around the cave?", objectives = "Gather 6 Drust Relics.", progress = "Did you find enough relics?", completion = "I can't wait to see what sort of power I can squeeze out of these." }
WordHunterWoW_QuestEN[49233] = { title = "I'm a Druid, Not a Priest", description = "The remains of previous trespassers also arose when we set off the main trap.\n\nCranklefuse here has been demanding that I help them, and while I can't say I'm too familiar with turning the undead, I believe I have found a solution.\n\nI've modified my staff to remove their curse. Take it and see if you can't help them.", objectives = "Free 5 cursed raiders.", progress = "Have you tried out that staff yet?", completion = "Another victory for druid magic! This staff is much more effective than any of Cranklefuse's gadgets." }
WordHunterWoW_QuestEN[49234] = { title = "A Marine Out of Water", description = "A giant one of those stone creatures killed quite a few marines while we were trying to evacuate the cave. It didn't chase us too far, but ignoring it outright is too big of a risk.\n\nIt needs to fall!", objectives = "Kill the Awakened Guardian.", completion = "I heard the falling of stone echo through the cave from here. Nice work." }
WordHunterWoW_QuestEN[49239] = { title = "Dress to Impress", description = "Freehold used to be open to anyone, but now it seems the Irontide Raiders have declared themselves the owners. They're locking the place down and turning away anyone who isn't part of the crew.\n\nFortunately, they're also hiring.\n\nPut this on. Don't think about where it came from.\n\nWe'll pose as new recruits, get in, gather some information, and be back in Boralus in time for supper! Cyrus may be salty, but he's a decent cook.", objectives = "Put on the Irontide Hat and enter Freehold with Flynn.", completion = "Don't worry, Venrik's a good man. I trust him with my life." }
WordHunterWoW_QuestEN[49242] = { title = "Quill or Be Quilled", description = "Oh, hello there. Sorry, we don't get many mainlanders in these parts.\n\nThis plot was my husband Sam's farm. He used to tend to the onion fields every day before the curse befell Glenbrook and took him with it.\n\nWith my husband gone, this farm is all I have left, and these quillrats are making sure I don't get even that.\n\nI'd hate to bother a perfect stranger, but could you help quell this infestation?", objectives = "Kill 6 Territorial Quillrats in Hawthorne's Plot.", progress = "These quillrats are truly a menace!", completion = "Thank you, <class>.\n\nMaybe in reviving these fields I can bring a bit of Sam's goodness back to this accursed land." }
WordHunterWoW_QuestEN[49259] = { title = "And Justice For All", description = "Thank you for helping to redeem me in the eyes of my people, {class}. I am in your debt, and I will be sure to let my father know.\n\nIn the mean time, I think we should find out what this Heartsbane Coven is, and what they are doing in our lands. I hope the marshal will be able to enlighten us.\n\nFirst thing's first, though. Care to undo these ropes? They're starting to chafe.", objectives = "Leave Hangman's Point with Lucille Waycrest.", progress = "Shall we?", completion = "This situation is much worse than I had thought. The coven has taken House Waycrest?! This will not stand!\n\nWait... you mentioned that they were drawing their power from an ancient ruin?\n\nI think I might have an idea." }
WordHunterWoW_QuestEN[49260] = { title = "Backup While I Pack Up", description = "I came in here tae try an' reclaim as many relics as possible. Sneakin' in was easy, but I'm worried about things noticin' me while I pack up. \n\nMind watching me back while I get the relics stored in a safe place in my bag?", objectives = "Protect Archaeologist Firebreaker.", completion = "Everything worth our attention should be stored in my bag, many thanks." }
WordHunterWoW_QuestEN[49261] = { title = "Crabby Crew Stew", description = "Shouldn't you be in the mines? Look, I won't tell Morrison if you won't. I wouldn't want to be stuck in those mines, either. \n\nWe could use a hand out here, though. The crew is getting crabby. We've been eating nothing but slop and the occasional rat for weeks. \n\nI hear one of the deckhands makes a marvelous crab stew. Can I count on you to secure the meat?", objectives = "Collect Lumpy Crab Meat from Sand Scuttlers.", progress = "It'll be nice to eat something other than rat for a change.", completion = "You've done good, <name>. We'll be eatin' like kings tonight!" }
WordHunterWoW_QuestEN[49262] = { title = "Gang Bustin'", description = "It's difficult to run a tight ship when you're so far from home. The crew has a tendency to get restless when they've been landlocked for too long.\n\nI've heard reports of deckhands sneakin' around and stealin' supplies. If the crew thinks they can steal from our employer on my watch, they've got another thing comin'!\n\nI need someone to crack down on these shady deals and send a message to the crew.\n\nThievin' won't be tolerated!", objectives = "Confront 8 Shady Deckhands.", progress = "We murder mutineers 'round here.", completion = "Glad I can count on you to keep things from gettin' out of hand." }
WordHunterWoW_QuestEN[49266] = { title = "Forge of Aeons", description = "The Lightforged have long stood as a beacon of hope against the Legion.\n\nBut few truly know what it takes to become the embodiment of Light's wrath.\n\nThese few champions among the Army of the Light are ready to undergo their final trial.\n\nWill you do us the honor of bearing witness?", objectives = "Bear witness to the ritual of the Lightforged.", progress = "It fills me with hope that we have found allies such as you.", completion = "T'paartos is... enthusiastic. He means well, and he has a fire within him that few even among the Lightforged possess. Thank you for keeping him safe, <race>." }
WordHunterWoW_QuestEN[49268] = { title = "Sharks in the Water", description = "Recently a large gam of sharks has moved into the shallower water in the harbor. I have dealt with minor illnesses before that were caused by creatures carrying foreign contaminants to shore.\n\nPerhaps the sharks have brought something in from the deeper waters? Cull some of the sharks that have wandered too close to the pier. I shall read the tides for any changes.", objectives = "Kill 6 Invading Dreadmaws.", completion = "Unfortunate... the tides still speak the same." }
WordHunterWoW_QuestEN[49274] = { title = "Morgrum's Survey", description = "Oi. Since yer hands are already dirty, what do ye say we make a deal?\n\nTo give it to ye straight, there's a relic here called the Breath of Xibala. I don't know who Xibala is or why the Alliance wants its breath, but there's a hefty sum of gold in it fer me if we deliver.\n\nThat means there's somethin' in it for you, too, if ye get my meanin'.\n\nI started a survey with me equipment but haven't got me results yet. Go on out into the ruins an' give the boxes you see a little kick to hurry things along.", objectives = "Check on Excavator Morgrum Emberflint's survey equipment in the Ruins of Xibala.", progress = "I'll be countin' me own gold if ye don't want to lend a hand.", completion = "Don't ask questions ye don't want the answer to, <name>.\n\nBut ye did well, an' now I got what I need to track down the Breath." }
WordHunterWoW_QuestEN[49276] = { title = "The Thrill of Exploration", description = "Name's Acadia, Acadia Chistlestone!\n\nI represent the interests of the Explorers' League at this site. Where there's dirt to be turned, we're happy to do the digging!\n\n<Acadia's smile falters.>\n\nThese Dark Iron, though, they're keen on delving deeper and faster than I'm comfortable with. Since you're a strong, capable member of the Alliance, do you think you could ah... lead by example?\n\nGo on, there's a fresh fossil here that could use some attention.", objectives = "Help Acadia Chistlestone recover a Xibalan fossil.", progress = "Acadia tells me you're in charge, now. We'll see about that.", completion = "We both know ye didn't really want all that dirt under yer nails.\n\nYer welcome." }
WordHunterWoW_QuestEN[49278] = { title = "Spiritual Restoration", description = "Dis is a sacred place to Bwonsamdi, but now it is little more than a ruin. Even de spirits are unable to escape de passage of time and have faded away, leaving only their drained husks behind.\n\nWe will return dem to life.\n\nHere, I have been collecting de souls from my hunt into dis charm. Use it on de drained spirits, and we will bring dis place back to what it once was.", objectives = "Use Hanzabu's charm to resurrect the spirits of Zo'bal.", progress = "You finished with de spirits yet?", completion = "De spirits watch over Zo'bal again!\n\nNow, about our deal..." }
WordHunterWoW_QuestEN[49282] = { title = "Morgrum's Extended Survey", description = "I've looked over the readings my little boxes gave an' I think I know where to look next. The Ashes of Xibala are practically mine.\n\nYe'll want to meet me in the middle of the ruins, under that big ol' leerin' skull on the mountainside, to continue my survey.\n\nReadin' these contraptions is hard work, an' I don't think we'll be alone up there.\n\nThink ye can watch me back?", objectives = "Assist Excavator Morgrum Emberflint with a survey.", completion = "That no good dirty ash-thievin'--!!\n\nWe're goin' after her, <name>." }
WordHunterWoW_QuestEN[49283] = { title = "Who Seeks the Seekers?", description = "Let me tell you, Zandalar is filled to the brim with ancient secrets. It's quite fascinating.\n\nWe heard tales of a region, to the southeast, where ships were losing their way. Some even vanished!\n\nRaku, along with a team of particularly curious Seekers, has been exploring a cove near there for some time. Shipwrecks and mysteries, what isn't to like?\n\nWe should have heard back by now. We tortollans may not be fast, but we are reliable.\n\nWill you check on them, and make sure they are well?", objectives = "Locate the Seekers down the coast, to the southeast, and speak to Batu.", completion = "We must thank him for his concern. We thank you for your arrival." }
WordHunterWoW_QuestEN[49284] = { title = "Perfect Tidings", description = "Your timing is most convenient, {class}.\n\nOur team had a check-in planned for this place, two days past. None have yet returned. \n\nI did not want to be brash and send word to the city too soon. However, I cannot leave this place empty, nor can I abandon young Koba. \n\nTake this scroll. See who, or what, you can find. Bring back those you can.", objectives = "Use the attuned Scroll of the Missing to track and find the lost explorers.", completion = "Well met, neighbor! Batu must have faced such a conundrum when we did not return." }
WordHunterWoW_QuestEN[49285] = { title = "Tiny Treasures", description = "My adults are in the field doing some research. So I stay here, patiently waiting, as they told me to do.\n\nThese monsters came and took my special treasures! They took my best friend in the whole world, my slug, Spitzy!\n\nThey took them all. They ran far. I do not move fast...\n\nCould you please get them back, and find my family?", objectives = "Collect all of Koba's treasures.", progress = "My hatchling... if they laid a finger on him...", completion = "Koba's favorite things! I do hope he stayed put. He is filled with such haste.\n\nThank you, <race>, my boy and I will be reunited soon.\n\nAlso, Spitzy asks that you take this little sluglet with you on all your adventures." }
WordHunterWoW_QuestEN[49286] = { title = "Caged Wisdom", description = "Oh, hello, friend. \n\nIt seems there is more here than for what we prepared.  \n\nWe sought. We found. We studied... and then we were taken. There are naga here. We did not expect this.\n\nThere is a nasty fellow in this cave. If you could get the key from him, it would help us greatly.\n\nNo need to fret, we'll wait here.", objectives = "Take the key from Sli'thrus.", progress = "Were we asking too much?", completion = "We best get moving. I do not believe we can wait for the naga to move on, this time." }
WordHunterWoW_QuestEN[49287] = { title = "Lost Chelonians", description = "Tidemistress Nazesh has been channeling on a rock they found in one of the pools above. She has been trying for days. They grow desperate.\n\nThe rest of my team was taken and locked up in cages. They want secrets from us that we do not know.\n\nWhen they realize we tortollan cannot be coerced, I expect the naga will do something most dire.\n\nRelease the Seekers. We will thwart the naga plans together.", objectives = "Rescue tortollans captured by the Nazeshi.", completion = "As long as my friends are safe, I can continue without worry. Many thanks, <class>." }
WordHunterWoW_QuestEN[49288] = { title = "Scrollhunters", description = "When they captured us, they took everything we had - including our wonderful scrolls!\n\nThose naga witches are building storms. They try to hide what they do here, and seek power for their queen. \n\nWe see past their madness, they are driven for a purpose.\n\nRetrieve our work from the Nazeshi Tempest-Wielders, else they may use them for nefarious gains.", objectives = "Collect 5 Seeker scrolls.", progress = "I really need to invest in some more scroll cases...", completion = "Looks like everything is here, and with little damage done! Very impressive!\n\nWhat do we have in here? Let's see..." }
WordHunterWoW_QuestEN[49289] = { title = "A Special Stone", description = "Tidemistress Nazesh is right up this hill, {name}. \n\nThere is something there. Something Azshara wants very badly.\n\nThe naga must not succeed. If you can get a little piece of that stone, though, bring it back for us.\n\nTake this scroll with you, it will help you in your fight.\n\nIt is time we push her forces, back into the waves for good.", objectives = "Defeat Tidemistress Nazesh and discover why the naga were sent here.", progress = "What have you found?", completion = "Well fought, adventurer. Well fought, indeed! \n\nWhatever this stone is those naga were after, they did not get it this day!" }
WordHunterWoW_QuestEN[49290] = { title = "Aged to Perfection", description = "Greetings, young one. I am Roko. I trade in specialty goods and exotic wares.\n\n<Roko pulls a small wooden cask from beneath his shell.>\n\nThis bourbon is one hundred years old. I know, because I bought it one hundred years ago.\n\nA man in Freehold is prepared to trade me a rare scroll for this, but alas I am barred from entering. It seems this town is not so \"free\" anymore.\n\nIf you can get in, perhaps you could make the trade on my behalf? I would be in your debt.", objectives = "Deliver the Hundred Year Bourbon to Carentan in Freehold.", progress = "Are you with the Irontide?\n\nI've already paid you people! Leave me alone!", completion = "Oh! The bourbon from that turtle fellow!\n\nSo... he's not coming himself? And I take it you're no Irontide loyalist.\n\nVery well, hand it over." }
WordHunterWoW_QuestEN[49292] = { title = "Algae Shakes", description = "Now that I have properly developed my tonic, it is of utmost importance that we dispense it amongst the ill at once.\n\nPlease, take this tankard and distribute the remedy to the sick. I will try to calm the rest.", objectives = "Dispense the Cleansing Tonic to 6 Nauseated Villagers in Anglepoint Wharf.", completion = "In all my days, I have never seen such an illness. We must find the source!" }
WordHunterWoW_QuestEN[49293] = { title = "Invasion Onslaught", description = "We must not yield even a single world to the Legion. Continue our Invasion Point offensive and crush the Legion beneath your heel.", objectives = "Complete 3 standard Invasion Points.", progress = "The offensive continues.", completion = "The Legion's defeat is at hand." }
WordHunterWoW_QuestEN[49295] = { title = "Clear-Cutting", description = "We've managed to hold this hill, but the wicker creatures have moved in to surround us.   \n\nWe're not going to be able to move into the town if we don't get them off our flanks. This is where you come in, {class}.\n\nSee if you can clear out some of their numbers in the lumber fields. That way, when we move in, we only need to worry about one front.", objectives = "Kill 8 Curseformed Familiars in the Timbered Strand.", completion = "Excellent. \n\nIt was starting to feel a bit claustrophobic on this hill." }
WordHunterWoW_QuestEN[49299] = { title = "Enemy Within", description = "I won't sugarcoat it, kid. It's a madhouse here.\n\nThe leadership has fallen, selling their own souls as well as the souls of the workers to some darker forces.\n\nI will not give in.\n\nOverseer Bates surrendered the guard in his hunger for power. Show him that he is a fool.", objectives = "Kill Overseer Bates.", progress = "After the guard fell, it was easy to get to everybody else.", completion = "Bates gave everything he had for greater power. Shame it had to go that way." }
WordHunterWoW_QuestEN[49300] = { title = "Creature Corruption", description = "", objectives = "" }
WordHunterWoW_QuestEN[49302] = { title = "The Deadliest Catch", description = "Oi! No time to waste!\n\nSeems Deepwarden had one more thing up his sleeve... and it's the catch of the day!\n\nThis'll be a hunt for the ages, and I won't let ya miss out.\n\nOkri will fly you out to the wall. Get ready!", objectives = "Accompany Okri to the sea gate, then kill Viq'Goth.", progress = "I've never seen a monster with such dark energy. We can't let it get through!", completion = "My inadequacy to rule lead to Deepwarden's near takeover of not only the fishing operation here, but the village as a whole.\n\nI can no longer allow myself to sit quietly and allow people like him to walk over me to do as they please! I've learned that, thanks to you." }
WordHunterWoW_QuestEN[49309] = { title = "Thunder's Fall", description = "Warlord Kao commands de mogu from dis warship. It is time to put an end to dis incursion.\n\nI should be able to hold off any stragglers dat may come to Kao's aid, but I can only maintain dis barrier for so long.\n\nBe careful. Kao was one of de Thunder King's top generals. He will not fall without a fight.", objectives = "Kill Warlord Kao.", progress = "Without Kao at their head, de mogu will fall easily.", completion = "De king is in danger!" }
WordHunterWoW_QuestEN[49310] = { title = "The Prophet's Ploy", description = "King Rastakhan's life is in grave danger. Zul is far more powerful than he appears.\n\nWe do not have much time. You have to warn de king before Zul can act.\n\nHabutu and Zolani can take you dere. Now go!", objectives = "Travel on Scarbeak to Dazar'alor.", completion = "We are betrayed." }
WordHunterWoW_QuestEN[49314] = { title = "Hunting Zardrax", description = "{name}, maybe you be helpin' me wit' sometin'.\n\nTalanji said dat Shadow Hunter Da'jul and her retainer, Kal'dran, ran off ta hunt down a lich named Zardrax.\n\nThey be goin' off ta a place called Burial Mound. I be worried dey be in over dere heads.\n\nCan ya check ta see if dey be needin' help? We can't be losin' any of our allies in dis place.", objectives = "Find Shadow Hunter Da'jul in Burial Mound.", completion = "About time... someone... showed up...! Ya gotta get... this lich... away from us!" }
WordHunterWoW_QuestEN[49315] = { title = "Dreadpearl Collusion", description = "", objectives = "" }
WordHunterWoW_QuestEN[49327] = { title = "Push Them Back!", description = "The faithless are laying siege to our home. \n\nThis isn't the first time they've attacked, nor will it be the last, but we must protect the temple!\n\nDo whatever you can to disrupt their siege and push them back.", objectives = "Disrupt the Faithless assault on the Sanctuary of the Devoted.", completion = "The faithless will never stop their siege, but your efforts have bought us time." }
WordHunterWoW_QuestEN[49333] = { title = "Building Our Arsenal", description = "Our fight against the faithless is an uphill battle we're bound to lose. We are outnumbered and out armed. \n\nWhat few weapons we have aren't enough to outfit the entire temple. \n\nWith a few more spears and daggers, we might stand a chance fighting them off until our loa can be returned to us.", objectives = "Collect 20 Sethrak Weapons from within the Temple Incursion.", progress = "We need weapons, <name>.", completion = "You've brought enough to put a weapon in the hands of everyone willing and able to fight." }
WordHunterWoW_QuestEN[49334] = { title = "A Powerful Prisoner", description = "It appears the Faithless broke through our defenses while I was away. \n\nThey must be after Vorrik's key. It's the only reason they would have taken him alive. \n\nPlease, {name}. You must secure our leader's safe return.", objectives = "Find Vorrik and free him from his captors.", completion = "I owe you my life, <name>." }
WordHunterWoW_QuestEN[49335] = { title = "Skycaller Slaughter", description = "Some among the faithless are gifted with the ability to command the storm. They call themselves skycallers, and they use their magic to summon great spires that turn the earth into sand.\n\nSkycallers are the only ones capable of summoning these spires. If you kill the skycallers, you also kill the sethrak's ability to expand their warcamps.", objectives = "Kill 6 Sethrak Skycallers at the Temple Incursion.", completion = "Without their skycallers, the faithless' incursion will falter." }
WordHunterWoW_QuestEN[49340] = { title = "The Keepers' Keys", description = "Serrik mentioned you might have uncovered something of significance at Zul'Ahjin?\n\nWe don't have much time, I'm afraid.\n\nWhat is it you have found?", objectives = "Speak to Vorrik and uncover the significance of Sulthis' Stone.", completion = "Thanks to you, we now have two of the keys. Korthek still holds the third.\n\nIf we can get our hands on that key, then Mythrax will remain sealed in his tomb forever." }
WordHunterWoW_QuestEN[49345] = { title = "Buried Treasure", description = "", objectives = "" }
WordHunterWoW_QuestEN[49348] = { title = "A Desecrated Temple", description = "Da spirits of da faithful flock ta me temple. Ya see dem out dere, yes? \n\nDey come ta enter da Other Side an' join me realm. However, spirits who've turned their backs upon Bwonsamdi, dey too have come to me temple grounds. Dey praise one called \"G'huun,\" and spread their blood magic desecration across da Necropolis.\n\nDis ends now!\n\nGo out dere and remove da desecrations dat be infesting me temple.", objectives = "Destroy 5 Vile Desecration within the Necropolis.", completion = "Ya done good, mon. Da Necropolis already startin' ta feel more like home again." }
WordHunterWoW_QuestEN[49354] = { title = "Remember the Sunwell", description = "The Regent Lord intends to show First Arcanist Thalyssra our Sunwell.\n\nI do not know if he will allow Alleria Windrunner to attend the meeting, but we are invited to join them.", objectives = "Complete the scenario, \"Remember the Sunwell.\"", completion = "That was not wholly expected." }
WordHunterWoW_QuestEN[49366] = { title = "Aid the Wounded", description = "<This Zandalari appears to be barely holding on.\n\nThere is a broken dart lying on the ground next to him. He appears to have dropped this bottle before he collapsed.\n\nYou grab the vial. Could it be some kind of antidote?>", objectives = "Treat the wounded Zandalari.", completion = "Thanks, stranger. Dat was too close." }
WordHunterWoW_QuestEN[49370] = { title = "Rescue the Chronicler", description = "Just ahead, Chronicler Jabari is being held in a cage, waiting to become a sacrifice.\n\nOne by one, I see dem taken away, I hear de screams. Blood drained to feed blood magic, and what was left... was food for a beast.\n\nHe is de only one left, and I don't have de strength to save him yet.\n\nGet Jabari out of dere, so we can return to Princess Talanji.", objectives = "Release Chronicler Jabari.", completion = "Well, dat was terrifying. Just a few more pieces, and we can be forever away from dis place." }
WordHunterWoW_QuestEN[49375] = { title = "LARRY TEST QUEST", description = "", objectives = "" }
WordHunterWoW_QuestEN[49376] = { title = "Just One Thing", description = "You are just in time! Chance be high dat my blood was de next to spill.\n\nIt is my fault we stopped here. Our team wanted to head back.\n\nCrawgs are de trouble, you see. De sanguinous birth of dese young be corrupted by cruel training. They are quite impressionable and dey will follow with just a little enticement.\n\nCapture the attention of one of de little squirmy ones nearby. We will see if my theory is correct.", objectives = "Capture a crawgling." }
WordHunterWoW_QuestEN[49377] = { title = "Off With Her Head", description = "Warmother Nagla is driving her forces with a brutality and strength we did not expect. \n\nBlood trolls desecrate all dey touch, and are preparing to wreak havoc on all dat remain. \n\nAs dey say, \"cut off de head, and de beast will be dead\". \n\nI will have her head as a trophy to show dat our brothers were avenged!", objectives = "Bring back the head of Warmother Nagla.", progress = "Does she still live?", completion = "<Satao spits on the ground.>\n\nDe world is better without dat monster in it." }
WordHunterWoW_QuestEN[49378] = { title = "Earn Their Trust", description = "If de young one can be taught to trust, dere is a chance for dis species.\n\nDey may have been born of bad blood, but is dat what makes dem monsters? If you can build his confidence, a mighty ally he could one day be.\n\nA little care could be de thing, and don't forget food! I think some blood trolls may be extra tasty.", objectives = "Feed the crawgling.", completion = "He is sated now! Well done!" }
WordHunterWoW_QuestEN[49379] = { title = "Crawg Free Zone", description = "Crawgs dat have been battle trained are already set in their ways.\n\nCleansing dem from de camp may be de only way to give de young ones a chance.", objectives = "Kill 5 Battle Crawgs.", completion = "Their suffering is over now." }
WordHunterWoW_QuestEN[49380] = { title = "Bad Juju", description = "Look, between you and me, dere is no way we will drag my friend outta here without what got us into dis mess.\n\nWe saw three orbs in dis camp. Dey are filled with de power of blood magic and are used in dirty rituals. \n\nBlood is drained from \"volunteers\" to corrupt de tadpoles of Krag'wa into vicious crawgs.\n\nIf dis is a possible fate for children of loa, we must end it. \n\nTake dis vial and bleed de orbs dry. De chronicler will need to do research.", objectives = "Drain the blood orbs.", completion = "Ugh! Even I feel de corruption. I am sure Jabari will be able to find de secrets locked away in here. \n\nThank you, <name>." }
WordHunterWoW_QuestEN[49381] = { title = "Vengeance Be Kind", description = "In the cave, you will find Mala'kili.\n\nShe be a depraved hoarder dat take pleasure in de tormented deaths of slaves and prisoners.\n\nDey be taken, one by one, and thrown to her pet monster. She is takin' what was theirs for herself.\n\nBring vengeance for de fallen bruddas, give dem peace, and all dat remains is for you.", objectives = "" }
WordHunterWoW_QuestEN[49382] = { title = "It Seems You've Made a Friend", description = "Dis young one has bonded with you. \n\nBring him to Krag'wa. \n\nSee if dere is anything to be done to heal him of de corruption.", objectives = "Seek out Krag'wa.", completion = "This young one is no longer one of them, but he can never be one of us. Take care of him!\n\nThank you, <name>." }
WordHunterWoW_QuestEN[49393] = { title = "The Roughnecks", description = "NEW JOB OPPORTUNITIES!\n\nDo you seek danger? Beasts in great quantities? Perilous adventure?\nDo you also prefer the rugged outdoors to the dainty frilly froo-froo estate life?\n\nWell, you might be cutout to be a ROUGHNECK, suppliers of all gryphon mounts in Kul Tiras.\n\nInquire at the Roughneck Camp in Westwind Weald about this exciting new opportunity.\n\nApplicants must NOT be afraid of heights, feathers, and/or death.", objectives = "Speak with Tagart at the Roughneck Camp.", completion = "Here for the job are ye? Well buckle up house cat, it gets rough from here on out." }
WordHunterWoW_QuestEN[49394] = { title = "Hold Still", description = "If you want to be a Roughneck, you're going to have to pass a few... trials. Every one of us has done 'em, so I don't want to hear any whining.\n\nTake these clippers and get me some goat fur. You have to clip 'em while they're alive, because thems the rules. Oh, and cover your bits when you do it, they like to kick.", objectives = "Use the Goat Shears on 6 Gentle Goats.", progress = "Got the fur?", completion = "You actually did it! Tell me, how did they like it? Any of 'em give you the horns? Hahaha!" }
WordHunterWoW_QuestEN[49395] = { title = "The Bears and the Bees", description = "Hey, while you're out, would you grab some honey for me and the boys?\n\nPlenty of hives out in the woods, but I'd be careful if you don't want to dirty your delicate house cat hands. Bears out here tend to get pretty vicious when they smell honey.", objectives = "Kill 8 Scruffhide Bears and gather 6 Sticky Bee Honey from nearby Beehives.", progress = "Bears giving you trouble?", completion = "You got more on your shirt than you got in the bottles! I'd ask you to shower, but frankly none of us have done that in weeks." }
WordHunterWoW_QuestEN[49397] = { title = "Sausage Party", description = "", objectives = "" }
WordHunterWoW_QuestEN[49398] = { title = "Raise a Glass!", description = "Pleased to meet you. Name's Venrik. I been scrapin' out a living here in Freehold for years.\n\nFlynn used to be a regular back when he... well I shouldn't say too much. A man's past is his own.\n\nI'll help the two of you out, but first I demand that you let me give you a proper Freehold welcome: A drink!", objectives = "Order a drink from Venrik and drink it.", progress = "What'sa matter? Cat got yer tongue?", completion = "Ah, nothing like sharing a drink with an old friend... and a new one!" }
WordHunterWoW_QuestEN[49399] = { title = "The Big Job", description = "So the Irontide Raiders are bringing the various outlaw crews together for a big job using weapons provided by the Ashvane Company.\n\nSomething tells me they're not going fishing.\n\nWe should see if members of the smaller crews are carrying any notes or orders. I trust you can handle it?\n\nI need to lay low and catch up with Venrik. If anyone else were to recognize me, the odds of them offering a friendly drink are precisely zero.", objectives = "Collect Bilge Rat Orders, Cutwater Corsair Orders, and Blacktooth Brawler Orders.", progress = "Find anything?", completion = "I--I'll try to make sense of these.\n\nYou've gotta help Flynn!" }
WordHunterWoW_QuestEN[49400] = { title = "Recruiting Efforts", description = "The captain of the Irontide Raiders, Harlan Sweete, has it in his tiny head that he's in charge of Freehold now. \n\nHe's been forcing the smaller crews to pledge their loyalty, and littering the whole town with his damn recruiting posters.\n\nDo me a favor and take down any of them posters you find. Just don't let them catch ya doin' it, or it's a long walk off a short plank.", objectives = "Tear down 6 Irontide Recruiting Posters.", progress = "Makes me sick seein' those damn posters all over this town.", completion = "Hah! That oughtta slow 'em down, or at least piss 'em off." }
WordHunterWoW_QuestEN[49401] = { title = "Rodrigo's Roost", description = "We should check in with Cyrus and Taelia before we get in too deep.\n\n<Flynn pens a note on a scrap of parchment and tucks it into a small courier bag.>\n\nThis is all of the evidence we've gathered so far linking the Ashvane Trading Company to the weapons and pirates here in Freehold.\n\nTake it to Rodrigo, on the rooftop just behind this tavern. He raises parrots that make great messengers. Some are even big enough to ride!\n\nRodrigo's a few planks short of a poop deck, but he's trustworthy!", objectives = "Speak with Rodrigo in Freehold.", progress = "Talk to Rodrigo and send that evidence off to Taelia.", completion = "Alright, now that the boss is updated, let's get back to work." }
WordHunterWoW_QuestEN[49402] = { title = "Flew the Coop", description = "Yes, yes, you can ride the pretties. They like it! They're good pretties. They like helping!\n\nDo you like helping, too? Maybe you can help me!\n\nSome of the loud men came here and threatened me. They don't scare me! But they made the pretties fly away.\n\nIf you see any of my pretties out there, please feed this to them!\n\nIt's my special treat. I know it will make them come home.", objectives = "Feed 6 Runaway Macaws.", progress = "Did you find any pretties? Oh, they must be so hungry out there.", completion = "You did it! So many pretties came back!" }
WordHunterWoW_QuestEN[49403] = { title = "Rodrigo's Revenge", description = "The loud men are mean, but you seem nice!\n\nWant to have fun fun?\n\nThe pretties love my special biscuits, but it makes them full full. Then they have to... go. You know?\n\nLet's prank the mean men! Fly fly on the pretties and make them go.", objectives = "Drop Vile Bombardment on 100 pirates in Freehold.", progress = "Go! Go! Go!", completion = "That'll teach 'em!" }
WordHunterWoW_QuestEN[49404] = { title = "Fairwind's \"Friends\"", description = "Someone must have recognized Flynn and ratted him out! A bunch of Irontide thugs dragged him off to the Ring of Booty for a \"special audience\" with Captain Harlan Sweete.\n\nFlynn doesn't like to talk about this, but he used to captain his own crew. With Harlan as his First Mate.\n\nThe two had a falling out after a messy job and Flynn lost all taste for freebooting. Just disappeared one day.\n\nHarlan took the nastiest of the crew and formed the Irontide Raiders.\n\nIn other words; it's personal.", objectives = "Rescue Flynn from the Ring of Booty.", completion = "I'm so sorry, <name>. I came as fast as I could!" }
WordHunterWoW_QuestEN[49405] = { title = "Defenders of Daelin's Gate", description = "Daelin's Gate has protected the southern channel for decades. If it falls, the pirate fleet can sail straight into Tiragarde Sound!\n\nThe marines at Vigil Hill will need our help. Let's go!", objectives = "Ride with Taelia to Vigil Hill.", completion = "You've come to help? Oh, thank the tides." }
WordHunterWoW_QuestEN[49406] = { title = "Zalamar Slaughter", description = "", objectives = "" }
WordHunterWoW_QuestEN[49407] = { title = "Trixie Business", description = "Usually this is the part where I hand you the scroll and send you on your way.\n\nSadly, friend, these are unusual times.\n\nHow's a man expected to run an honest business dealing in highly illegal goods when the Irontide Raiders are shaking down good folk like myself?\n\nI'm prepared to offer you a handsome sum - and the scroll for our shelled associate - if you rid me of the damnable woman who collects these tributes.\n\nYou'll surely find her at Harlan's table at the bar, getting drunk on MY gold!", objectives = "Slay First Mate Trixie Tornsail.", progress = "Stay your hand, friend! If you harm me, you'll never find the scroll!", completion = "You actually did it? Color me impressed." }
WordHunterWoW_QuestEN[49408] = { title = "Pirate Dice", description = "", objectives = "You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[49409] = { title = "Missing Treasure!", description = "Which one o' you scurvy dogs dug up me treasure?!\n\nWas it you, Ned? I know you was in the Dead Man's Tale when I were talkin' about it!\n\nOr maybe it was ol' Nance Barmy, huh? Yer the one what fed me all them drinks in the first place!\n\nOh and don't think I forgot about you, Nub Nub! I ain't trust a hozen as far as I can throw 'em... which I guess is PRETTY FAR, but-- \n\n<Several lines are scratched out here.>\n\nSomeone stole me damn treasure!\n\n<Signed with an X.>", objectives = "Ask Ned, Nance Barmy, and Nub Nub about the treasure, then find it." }
WordHunterWoW_QuestEN[49411] = { title = "Contruct Barracks", description = "", objectives = "" }
WordHunterWoW_QuestEN[49412] = { title = "Helping Henry", description = "The Roughnecks told me to clear the rocks in the forest. I didn't know they meant THIS!\n\nYou look tough, you have to help me! I'll get killed if I get anywhere near that thing. I'm also super allergic to bees...", objectives = "Kill Brawr.", progress = "That thing sure hates bees...", completion = "Thanks so much! I'm off to my next task!" }
WordHunterWoW_QuestEN[49413] = { title = "Scamps With Scrolls", description = "", objectives = "" }
WordHunterWoW_QuestEN[49417] = { title = "Roughneck Riders", description = "Rulf sent word that you're needed for another job.\n\nA rich house cat is willing to pay top dollar for a male aerie alpha and there is only one that fits the bill, Greatfeather. I gotta head back to camp to help train a particularly wild female, so this is going to be a solo job.\n\nFind Greatfeather and hit him with the Tether Shot. From there, you'll have to wing it.", objectives = "Capture Greatfeather.", completion = "I can't believe you did it, kid! I knew you'd be Roughneck material!" }
WordHunterWoW_QuestEN[49418] = { title = "Big Boss", description = "With a performance like that, it's clear you're one of the top dogs here. Boss Tak will want to see you. He's up north checking on one of our camps in Waning Glacier. Head up that way and give him a hand.\n\nOh, and I don't recommend looking him straight in the eye... or at his feet... or really anywhere near him. Best bet, close your eyes when you're talkin' to him.", objectives = "Meet Boss Tak at the Roughneck camp in Waning Glacier.", completion = "You the new kid? Frankly, it doesn't matter. I got a problem and you're going to help me with it." }
WordHunterWoW_QuestEN[49419] = { title = "Frozen", description = "Hurp me pwease! Oh, it's woo. I can sill muv my wips a wittle.\n\nFin me sumfin to 'et me owdda 'ere.", objectives = "Find the source of heat in Longdrop Hot Springs.", progress = "Woo 'ave somefin?", completion = "Whank woo!" }
WordHunterWoW_QuestEN[49421] = { title = "Hunting Zul", description = "Zul is pulling all of his forces back to his stronghold at the Temple of the Prophet.\n\nRastakhan has sent word that he is marshalling an army in the Zocalo with anyone still loyal that can carry a weapon. Looks like the old king had more loyalists than Zul expected.\n\nThat, and he has three of their eldest loa gathered to his side.\n\nGo and lend your strength to their army.", objectives = "Meet King Rastakhan at the Zocalo.", completion = "When hunting one who has foreseen de future, it is best to proceed with a measure of caution." }
WordHunterWoW_QuestEN[49422] = { title = "Heretics", description = "Descend on Zul's fanatics and mogu allies. Hunt them down and slay them all with the fury of a true predator. Show them the true price of their betrayal.", objectives = "Bring ruin to the Temple of the Prophet.", completion = "With de sky clear of ballistae fire, Pa'ku can start doing what she loves: dropping those who cross her from a really great height." }
WordHunterWoW_QuestEN[49424] = { title = "The Full Prophecy", description = "Dat snake of a prophet, Zul. I never trusted him. Always felt like he was never telling us de whole prophecy.\n\nEnter de Temple of dis \"Prophet\" and see if he recorded any of his visions.\n\nWe must learn of what our prey intends, before our real hunt may begin.", objectives = "Find and read the 3 Words of Zul.", progress = "Zul is not liked enough for his followers to go on blind faith.", completion = "Zul has fallen so low as to wish to raise Dazar himself? Can Zul even be called a Zandalari anymore?" }
WordHunterWoW_QuestEN[49425] = { title = "City of Gold", description = "Rezan and Rastakhan did not wait for us. Dey are marching up de mountain to Atal'Dazar, de City of Gold.\n\nYou, Loti, and I need to catch up quick and give dem some air support. Hop aboard.", objectives = "Break Zul's forces on the road to Atal'Dazar.", completion = "Zul thinks to bar me from MY domain? I will consume his soul." }
WordHunterWoW_QuestEN[49426] = { title = "The King's Gambit", description = "Atal'Dazar is the tomb of kings. MY kings. My greatest followers.\n\nI will taste Zul's flesh before this day is done.\n\nCome, {name}, keep up. Our prey has neither the strength nor the numbers to block this entrance. Let us crush this heretic.", objectives = "Join Rezan and Rastakhan in their siege of Atal'Dazar.", completion = "He... he's gone..." }
WordHunterWoW_QuestEN[49427] = { title = "Not Our Purple Elves", description = "Ye know, {name}, these elves might be purple, but they're no' with the Alliance.\n\nLeastwise, they're a lot more aggressive than this ol' Dark Iron is comfortable with.\n\nOn the off chance it'll piss off the Horde, ye mind killin' a few of them?", objectives = "Slay 8 Horde forces on the eastern shores of Xibala.", completion = "I'm guessin' they weren't friendly. Well, that's a weight off me mind." }
WordHunterWoW_QuestEN[49428] = { title = "Grand Theft Telemancy", description = "I'm not opposed to honest competition, {name}.\n\nBut teleportin' it right out from under our noses leaves me feelin' dirty.\n\nGo teach that thievin' elf what it means t'steal from the Alliance. If they're fightin' dirty, then so will we.", objectives = "Slay Third Telemancer Syranel and recover the Breath of Xibala.", progress = "Ye get the Breath of Xibala back?", completion = "I'm a dwarf of me word, <name>.\n\nHere's yer cut. I'll see to it that this here... pot... is delivered to the Alliance with my praise for yer actions.\n\nIt's a little underwhelming, isn't it?" }
WordHunterWoW_QuestEN[49431] = { title = "Warm and Cozy", description = "Heya! Isn't this place a dream? I couldn't be more relaxed. Well, I could be if these annoying cloud jerks would leave me alone. \n\nWhy don't you go punch some in their cloud faces. Oh, and bring back their essences, they help keep my tub warm.", objectives = "Collect 99 Steamy Essences.", progress = "I need more steam! Hurry, the tub is getting chilly!", completion = "Ooooh, that's nice. Real nice. Hop in if you want, the water is great! Ignore the bubbles." }
WordHunterWoW_QuestEN[49432] = { title = "The Forlorn Soul", description = "Where's my ma'da? You seen her?\n\n\"I'll be right back,\" she said. I'm a good girl, I wait. I wait and wait, I'm not sure how long I've been waiting here for.\n\nIt's cold and lonely here. Hey... could you help me find ma'da? I swear I won't cause you any trouble.", objectives = "Help Keula locate her ma'da within the Necropolis.", completion = "Keula's ma'da be foolish ta tink she never gonna pass on to da Other Side, but now dey be together an' I be havin' two more souls in me realm.\n\nYou done good, mon." }
WordHunterWoW_QuestEN[49433] = { title = "Wendies", description = "It's a mystery where these boys were taken, but it ain't much of a mystery who did it. Roughnecks believe an eye for an eye and then some.\n\nLet's put down some of those monstrosities.", objectives = "Kill 10 wendigo.", completion = "This'll help protect my boys down the hill. Well done." }
WordHunterWoW_QuestEN[49435] = { title = "Where'd They Go?", description = "My boys are missing. You're going to help me find 'em.\n\nGot it?", objectives = "Locate clues regarding the missing Roughnecks.", progress = "Find anythin'?", completion = "Pity. At least I can tell the rest of the boys they went down fighting." }
WordHunterWoW_QuestEN[49437] = { title = "Tattered Note", description = "<The short, hand-written note is scrawled in blood.>\n\nThey captured me soon after I was exiled. I was too weak to be a slave and too starved to be food for the beasts.\n\nThey were going to kill me, but one called Shath'kar intervened. He said it would be amusing to watch me starve to death among his prisoners.\n\nI have not lived a good life. I deserve nothing. But, to any fellow Zandalari who finds this, I have one request...\n\nStick a blade in Shath'kar's belly and twist it until the snake is dead!", objectives = "Slay Shath'kar in the Slithering Gulch.", completion = "I've heard the other vulpera whisper Shath'kar's name in fear. Thank you for ridding us of him." }
WordHunterWoW_QuestEN[49439] = { title = "Boss' Revenge", description = "Revenge has never really been my thing, but whatever is in there killed my crew and I am not going to let it stand.\n\nEverybody fights, nobody quits.", objectives = "Kill Whompus.", completion = "To survive out here, we do what we have to. Today that meant avenging members of the pack.\n\nThank you for your help. If you ever need anything, don't hesitate to call on the Roughnecks." }
WordHunterWoW_QuestEN[49440] = { title = "Blood Troll on the Outside", description = "One of our scouts, Jo'chunga, has infiltrated de blood trolls, but we have not heard back from him.\n\nI need your help to find Jo'chunga and see what he has discovered about de blood trolls.\n\nIf you are going to find him, you need to sneak in by looking like one of de blood troll women. Dey are de ones with de most freedom to move around. I have a ritual that can change you.\n\nHelp me set up de ritual to make you look like a blood troll.", objectives = "Help Witch Doctor Kejabu complete his ritual to disguise yourself as a blood troll.", progress = "Eh? What do you need?", completion = "De ritual is done, and you are ready." }
WordHunterWoW_QuestEN[49443] = { title = "A Lesson in Witch Hunting", description = "While I appreciate the dedication that went into compiling this tome, this thing reads like engineering instructions for a siege engine!\n\nI'll need some time to comb through this information for anything that might be useful to us. I wouldn't mind some assistance, if you have a moment.\n\nFor starters, I could use some more light in here...", objectives = "Assist Lucille Waycrest as she studies the Tome of Ash and Silver.", progress = "Did you find it?", completion = "Ah, you found it! Excellent.\n\n<Lucille produces a long sewing needle from the kit>\n\n...You look confused. Let me explain." }
WordHunterWoW_QuestEN[49444] = { title = "Underfoot", description = "", objectives = "" }
WordHunterWoW_QuestEN[49445] = { title = "The Prime Exchange", description = "", objectives = "As you've no doubt learned, Primal Sargerite is a precious material which yields great power when infused with items. In our fight against the Legion, we need all the power we can get our hands on.\n\nBring me any Primal Sargerite you find and I will trade with you what I can." }
WordHunterWoW_QuestEN[49449] = { title = "Leather - Rank 1 Unlock", description = "Amazed that anything so pure could continue to grow on this planet, you pick flower from the ground. You feel a small power radiate from it and then vanish.\n\nAs it falls apart in your hands, you wonder if anyone on this Light-forsaken place knows how to handle this precious herb.", objectives = "Find someone on Argus who might be able to train you on how to handle Astral Glory." }
WordHunterWoW_QuestEN[49450] = { title = "Incident Reports", description = "No wonder our workers are terrified to go into these woods. Generally the bears and spiders stay out of the way of humans... \n\nBut these are no ordinary beasts!\n\nFather would be furious if productivity came to a halt. Please, cull these beasts so that the ridge can be safe once more!", objectives = "Kill 10 Enthralled beasts in Fernwood Ridge.", completion = "I have never seen beasts so... soulless. It's as if they're under some sort of spell." }
WordHunterWoW_QuestEN[49451] = { title = "Time Off Requests", description = "My father is incapable of seeing what's in front of his very nose. He holes himself up in his office, not leaving to go home until late at night...\n\nHere I am, his only son, trapped out here along with all of his workers. Are they in trouble? Yes! But father will never believe them.\n\nIf he won't try to get to the bottom of this attack, I will do it myself!", objectives = "Free 5 Entangled Lumberjacks in Algerson Lumber Yard.", completion = "My son is far too soft-hearted. He needs to harden up if he's going to run this business one day!" }
WordHunterWoW_QuestEN[49452] = { title = "Inventory Deficit", description = "My employees say we're under attack. They say our workers are falling to beasts and men made of wood.\n\nI say we're losing precious inventory!\n\nDo you know how many company-issued axes must be getting dropped out there? That's a waste of my hard-earned money!\n\nI'm going to need you to get those back for me.", objectives = "Collect 5 Reclaimed Axes from dead Algerson Lumberjacks.", progress = "I spend my own money to get these workers the supplies they need and they just go ahead and lose them! How much more generous must I be?", completion = "Perhaps the cost of the axes should come out of their paychecks from now on!" }
WordHunterWoW_QuestEN[49453] = { title = "Give a Dam", description = "These loggers are destroying the forest, and harming the wildlife!\n\nBeavers need this wood for their dams, but have had to resort to scrounging for scraps.\n\nIt's not safe for them anymore! Please, help me chase them back to the safety of the water.", objectives = "Shoo 6 Woodchewing Beavers back to the water.", completion = "Hooray! Now the beavers will be safe from the lumberjacks and the spiders!" }
WordHunterWoW_QuestEN[49454] = { title = "Pest Prevention", description = "These woods have never been so densely littered with spider eggs.\n\nIf these are recent... they must also be corrupted! We cannot allow them to hatch into more of these aggressive spiders.\n\nWhile you are in the woods, destroy those eggs. Any more spiders could lead to an uncontainable infestation!", objectives = "Destroy 12 Mossfang Eggs.", progress = "I will admit to not being the biggest fan of spiders. Fewer spiders sounds pretty good to me.", completion = "Thanks for that.\n\nI uh... I think you got some spider egg goop on your cloak." }
WordHunterWoW_QuestEN[49455] = { title = "Leather - Rank 2 Unlock", description = "Amazed that anything so pure could continue to grow on this planet, you pick flower from the ground. You feel a small power radiate from it and then vanish.\n\nAs it falls apart in your hands, you wonder if anyone on this Light-forsaken place knows how to handle this precious herb.", objectives = "Find someone on Argus who might be able to train you on how to handle Astral Glory." }
WordHunterWoW_QuestEN[49456] = { title = "Leather - Rank 3 Unlock", description = "Amazed that anything so pure could continue to grow on this planet, you pick flower from the ground. You feel a small power radiate from it and then vanish.\n\nAs it falls apart in your hands, you wonder if anyone on this Light-forsaken place knows how to handle this precious herb.", objectives = "Find someone on Argus who might be able to train you on how to handle Astral Glory." }
