WordHunterWoW_QuestEN[49458] = { title = "Bones - Rank 2 Unlock", description = "Amazed that anything so pure could continue to grow on this planet, you pick flower from the ground. You feel a small power radiate from it and then vanish.\n\nAs it falls apart in your hands, you wonder if anyone on this Light-forsaken place knows how to handle this precious herb.", objectives = "Find someone on Argus who might be able to train you on how to handle Astral Glory." }
