WordHunterWoW_QuestEN[49462] = { title = "Scales - Rank 3 Unlock", description = "Amazed that anything so pure could continue to grow on this planet, you pick flower from the ground. You feel a small power radiate from it and then vanish.\n\nAs it falls apart in your hands, you wonder if anyone on this Light-forsaken place knows how to handle this precious herb.", objectives = "Find someone on Argus who might be able to train you on how to handle Astral Glory." }
WordHunterWoW_QuestEN[49464] = { title = "Saurolisk Tails", description = "Among the upper echelons of Kul Tiran society, there is one cuisine that escapes all but the most determined of chefs. Nobles will pay exorbitant amounts to have just a taste of this delicacy, spiced and cooked to one's delight.\n\nI speak, of course, of the saurolisk tail.\n\nI must discover the finest method of cooking this sought after comestible! Boiled? Braised? Poached? Perhaps steamed or blanched is the most appropriate method!\n\nI will, of course, need a few tails to test.", objectives = "Collect 5 Saurolisk Tails from Lichenjaw Saurolisks." }
WordHunterWoW_QuestEN[49465] = { title = "Maximizing Resources", description = "Let me tell you a thing about my employees.\n\nThey're always blowing things out of proportion! I give them a good job with a steady wage and what do they do? They try to make excuses as to why they can't work!\n\nThey say the trees have come alive. Trees? Walking and fighting? If you're going to lie, at least make it more believable.\n\nIf they want to convince me, I'm going to need cold hard proof.", objectives = "Collect 5 Wood-Adorned Skulls in Algerson Lumber Yard.", progress = "I give them an honest job with good pay. This is the thanks I get?", completion = "<Algerson examines the skull.>\n\nNow this... this is something! Why are my workers running, they should be harvesting!\n\nWe could make a killing with these!" }
WordHunterWoW_QuestEN[49467] = { title = "Witch of the Woods", description = "A... a witch?!\n\nI uh... I would love to help you, truly I would but... I must report to my father.\n\nWhy don't you go stop the witch yourself? For a brave adventurer like you, a witch should be no problem.\n\nI'm sure my father would reward you greatly!", objectives = "Kill the Witch of the Woods in Fernwood Ridge.", progress = "My son told me about the witch, <name>. I've come up here to take care of her! If you want something done right, you need to do it yourself.", completion = "<Maynard studies the locket.>\n\nThat ungrateful woman!" }
WordHunterWoW_QuestEN[49468] = { title = "Required Webinar", description = "I'm not surprised some of the workers stayed in the woods, even amidst the beasts. While he won't admit it, some of father's workers are extremely dedicated.\n\nAnd now they're trapped by the spiders!\n\nPerhaps they have information about what is going on here. Free them from their webbings and see what they know!", objectives = "Free 5 Webbed Lumberjacks.", completion = "A witch?! This is all because of a witch?!" }
WordHunterWoW_QuestEN[49472] = { title = "A Titanic Effort", description = "Illidan may have forced fate's hand, but bringing Argus so near to Azeroth has accelerated the reaction triggered by the Nightwell's collapse.\n\nI believe the Legion's actions on Argus are further destabilizing the powers we've drawn upon unknowingly for many years.\n\nIt is clear that further studies are required.", objectives = "Bring 50 Wakening Essence to Arcanomancer Vridiel.", progress = "Illidan may believe that no price is too high to pay for banishing the Legion, but fate might prove him wrong.", completion = "The changes this substance has undergone since the Vindicaar departed for Argus are alarming.\n\nWhat will the outcome mean for Azeroth? I fear this to be an ill omen, <name>." }
WordHunterWoW_QuestEN[49473] = { title = "A Titanic Effort", description = "The reaction's intensity is accelerating by the day. We may win the fight against the Legion only to lose something very dear to us.\n\nIs this a portent of some greater upheaval to come? What fate awaits our world, <name>?\n\nI will seek answers at my forge, as I have done all my life. Your answers, I suspect, lie elsewhere.", objectives = "Bring 50 Wakening Essence to Arcanomancer Vridiel.", progress = "If I do not soon discover the underlying cause of this disturbance, I fear we may find ourselves too far down the path to turn back.", completion = "Take this. May it aid your efforts to stop the Legion... and to save our world." }
WordHunterWoW_QuestEN[49474] = { title = "The Cursed Shard", description = "<A unnatural metallic shard catches your eye as it shifts from color to color. At your touch, one end of the shard swells in size before melting away. Droplets hit the ground with a hiss and a noxious stench invades your nostrils.\n\nSomeone in Dalaran who works with metals should be able to tell you more.>", objectives = "Bring the Cursed Shard to Arcanomancer Vridiel in Dalaran on the Broken Isles.", completion = "The Betrayer lives up to his name once more." }
WordHunterWoW_QuestEN[49477] = { title = "Surprise Backup", description = "<You find a torn Horde missive on the ground...\n\nIt appears that a group of forsaken, led by a man named Chadwick Paxton, were sent here to investigate Nazmir.\n\nYou're unable to discern why they were sent here, but there are coordinates that indicate where they were going.\n\nYou may be able to find the scouts at the coordinates and enlist their aid in fighting the blood trolls.>", objectives = "Find Chadwick Paxton, leader of the Forsaken Scouting Party.", completion = "Oh. Hello there, fancy meeting you out here in a swamp. Yes, I'm Chadwick Paxton, or approximately half of him. Care to help?" }
WordHunterWoW_QuestEN[49479] = { title = "Didn't Stop to Think if They Should", description = "The sethrak seem to believe there's something in Nazmir that can unlock the destructive power of this gem.\n\nWe don't have that, but we have the next best thing. An insane warlock who is willing to experiment with magic.\n\nSpeak with Ingrid and have her begin the process to unlock the true power of this gem.", objectives = "Have Ingrid empower the Skycaller Gem.", progress = "Just be careful around Ingrid, she can get a little carried away.", completion = "That gem appears ready to do some damage. Let's just... point it elsewhere, for now." }
WordHunterWoW_QuestEN[49488] = { title = "Tal'gurub", description = "My prophet is a loyal servant, but he has his own ideas of how things must be.\n\nI am sending him to Tal'gurub to deal with a mess of his own making. One of his pupils, a witch doctor by de name of Vol'jamba, has taken de Gurubashi enclave as his own and has ousted my guards.\n\nMeet Zul at Tal'gurub and ensure dis nuisance is dealt with. Do not let him get... distracted.", objectives = "Meet Zul the Prophet in Tal'gurub.", completion = "Ah, yes, my new escort!\n\nYou are here to enforce de king's will. I would hate for ol' Rastakhan to become disappointed with you, especially after your performance in Stormwind." }
WordHunterWoW_QuestEN[49489] = { title = "Needs a Little Body", description = "I am here primarily to deal with my wayward student. His followers, however, I will leave to you.\n\nI have seen a possible future dat is... concerning. Rivers running red with poison, dead filling de streets. And dese... \"Jambani\" asserting themselves as de new rulers of Zuldazar. Dis cannot come to pass.\n\nFortunately for you, I know how to avoid dat fate. I think you will find their cauldrons are missing one key ingredient.\n\n<He stares at you.>\n\nSomething to give it a little body, perhaps?", objectives = "\"Improve\" 2 concoctions prepared by the Atal'Jamba acolytes.", progress = "We would not want dem to forego a crucial ingredient, would we?", completion = "Fight fire with fire, dey say. Or in dis case, poison with idiots who chew de ankles of their betters." }
WordHunterWoW_QuestEN[49490] = { title = "The Urn of Voices", description = "Vol'jamba does possess de Sight, and so even now he is taking precautions against us.\n\nRegrettably his vision is incomplete. You will help me prepare for his demise and deal with his followers simultaneously. De tool you will use is called de Urn of Voices.\n\nTake it and venture into Tal'gurub. Slay his followers, destroy their golems and masks. Their spirits, once released, will fill de urn.\n\nOh, and try not to die while holding it. De Urn of Voices is not discerning.", objectives = "Collect 30 Ounces of Soul from enemies within Tal'gurub.", progress = "Vol'jamba will pay for his transgressions.", completion = "All according to plan. Do not worry for dem... dis was always their fate." }
WordHunterWoW_QuestEN[49491] = { title = "Fuel for the Voodoo", description = "Dere be no time! Dey be draining our spirits... using us... dark voodoo...\n\n<Loa Priestess Izita's spirit grows dim, and her voice is soft and distant.>\n\nDa totems... burn dem...\n\nDen we be free...!", objectives = "Collect 8 Voodoo Totems.", progress = "<The brazier burns brightly.>", completion = "<As the fire chews away at the totems, Gurubashi spirits rise from the ashes.>" }
WordHunterWoW_QuestEN[49492] = { title = "Arrogance of Vol'jamba", description = "Vol'jamba thinks his Sight has surpassed mine. I warned against such arrogance many years ago, but we see how well he listened.\n\n<Zul chuckles.>\n\nNo doubt he will attempt to deter us as we encroach upon his sanctum. Listen if you like, but remember dat he is desperate to save himself. His truth is distorted by fear.\n\nDestroy his masks and we will walk unharmed through dis passage.", objectives = "Destroy Vol'jamba's masks.", progress = "His arrogance blinds him. He will soon learn de error of his ways.", completion = "As I said, his truth is distorted by fear." }
WordHunterWoW_QuestEN[49493] = { title = "Zul's Ethical Dilemma", description = "Hm.\n\nDe Gurubashi have earned a reputation for betrayal and weakness. Their activities in Zul'Gurub will be a stain on our records for generations to come.\n\nOn de other hand...\n\nDe Zandalari are above de use of slaves. We are strong, capable. De very existence of mindslaves in dis great city is insulting.\n\nDere is a chant dat will free their minds. Use it near de mindslaves to free dem. \n\nOr you can simply kill dem. It makes no difference to me.", objectives = "Free 9 Mindslaves.", completion = "Weakness or pride... I think often on de Zandalari's priorities." }
WordHunterWoW_QuestEN[49494] = { title = "Zuvembi Brew", description = "Zuvembi brew is arguably a witch doctor's most insidious concoction.\n\nDriven by de cauldron master's strength of mind, Zuvembi brew takes de will of those who breathe its fumes. It makes dem compliant, easily manipulated.\n\nIt is low magic, relying upon ancient cantrips and recipes known only to witch doctors of a certain skill. If we want to eradicate dis brew, we must slay those dat brew it.\n\nFind de Zuvembi brewer lurking here and see dat dis knowledge is erased.", objectives = "Slay Zuvembi Brewer Zekal.", progress = "Dis primitive magic cannot be allowed to proliferate.", completion = "Good. Dis thread has been severed." }
WordHunterWoW_QuestEN[49495] = { title = "Enforcing Fate", description = "Vol'jamba is busy consolidating his power. His Sight has shown him dat he will fight, and perhaps even dat he will die, and so he looks to all his tools to save himself.\n\nI will need you to be my hands, as he will come as soon as I show myself. You will undo all de preparations he has made for dis day.\n\nDo as I say and we will both find ourselves enjoying de king's favor.", objectives = "Sabotage Vol'jamba's precautions.", progress = "His vision is imperfect. We will use dis to end him.", completion = "<Zul rubs his hands together.>\n\nGood. Now we are ready to draw him out." }
WordHunterWoW_QuestEN[49522] = { title = "Carentan's Payment", description = "Well done, my friend. Well done, indeed.\n\nYou see that dusty crate in the corner of the room? You'll find it contains the ancient scroll and a generous purse of gold, as we agreed.\n\nPlease, take your reward. You've certainly earned it.", objectives = "Open the Dusty Crate." }
WordHunterWoW_QuestEN[49523] = { title = "A Bad Deal", description = "<Carentan escaped!\n\nRoko, the tortollan merchant who set up this deal in the first place, will want to know what happened.\n\nWhen you last spoke, Roko said he would be heading to Boralus.>", objectives = "Speak with Roko in Tradewinds Market.", completion = "Hmm. A scam, was it? You have my apologies for putting you in harm's way.\n\nThis man should be delivered to justice. He may be in hiding now, but I am very, very patient." }
WordHunterWoW_QuestEN[49529] = { title = "Spring Cleaning", description = "", objectives = "" }
WordHunterWoW_QuestEN[49531] = { title = "The Beauty of Marketing", description = "While us Fizzbrackets may not be goblins, we still know a business opportunity when we see one! The resort staff is getting trained, the place is getting cleaned up, now all we need is some quality marketing!\n\n<Wulferd holds up a familiar looking box.>\n\nBehold! The wondrous Gnomish engineering feat that is the S.E.L.F.I.E. Camera! Now, if only there was a generous {race} willing to capture the radiance of this place.\n\nMake sure you look like you're enjoying yourself out there!", objectives = "Take S.E.L.F.I.E.s with the resort's sights and wildlife.", progress = "If your smile isn't at least half of the picture, I don't want to see it!", completion = "These are perfect, you look dashing! Now I need to figure out how to get these out to our target customers." }
WordHunterWoW_QuestEN[49532] = { title = "Warchief's Command: Shadowmoon Valley!", description = "All able-bodied members of the Horde are hereby ordered to report to Blood Guard Gulmok at Shadowmoon Valley in Outland.\n\nThe Burning Legion is attempting to lay siege to Shadowmoon Village, but our elite Kor'kron force is showing them what it means to fight against the Horde.\n\nCrush the Legion.\n\nFor the Horde!", objectives = "Speak to Blood Guard Gulmok at Shadowmoon Valley in Outland.", completion = "Welcome to the battlefield, grunt!" }
WordHunterWoW_QuestEN[49533] = { title = "Warchief's Command: Howling Fjord!", description = "All able-bodied members of the Horde are hereby ordered to report to Apothecary Lysander in Howling Fjord.\n\nThe Forsaken have established a stronghold on the eastern shores of Northrend.\n\nNow is the time to strike at the Scourge with our military might and a new plague that is being developed by the Royal Apothecary Society.\n\nFor the Horde!", objectives = "Speak to Apothecary Lysander in Howling Fjord.", completion = "Ah, <name>, you have arrived!\n\nLet's get to work." }
WordHunterWoW_QuestEN[49534] = { title = "Warchief's Command: Zul'Drak!", description = "All able-bodied members of the Horde are hereby ordered to report to Crusader Lord Lantinga in Zul'Drak.\n\nThe Scourge is massacring the local population in Zul'Drak and converting them over to be part of the Scourge army.\n\nAssist the Argent Crusade and the Ebon Blade in stopping this threat.\n\nFor the Horde!", objectives = "Speak with Crusader Lord Lantinga in Zul'Drak.", completion = "Death and acts of sacrilege pervert this land.\n\n<Lantinga lets out a drawn-out sigh.>\n\nThankfully, we're here to stop it." }
WordHunterWoW_QuestEN[49535] = { title = "Warchief's Command: Sholazar Basin!", description = "All able-bodied members of the Horde are hereby ordered to report to Archmage Pentarus in Dalaran over Crystalsong Forest.\n\nHemet Nesingwary, along with his expeditionary force, was sent to explore Sholazar Basin, but has gone missing.\n\nWe do not know much about the lush landscape of Sholazar, but there might be secrets in the basin that can give us an advantage in our fight against the Lich King.\n\nFor the Horde!", objectives = "Speak with Archmage Pentarus in Dalaran over Crystalsong Forest.", completion = "I am glad you're here, <race>. Hemet has not been heard from for quite some time, and I could really use your help finding him." }
WordHunterWoW_QuestEN[49536] = { title = "Warchief's Command: Storm Peaks!", description = "All able-bodied members of the Horde are hereby ordered to report to Rin Duoctane in Dalaran over Crystalsong Forest.\n\nThe goblins of K3 have built a city in Storm Peaks and have sent their ambassador to recruit adventurers.\n\nSpeak with Rin and see what the people of K3 need. They would make valuable allies in our fight against the Lich King.\n\nFor the Horde!", objectives = "Speak with Rin Duoctane in Dalaran over Crystalsong Forest.", completion = "Yo! Do I have an explosive proposition for you, pal...." }
WordHunterWoW_QuestEN[49537] = { title = "Warchief's Command: Icecrown!", description = "All able-bodied members of the Horde are hereby ordered to report to Sky-Reaver Klum in Dalaran over Crystalsong Forest.\n\nThe Warsong Offensive needs more adventurers to bolster their assault on assault Icecrown Citadel and Arthas himself.\n\nIt is time to make the Lich King pay for his crimes.\n\nFor the Horde!", objectives = "Speak to Sky-Reaver Klum in Dalaran over Crystalsong Forest.", completion = "The Warsong Offensive is ready to strike at the heart of the Scourge, <class>. Are you up to the challenge?" }
WordHunterWoW_QuestEN[49538] = { title = "Warchief's Command: Jade Forest!", description = "All able-bodied members of the Horde are hereby ordered to report to General Nazgrim in Orgrimmar.\n\nRecent victories in our naval battles against the Alliance strengthens our resolve.\n\nReport to Grommash Hold and assist the Horde's invasion fleet.\n\nFor the Horde!", objectives = "Report to General Nazgrim in Grommash Hold.", completion = "Lok'tar ogar, <name>. You've arrived not a moment too soon...." }
WordHunterWoW_QuestEN[49539] = { title = "Warchief's Command: Valley of the Four Winds!", description = "All able-bodied members of the Horde are hereby ordered to report to Chen Stormstout in the Valley of the Four Winds.\n\nThe adventuring spirit of the Stormstouts is something that the Horde can learn from.\n\nTravel with the Stormstouts and discover what secrets Pandaria holds.\n\nFor the Horde!", objectives = "Speak with Chen Stormstout in the Valley of the Four Winds.", completion = "You seem like someone who needs some excitement in their life. Excitement... and beer!" }
WordHunterWoW_QuestEN[49540] = { title = "Warchief's Command: Krasarang Wilds!", description = "All able-bodied members of the Horde are hereby ordered to report to Zhu's Watch in Krasarang Wilds.\n\nThere have been rumors that the pandaren living in Krasarang Wilds are not their usual self.\n\nSpeak with Ken-Ken at Zhu's Watch. Perhaps he has a better idea of what has happened to cause the pandaren to become lethargic.", objectives = "Speak with Ken-Ken in Krasarang Wilds.", completion = "What the dook is going on here, <race>?!\n\nWhy are pandaren so sad?!" }
WordHunterWoW_QuestEN[49541] = { title = "Warchief's Command: Kun-Lai Summit!", description = "All able-bodied members of the Horde are hereby ordered to assist Lorewalker Cho in Kun-Lai Summit.\n\nSpeak with a messenger grummle in Valley of the Four Winds. They will show you the way to Kun-Lai Summit.\n\nFor the Horde!", objectives = "Speak to the Messenger Grummle in Valley of the Four Winds.", completion = "Traveling to Kun-Lai? Right this way, wanderer, right this way!" }
WordHunterWoW_QuestEN[49542] = { title = "Warchief's Command: Townlong Steppes!", description = "All able-bodied members of the Horde are hereby ordered to report to Taran Zhu in Townlong Steppes.\n\nThe Shado-Pan want to reclaim their land from the clutches of the yaungol, but lack the numbers to do so.\n\nAssist them with their assault against the yaungol.\n\nFor the Horde!", objectives = "Speak with Taran Zhu in Townlong Steppes.", completion = "Welcome to Townlong Steppes, outsider.\n\nIf you insist on wandering in to the darkest places of Pandaria then far be it from me to not put you to good use." }
WordHunterWoW_QuestEN[49543] = { title = "Warchief's Command: Dread Wastes!", description = "All able-bodied members of the Horde are hereby ordered to report to Bowmistress Li on the Serpent's Spine in the Vale of Eternal Blossoms.\n\nThe Shado-Pan are attempting to stop the mantid army from invading the entirety of Pandaria.\n\nYou can reach Bowmistress Li by securing a kite and flying to the Serpent's Spine.\n\nDestiny calls!", objectives = "Speak with Bowmistress Li on the Serpent's Spine.", completion = "A volunteer for Dread Wastes duty? I think you might be the first.\n\nPleased to meet you." }
WordHunterWoW_QuestEN[49545] = { title = "Warchief's Command: Frostfire Ridge!", description = "All able-bodied members of the Horde are hereby ordered to report to Farseer Drek'Thar in Frostfire Ridge.\n\nThe destruction of the Dark Portal has stopped the Iron Horde invasion of Azeroth, but now we must to take the fight to them.\n\nWith Farseer Drek'Thar's aid, we will be able to establish a strategic position in Draenor to fight against our enemies.\n\nFor the Horde!", objectives = "Speak to Farseer Drek'Thar in Frostfire Ridge.", completion = "I am glad to see you are well after Tanaan Jungle.\n\nWe have much to do." }
WordHunterWoW_QuestEN[49546] = { title = "Warchief's Command: Gorgrond!", description = "All able-bodied members of the Horde are hereby ordered to report to Durotan in Gorgrond.\n\nDurotan is seeking allies to help us navigate the savage landscape of Gorgrond in hopes that we will find ancient powers to help us destroy the Iron Horde.\n\nSpeak with him and see what secrets the lands hold.\n\nFor the Horde!", objectives = "Speak to Durotan in Gorgrond.", completion = "Gorgrond is no place for armies. We are now stepping into the domain of legends." }
WordHunterWoW_QuestEN[49547] = { title = "Warchief's Command: Talador!", description = "All able-bodied members of the Horde are hereby ordered to report to Foreman Grobash in Talador.\n\nThe Iron Horde seek to control Talador. The area is perfect to send reinforcements to any other part of Draenor quickly and without resistance.\n\nForeman Grobash is currently establishing an outpost in Talador. Travel there and stop the Iron Horde.\n\nFor the Horde!", objectives = "Speak with Foreman Grobash in Talador.", completion = "It is good to see you, Commander <name>. I require your advisement." }
WordHunterWoW_QuestEN[49548] = { title = "Warchief's Command: Spires of Arak!", description = "All able-bodied members of the Horde are hereby ordered to report to Azik in Spires of Arak.\n\nThere have been wingless arakkoa seen fleeing from Spires of Arak. Rumors suggest that they are running from an Iron Horde superweapon.\n\nWe need to find out what is causing them to leave their homeland, and why their wings have withered.\n\nFor the Horde!", objectives = "Speak with Azik in the Spires of Arak.", completion = "<Azik looks you up and down.>\n\nAzik is betting you are someone of importance to your people.\n\nCome closer, friend. Azik could use your help." }
WordHunterWoW_QuestEN[49549] = { title = "Warchief's Command: Nagrand!", description = "All able-bodied members of the Horde are hereby ordered to report to Stone Guard Brox in Nagrand on Draenor.\n\nThrall is establishing a Horde outpost and needs help to stop the Warsong clan.\n\nSpeak with Bron Skyhorn to fly to Nagrand and meet up with the supply caravan.\n\nFor the Horde!", objectives = "Speak to Stone Guard Brox in Nagrand on Draenor.", completion = "They came at us... from... nowhere.\n\n<The stone guard nearly passes out.>" }
WordHunterWoW_QuestEN[49550] = { title = "Hero's Call: Shadowmoon Valley!", description = "All able-bodied citizens of the Alliance are to report to Wing Commander Nuainn in Shadowmoon Valley on Outland.\n\nThe Burning Legion are laying siege to Wildhammer Stronghold, endagering our people and threatening their lives.\n\nWe need to reinforce the stronghold and stop the Burning Legion's relentless assault!\n\nGlory to the Alliance!", objectives = "Speak with Wing Commander Nuainn in Shadowmoon Valley on Outland.", completion = "We're gettin' hammered out here, lad.\n\nI hope you're here to help." }
WordHunterWoW_QuestEN[49551] = { title = "Hero's Call: Howling Fjord!", description = "All able-bodied citizens of the Alliance are to report to Macalroy in Howling Fjord.\n\nThe port town of Valgarde is located in the heart of the Howling Fjord, and it allows for the Alliance to have an advantageous position to strike at the Scourge.\n\nAssist the soldiers stationed there.\n\nGlory to the Alliance!", objectives = "Speak with Macalroy in Howling Fjord.", completion = "What is it?!\n\nCan't you see I'm already busy trying to get this port ready, <race>?" }
WordHunterWoW_QuestEN[49552] = { title = "Hero's Call: Zul'Drak!", description = "All able-bodied citizens of the Alliance are to report to Crusader Lord Lantinga in Zul'Drak.\n\nThe Scourge is massacring the local population in Zul'Drak and converting them over to be part of the Scourge army.\n\nAssist the Argent Crusade and the Ebon Blade in stopping this threat.\n\nGlory to the Alliance!", objectives = "Speak with Crusader Lord Lantinga in Zul'Drak.", completion = "Death and acts of sacrilege pervert this land.\n\n<Lantinga lets out a drawn-out sigh.>\n\nThankfully, we're here to stop it." }
WordHunterWoW_QuestEN[49553] = { title = "Hero's Call: Sholazar Basin!", description = "All able-bodied citizens of the Alliance are to report to Archmage Pentarus in Dalaran over Crystalsong Forest.\n\nHemet Nesingwary, along with his expeditionary force, was sent to explore Sholazar Basin, but has gone missing.\n\nWe do not know much about the lush landscape of Sholazar, but there might be secrets in the basin that can give us an advantage in our fight against the Lich King.\n\nGlory to the Alliance!", objectives = "Speak with Archmage Pentarus in Dalaran over Crystalsong Forest.", completion = "I am glad you're here, <race>. Hemet has not been heard from for quite some time, and I could really use your help finding him." }
WordHunterWoW_QuestEN[49554] = { title = "Hero's Call: Storm Peaks!", description = "All able-bodied citizens of the Alliance are to report to Rin Duoctane in Dalaran over Crystalsong Forest.\n\nThe goblins of K3 have built a city in Storm Peaks and have sent their ambassador to recruit adventurers.\n\nSpeak with Rin and see what the people of K3 need. They would make valuable allies in our fight against the Lich King.\n\nGlory to the Alliance!", objectives = "Speak with Rin Duoctane in Dalaran over Crystalsong Forest.", completion = "Yo! Do I have an explosive proposition for you, pal...." }
WordHunterWoW_QuestEN[49555] = { title = "Hero's Call: Icecrown!", description = "All able-bodied citizens of the Alliance are to report to Officer Van Rossem in Dalaran over Crystalsong Forest.\n\nThe Valiance Expedition needs more adventurers to bolster their assault on assault Icecrown Citadel and Arthas himself.\n\nIt is time to make the Lich King pay for his crimes.\n\nGlory to the Alliance!", objectives = "Speak with Officer Van Rossem in Dalaran over Crystalsong Forest.", completion = "The Valiance Expedition is ready to strike at the heart of the Scourge, <class>. Are you up to the challenge?" }
WordHunterWoW_QuestEN[49556] = { title = "Hero's Call: Jade Forest!", description = "All able-bodied citizens of the Alliance are to report to Stormwind Keep in Stormwind.\n\nGrand Admiral Jes-Tereth is assembling a team for a high priority mission.\n\nHead to Stormwind Keep immediately to be briefed.\n\nGlory to the Alliance!", objectives = "Report to Grand Admiral Jes-Tereth in Stormwind Keep.", completion = "Our role is of utmost importance, <name>.\n\nAdmiral Taylor and his flagship have gone missing.... More importantly, the young Prince was with him, and it is our primary objective to bring him back home safely." }
WordHunterWoW_QuestEN[49557] = { title = "Hero's Call: Valley of the Four Winds!", description = "All able-bodied citizens of the Alliance are to report to Chen Stormstout in the Valley of the Four Winds.\n\nThe adventuring spirit of the Stormstouts is something that the Alliance can learn from.\n\nTravel with the Stormstouts and discover what secrets Pandaria holds.\n\nGlory to the Alliance!", objectives = "Speak with Chen Stormstout in the Valley of the Four Winds.", completion = "You seem like someone who needs some excitement in their life. Excitement... and beer!" }
WordHunterWoW_QuestEN[49558] = { title = "Hero's Call: Krasarang Wilds!", description = "All able-bodied citizens of the Alliance are to report to Zhu's Watch in Krasarang Wilds.\n\nThere have been rumors that the pandaren living in Krasarang Wilds are not their usual self.\n\nSpeak with Ken-Ken at Zhu's Watch. Perhaps he has a better idea of what has happened to cause the pandaren to become lethargic.", objectives = "Speak with Ken-Ken in Krasarang Wilds.", completion = "What the dook is going on here, <race>?!\n\nWhy are pandaren so sad?!" }
WordHunterWoW_QuestEN[49559] = { title = "Hero's Call: Kun-Lai Summit!", description = "All able-bodied citizens of the Alliance are to assist Lorewalker Cho in Kun-Lai Summit.\n\nSpeak with a messenger grummle in Valley of the Four Winds. They will show you the way to Kun-Lai Summit.\n\nGlory to the Alliance!", objectives = "Speak to the Messenger Grummle in Valley of the Four Winds.", completion = "Traveling to Kun-Lai? Right this way, wanderer, right this way!" }
WordHunterWoW_QuestEN[49560] = { title = "Hero's Call: Townlong Steppes!", description = "All able-bodied citizens of the Alliance are to report to Taran Zhu in Townlong Steppes.\n\nThe Shado-Pan want to reclaim their land from the clutches of the yaungol, but lack the numbers to do so.\n\nAssist them with their assault against the yaungol.\n\nGlory to the Alliance!", objectives = "Speak with Taran Zhu in Townlong Steppes.", completion = "Welcome to Townlong Steppes, outsider.\n\nIf you insist on wandering in to the darkest places of Pandaria then far be it from me to not put you to good use." }
WordHunterWoW_QuestEN[49561] = { title = "Hero's Call: Dread Wastes!", description = "All able-bodied citizens of the Alliance are to report to Bowmistress Li on the Serpent's Spine in the Vale of Eternal Blossoms.\n\nThe Shado-Pan are attempting to stop the mantid army from invading the entirety of Pandaria.\n\nYou can reach Bowmistress Li by securing a kite and flying to the Serpent's Spine.\n\nGlory to the Alliance!", objectives = "Speak with Bowmistress Li on the Serpent's Spine.", completion = "A volunteer for Dread Wastes duty? I think you might be the first.\n\nPleased to meet you." }
WordHunterWoW_QuestEN[49562] = { title = "Hero's Call: Shadowmoon Valley!", description = "All able-bodied citizens of the Alliance are to report to Prophet Velen in Shadowmoon Valley on Draenor.\n\nThe destruction of the Dark Portal has stopped the Iron Horde invasion of Azeroth, but now we must to take the fight to them.\n\nWith Prophet Velen's blessing, we will be able to establish a strategic position in Draenor to fight against the enemies of Azeroth.\n\nGlory to the Alliance!", objectives = "Speak with Prophet Velen in Shadowmoon Valley on Draenor.", completion = "<Prophet Velen welcomes you with a curious look, then a warm nod.>\n\nSo it begins...." }
WordHunterWoW_QuestEN[49564] = { title = "Hero's Call: Gorgrond!", description = "All able-bodied citizens of the Alliance are to report to Yrel in Gorgrond.\n\nYrel and Maraad are requesting for a small expedition to be sent into the wilds of Gorgrond.\n\nWe hope to gain a better understanding of the land in hopes that it will show us how to exploit weaknesses in the Iron Horde.\n\nAssist them with their expedition.\n\nGlory to the Alliance!", objectives = "Speak with Yrel in Gorgrond.", completion = "Welcome to Gorgrond, commander.\n\nWe have just arrived ourselves." }
WordHunterWoW_QuestEN[49565] = { title = "Hero's Call: Talador!", description = "All able-bodied citizens of the Alliance are to report to Foreman Eksos in Talador.\n\nThe Iron Horde seek to control Talador. The area is perfect to send reinforcements to any other part of Draenor quickly and without resistance.\n\nForeman Eksos is currently establishing an outpost in Talador. Travel there and stop the Iron Horde.\n\nGlory to the Alliance!", objectives = "Speak with Foreman Eksos in Talador.", completion = "It is good to see you, Commander <name>. I require your advisement." }
WordHunterWoW_QuestEN[49566] = { title = "Hero's Call: Spires of Arak!", description = "All able-bodied citizens of the Alliance are to report to Azik in Spires of Arak.\n\nThere have been wingless arakkoa seen fleeing from Spires of Arak. Rumors suggest that they are running from an Iron Horde superweapon.\n\nWe need to find out what is causing them to leave their homeland, and why their wings have withered.\n\nGlory to the Alliance!", objectives = "Speak with Azik in the Spires of Arak.", completion = "<Azik looks you up and down.>\n\nAzik is betting you are someone of importance to your people.\n\nCome closer, friend. Azik could use your help." }
WordHunterWoW_QuestEN[49567] = { title = "Hero's Call: Nagrand!", description = "All able-bodied citizens of the Alliance are to report to Lieutenant Balfor in Nagrand on Draenor.\n\nYrel is recommending that the Alliance establish an outpost in Nagrand to help in our fight against the Warsong clan.\n\nSecure a flight to Nagrand and meet up with Lieutenant Balfor and the supply caravan.\n\nGlory to the Alliance!", objectives = "Speak with Lieutenant Balfor in Nagrand on Draenor.", completion = "They came at us... from... nowhere.\n\n<The lieutenant nearly passes out.>" }
WordHunterWoW_QuestEN[49569] = { title = "Down by the Riverside", description = "We have de aid of Krag'wa and de Gob Squad. We must get back to Zul'jan and begin our plan to stop de blood trolls.\n\nWe have one problem. De Gob Squad are unable to move their mech fast enough in de jungle. We must take it by boat.\n\nDe two of us will ride with dem and ensure de blood trolls do not destroy de mech.\n\nI will run ahead and get de boat ready near de riverbank. Meet us dere.", objectives = "Sail down the river with Talanji and defend the Gob Squad's A.M.O.D.", completion = "We made it, <name>. Now comes de hard part. Are you ready?" }
WordHunterWoW_QuestEN[49570] = { title = "A Rocky Start", description = "<As you thumb through the book, the pages are unusually thick and embedded on their surface are runic-shaped jewels. Samuel Colton notices you looking and approaches.>\n\nAh, now that's a treasure I've had for many years. Beautiful, isn't it? No clue what it says, but I've always reveled at the thought of something being transcribed in jewels.\n\nCome to think of it, I wonder if Zooey Inksprocket would be able to decipher it. Say, {name}, would you mind taking it over to her and see if she can translate it?", objectives = "Bring the book to Zooey Inksprocket and see if she can translate the text.\n\nProvided item:", completion = "Y-yes? Can I help you?\n\n<You hand the book over to Zooey and ask for it to be translated. As she turns each page, wondrous expressions cross the scribe's face.>\n\nOh my, I've only ever heard of such books in existence but have never seen one up close. Do you know what this is?\n\nIt's ancient earthen. And this book must be centuries old!\n\nOf course I'll help translate it! Only... well... my ancient earthen isn't so great. I'll need some reference materials." }
WordHunterWoW_QuestEN[49571] = { title = "Digging Through the Past", description = "Let's see, Jane Hudson probably still has her book on ancient runes and carvings. And I believe Tal'ana has a few scrolls he picked up from Ulduar.\n\nOH! And Toopa found what appeared to be some type of codex the last time he ventured out. I remember seeing the runes on it and they bear a striking resemblance to the ones in this book.\n\nIf you could convince them to uh... lend us those items for a bit, I believe I just might be able to create a translation for you. I won't even charge you for it!", objectives = "Ask Jane Hudson for her book of Primordial Races: Runes and Writings. Ask Tal'ana for his Scrolls of the Stonefather. And ask Toopa for the The Dungard Codex.", progress = "How goes the translation?", completion = "Was she able to translate it?\n\n<You hand the book over to Samuel and he begins to read it.>\n\nThis is incredible. This earthen was able to create jewels with light at special shrines he built. I mean, he mentions building several of them all over the world but...\n\n<Samuel pulls out a few maps and begins scanning them.>" }
WordHunterWoW_QuestEN[49572] = { title = "The Shrine of the Sea", description = "This next shrine is right here, in Tiragarde Sound.\n\nAccording to the journal, the earthen mentions creating bluish hued jewels. I wonder if that's anything like the kyanite we have here.\n\nGo and see if the shrine still stands. Hopefully it's still in a usable state.\n\nI'll continue to study the journal for more information.", objectives = "Investigate the Shrine of the Sea in Tiragarde Sound.", completion = "<As you peer at the shrine in front of you, you can't help but revel at the construction of it.\n\nSeamlessly constructed with azure jewels placed just so in a radial pattern, collapsing towards a single point.\n\nA single, empty point.>" }
WordHunterWoW_QuestEN[49573] = { title = "The Shrine of the Eventide", description = "There are two more shrines here on Kul Tiras.\n\nI believe this next one resides within Drustvar, near the Bleak Hills Mine, southeast of Corlain.\n\nHere are the notes on that shrine. Should it also need mending, I'm positive your skills with jewels can meet the challenge of repairing it.", objectives = "Travel to the location marked on your map and investigate the shrine in Drustvar. Do what you can to repair the shrine, should the need arise.", completion = "<Inspecting the shrine, you realize that several of the gems embedded on its surface are cracked and need to be replaced.>" }
WordHunterWoW_QuestEN[49574] = { title = "The Shrine of Storms", description = "Yes, I believe there are a few here in Kul Tiras. You should visit them, {name}, investigate them. See if what this book says is true.\n\nThis particular shrine he mentions sounds like it may reside near Brennadam, in Stormsong Valley.\n\nIt should be fairly easy to find. If my calculations are correct, it should be just north of that town.\n\nHere are the notes on that one. And I've marked its location for you on your map. Good luck, {name}.", objectives = "Travel to the location marked on your map and investigate the shrine in Stormsong Valley. Do what you can to repair the shrine, should the need arise.", completion = "<Upon your investigation you discover that the shrine has a couple locations where jewels appeared to have been located, but no longer exist.\n\nAdditionally, the center jewel appears to have several cracks in it as well.>" }
WordHunterWoW_QuestEN[49575] = { title = "Tol Dagor: Jewel of the Tides", description = "<An absence you assume to be a mistake, you quickly survey the area for something that might fit there yet you find nothing.\n\nHowever, there appears to be a drunk here shouting at the shrine. Perhaps he might know the whereabouts of the shrine's missing piece.>", objectives = "Speak with \"Slippery\" Salton and learn what you can about the missing centerpiece.", progress = "<Perhaps finding the missing centerpiece will give you a clue into the shrine's operation?>", completion = "<As you affix the gem back into the center of the shrine, a strange pulse emanates from it.\n\nThe shrine, now whole again, begins to hum with energy.>" }
WordHunterWoW_QuestEN[49576] = { title = "High Prospects", description = "<Checking your notes, you find that the earthen had extracted the gems from some earth elementals to the south.\n\nLooking at your map, you wonder if he was referring to the now ruins of a once ancient settlement that has become littered with constructs and undead.\n\nPerhaps investigating there will yield some clues as to where to find these jewels.>", objectives = "Investigate Gol Osigr for clues about the jewels that were used to construct the shrine.", progress = "<All of the cracked jewels will definitely need to be replaced.>", completion = "<You begin to remove all the cracked gems from the shrine and carefully start placing the new ones in.\n\nPlacing the final one, a pulse radiates from the shrine, as the light in the area seems to draw into it.\n\nThat strange, similar glow now emanating from the shrine leads you to believe it is once again active.>" }
WordHunterWoW_QuestEN[49577] = { title = "Cracking the Surface", description = "<Checking your notes, the earthen mentions having prospected the jewels from a nearby mountain to the northwest.\n\nPerhaps you can prospect the earth in that area to find more of those jewels and repair the shrine.>", objectives = "Go to the Windshorn Hills and gather 20 Shard of Golden Beryl.", progress = "<The placement of the jewels on this shrine appear to be placed in a rather intricate fashion.>", completion = "<Using your tools, you carefully shape the jewels and affix them into the empty slots on the shrine.\n\nUsing the remainder, you are able to fill in the cracks of the center jewel, giving it a flush surface.\n\nAs you place the final jewel, a similar pulse of energy radiates from the shrine as the light in the area seems to draw into it. A strange glow now emanating from the shrine leads you to believe it is once again active.>" }
WordHunterWoW_QuestEN[49578] = { title = "REUSE ME", description = "I've been to Zandalar before. Crazy place, full of dinosaurs and other unspeakable beasts. However one of the shrine's locations the journal speaks of sounds like a place they call Vol'dun.\n\nIt's a foreboding desert, full of canyons, with a great pyramid in the center.\n\nIf my calculations are correct though, the shrine ought to be around this area. I'll mark it for you on your map.\n\nAnd let's hope it's still in one piece.", objectives = "Travel to the location marked on your map and investigate the shrine in Vol'dun. Do what you can to repair the shrine, should the need arise.I've been to Zandalar before. Crazy place, full of dinosaurs and other unspeakable beasts. However one of the shrine's locations the journal speaks of sounds like a place they call Vol'dun.\n\nIt's a foreboding desert, full of canyons, with a great pyramid in the center.\n\nIf my calculations are correct though, the shrine ought to be around this area. I'll mark it for you on your map.\n\nAnd let's hope it's still in one piece.You will receive:" }
WordHunterWoW_QuestEN[49579] = { title = "REUSE ME", description = "This next shrine might be a bit difficult to get to. It resides in Zandalar, the heart of the troll empire.\n\nWell, maybe not the main city itself, but close to it. Actually...\n\n<Samuel checks a map he has laid out.>\n\nAh, it's not too far from (POI). I've heard there's been some strife there between the Horde and Alliance. Perhaps there's a camp there you can work out of.\n\nHere are you notes for the shrine and the location for it should be marked on your map.", objectives = "Travel to the location marked on your map and investigate the shrine in Zandalar. Do what you can to repair the shrine, should the need arise.This next shrine might be a bit difficult to get to. It resides in Zandalar, the heart of the troll empire.\n\nWell, maybe not the main city itself, but close to it. Actually...\n\n<Samuel checks a map he has laid out.>\n\nAh, it's not too far from (POI). I've heard there's been some strife there between the Horde and Alliance. Perhaps there's a camp there you can work out of.\n\nHere are you notes for the shrine and the location for it should be marked on your map.You will receive:" }
WordHunterWoW_QuestEN[49580] = { title = "REUSE ME", description = "The last shrine resides in Nazmir, a swamp infested with deadly creatures and home of the blood trolls.\n\nLuckily an ally of mine gave me a rather detailed map of that region and if my calculations are correct...\n\n<Samuel looks quickly back and forth between the journal and his map and finally stops his finger on the map.>\n\nIt should be right there. Take note of its location and here are the notes for that shrine. Good luck, {name}.", objectives = "Travel to the location marked on your map and investigate the shrine in Nazmir. Do what you can to repair the shrine, should the need arise.The last shrine resides in Nazmir, a swamp infested with deadly creatures and home of the blood trolls.\n\nLuckily an ally of mine gave me a rather detailed map of that region and if my calculations are correct...\n\n<Samuel looks quickly back and forth between the journal and his map and finally stops his finger on the map.>\n\nIt should be right there. Take note of its location and here are the notes for that shrine. Good luck, <name>.You will receive:" }
WordHunterWoW_QuestEN[49581] = { title = "Sun-Speckled Dunes", description = "<Looking at your notes, the earthen mentions coming across dunes sprinkled with orange gems. He said it reminded him of the soft sunlight in this area.\n\nChecking your notes, it appears that these dunes were located south of your current location.>", objectives = "Go to the location on your map where you believe these gems to be and recover 8 of them. Polish and shape them when you've collected enough.", progress = "<These gems have a very strong structure. Time, in addition to the winds, must have also taken its toll on them.>", completion = "<You carefully remove the old, weathered gems from the shrine and replace your polished gems in their place.\n\nAs you place the final gem, a similar pulse of energy radiates from the shrine as the light in the area seems to draw into it. A strange glow now emanating from the shrine leads you to believe it is once again active.>" }
WordHunterWoW_QuestEN[49582] = { title = "Atal'Dazar: Not All That Glitters...", description = "<You reference your notes on the shrine and discover that these jewels came from a \"golden sanctuary\".\n\nGiven your location, that can only mean Atal'Dazar. Perhaps you could find a replacement from that ancient city.>", objectives = "Travel to Atal'Dazar and find a replacement for the broken jewel.", progress = "<When you're done replacing the central gem, you think you might still be able to sell the old one.>", completion = "<Returning to the shrine, you begin to pluck the old gem from its holding place. As you do, the gem cracks again and shatters in your hands.\n\nApparently these gems are much more fragile than you originally thought.\n\nVery carefully, you replace the gem you obtained into the slot.\n\nOnce affixed, the familiar pulse radiates once more from the shrine and the glow emanating from it confirms its restoration.>" }
WordHunterWoW_QuestEN[49583] = { title = "Out With the Old", description = "<It's clear though that time has had its way with these gems, some eroded and chipped in places.\n\nRepairing this shrine may be as simple as replacing the old gems with newer ones of the same type and cut.>", objectives = "Cut 4 Natant Rubellites and replace the old ones with the new.", progress = "<Interesting that the cut should be so similar, you wonder how the design has persisted all these years.>", completion = "<Replacing each gem, they fit perfectly into the slots confirming your suspicions of their similarities.\n\nAs you place the final gem, a peaceful glow now emanating from the shrine leads you to believe it is once again active.>" }
WordHunterWoW_QuestEN[49584] = { title = "The Missing Chapter", description = "<Samuel puts down the journal and looks back up at you.>\n\nWhile trying to figure out where the shrines reside, I came across an entry that mentioned him exploring an area that sounds very similar to Dustwallow Marsh.\n\nHe mentions hiding something of great importance there.\n\nIt's a long shot, given when this earthen roamed Azeroth, but perhaps if you were to retrace his final steps you may find something.\n\nI'll mark the location on your map.", objectives = "Travel to the location marked on your map and see what you can find.", progress = "Who knows what you may find out there. Hopefully something...", completion = "What did you find?\n\n<You hand the final chapter and its transcription over to Samuel. As he reads through it, he reaches the page with the design for the lens and his eyes go wide.>\n\nYou've found it, <name>! We can construct a lens now and use it with the shrines.\n\nAlthough, the reagents for this design are quite... rare. But nevertheless you've done it!\n\nIt was an honor to work with you on this, <name>." }
WordHunterWoW_QuestEN[49585] = { title = "A Rocky Start", description = "<As you thumb through the book, you see odd-looking runes carved out of jewels embedded in the stone pages. Seshuli notices you looking and approaches you.>\n\nAh, dat's been a treasure of mine for many years. Beautiful, isn't it? No clue what it says, but I've always reveled at de thought of something being written in jewels.\n\nCome to think of it, I wonder if Grazzul would know what it says. {name}, would you mind taking it over to him and see if he can translate it?", objectives = "Bring the book to Grazzul and see if he can translate the text.\n\nProvided item:", completion = "What do you need?\n\n<You hand the book over to Grazzul and ask for it to be translated. As he turns each page, wondrous expressions cross the scribe's face.>\n\nI've only heard of such books in existence but I've never seen one before. Do you know what dis is?\n\nDis is ancient earthen. And dis book is centuries old!\n\nOf course I'll help to translate it, only... well... my ancient earthen isn't so great. I'll need some things to do dis." }
WordHunterWoW_QuestEN[49586] = { title = "Digging Through the Past", description = "Let's see, Examiner Alerinda has a book on ancient runes and carvings. I think Koatini has a few scrolls he brought with him from Ulduar.\n\nOH! And Chronicler Shoopa found a codex de last time he ventured out. I remember seeing de runes on it and dey look a lot like de ones in dis book.\n\nMaybe you can convince dem to lend us dose books for a bit, and I think I can create a translation for you.", objectives = "Ask Examiner Alerinda for her book of Primordial Races: Runes and Writings. Ask Koatini for his Scrolls of the Stonefather. And ask Chronicler Shoopa for the The Dungard Codex.", progress = "How is de translation going?", completion = "Was he able to translate it? \n\n<You hand the book over to Seshuli and she begins to read it.>\n\nDis is incredible. Dis earthen was able to create jewels with de light. And dose shrines he's built, I mean, he mentions building several of dem but...\n\n<Seshuli pulls out a few maps and begins scaninng them.>" }
WordHunterWoW_QuestEN[49587] = { title = "The Shrine of Nature", description = "Another shrine resides right here in Zuldazar.\n\nAccording to de journal, de earthen talks about creating green hued jewels dere. I wonder if dat's anything like de viridium we find in de ore we mine.\n\nGo and see if de shrine still stands. Hopefully, we can still make use of it.\n\nI'll continue to study de journal for more information.", objectives = "Investigate the Shrine of Nature in Zuldazar.", completion = "<As you observe the shrine, it's quite clear that the central jewel is badly broken and in need of replacement.>" }
WordHunterWoW_QuestEN[49588] = { title = "The Shrine of the Sands", description = "Dere are two more shrines here on Zandalar. Dis next one resides within Vol'dun, near Bonetrail Gulch.\n\nHopefully de Faithless haven't defiled de shrine.\n\nHere are de notes on dat location. Should dat shrine also need fixing, I think your skills with jewels will probably be enough to fix it.", objectives = "Travel to the location marked on your map and investigate the shrine in Vol'dun. Do what you can to repair the shrine, should the need arise.", completion = "<Surveying the shrine, you believe that the sandy winds in this area have worn down the embedded gems, producing odd shapes and cracks in some.>" }
WordHunterWoW_QuestEN[49589] = { title = "The Shrine of the Dawning", description = "Yea, I believe there are a few here on Zandalar. You should find dem, {name}, investigate dem. See if what dis book says is true.\n\nDis particular shrine sounds like it might be in Nazmir. If my calculations are correct, it should be just south of Torga's Rest.\n\nDat loa was a mighty one. It is truly sad dat it is no longer with us.\n\nHere are de notes on dat one. And I've marked its location for you on your map. Loa be with you, {name}.", objectives = "Travel to the location marked on your map and investigate the shrine in Nazmir. Do what you can to repair the shrine, should the need arise.", completion = "<Upon inspection of the shrine, you notice something... familiar.\n\nThe cut of the gems looks like a primitive or simple version of the way you've learned to cut rubellites.>" }
WordHunterWoW_QuestEN[49590] = { title = "REUSE ME", description = "As you peer from one gem to the next, you realize that the shrine appears to be fine, yet no power radiates from it.\n\nPulling out your jewelcrafting tools, you begin to inspect the central gem and realize that there is in fact a flaw. A small crack near the base of it that permeates through the gem towards the back.\n\nYou reference your notes on the shrine and discover that this gem came from a \"golden sanctuary\".\n\nPerhaps someone back at the Explorer's League Campsite will know what this means.", objectives = "Travel to the Reliquary Camp and ask around about the \"golden sanctuary\". Then find a replacement gem once you learn of its location.As you peer from one gem to the next, you realize that the shrine appears to be fine, yet no power radiates from it.\n\nPulling out your jewelcrafting tools, you begin to inspect the central gem and realize that there is in fact a flaw. A small crack near the base of it that permeates through the gem towards the back.\n\nYou reference your notes on the shrine and discover that this gem came from a \"golden sanctuary\".\n\nPerhaps someone back at the Explorer's League Campsite will know what this means." }
WordHunterWoW_QuestEN[49591] = { title = "REUSE ME", description = "Surveying the shrine, you believe that the sandy winds in this area have worn down the embedded gems, producing odd shapes and cracks in some.\n\nLooking at your notes, the earthen mentions coming across dunes sprinkled with orange gems. He said it reminded him of the soft sunlight in this area.\n\nSamuel added his own note saying he believes the location of these gems to be south of the shrine's location.", objectives = "Go to the location on your map where you believe these gems to be and recover $1oa of them. Polish and shape them as you find them.Surveying the shrine, you believe that the sandy winds in this area have worn down the embedded gems, producing odd shapes and cracks in some.\n\nLooking at your notes, the earthen mentions coming across dunes sprinkled with orange gems. He said it reminded him of the soft sunlight in this area.\n\nSamuel added his own note saying he believes the location of these gems to be south of the shrine's location." }
WordHunterWoW_QuestEN[49592] = { title = "REUSE ME", description = "Upon inspection of the shrine, you notice something... familiar. The cut of the gems looks like a primitive or simple version of the way you've learned to cut rubellites.\n\nIt's clear though that time has had its way with these gems, some eroded and chipped in places. \n\nRepairing this shrine may be as simple as replacing the old gems with newer ones of the same type and cut.", objectives = "Cut $1oa Insightful Rubellites and replace the old ones with the new.Upon inspection of the shrine, you notice something... familiar. The cut of the gems looks like a primitive or simple version of the way you've learned to cut rubellites.\n\nIt's clear though that time has had its way with these gems, some eroded and chipped in places. \n\nRepairing this shrine may be as simple as replacing the old gems with newer ones of the same type and cut." }
WordHunterWoW_QuestEN[49593] = { title = "REUSE ME", description = "I once viisted Kul Tiras. Da humans dere not be too friendly to us Zandalari. However one of da shrines be dere, in Tiragarde Sound.\n\nDat place have da most humans of all dat land. Ya need to be watchin' your back out dere, {name}.\n\nI'll mark da location of it on your map for ya.\n\nAnd let's be hoping dem humans didn't mess wit it.", objectives = "Travel to the location marked on your map and investigate the shrine in Tirigarde Sound. Do what you can to repair the shrine, should the need arise.I once viisted Kul Tiras. Da humans dere not be too friendly to us Zandalari. However one of da shrines be dere, in Tiragarde Sound.\n\nDat place have da most humans of all dat land. Ya need to be watchin' your back out dere, <name>.\n\nI'll mark da location of it on your map for ya.\n\nAnd let's be hoping dem humans didn't mess wit it." }
WordHunterWoW_QuestEN[49594] = { title = "REUSE ME", description = "Da next shrine be a in a place dey call Drustvar. From what I be hearin', dat place is full of witches.\n\nDey use deir magics to bring tings ta life. But lookin at da map and where I tink dis shrine be, ya may not be needing to run into any of dem.\n\nIt's pretty close ta da Smuggler's Cove. I'd make ya way dere and den find da shrine. I'll mark ya map for ya where I tink it is.", objectives = "Travel to the location marked on your map and investigate the shrine in Drustvar. Do what you can to repair the shrine, should the need arise.Da next shrine be a in a place dey call Drustvar. From what I be hearin', dat place is full of witches.\n\nDey use deir magics to bring tings ta life. But lookin at da map and where I tink dis shrine be, ya may not be needing to run into any of dem.\n\nIt's pretty close ta da Smuggler's Cove. I'd make ya way dere and den find da shrine. I'll mark ya map for ya where I tink it is." }
WordHunterWoW_QuestEN[49595] = { title = "REUSE ME", description = "Da last shrine in Kul Tiras be in a green place dey call Stormsong Valley. Da humans dere probably won't be givin' ya too much trouble.\n\nBut da shrine be pretty dead center in da land, so ya probably gonna have ta do some travelin'. I'll mark it on ya map for ya.", objectives = "Travel to the location marked on your map and investigate the shrine in Stormsong Valley. Do what you can to repair the shrine, should the need arise.Da last shrine in Kul Tiras be in a green place dey call Stormsong Valley. Da humans dere probably won't be givin' ya too much trouble.\n\nBut da shrine be pretty dead center in da land, so ya probably gonna have ta do some travelin'. I'll mark it on ya map for ya." }
WordHunterWoW_QuestEN[49596] = { title = "REUSE ME", description = "As you peer at the rock altar in front of you, you can't help but revel at the construction of it. Seamlessly constructed with azure jewels placed just so in a radial pattern, collapsing towards a single point.\n\nA single, empty point. An absence you assume to be a mistake. Quickly surveying the area for something that might fit there, you find nothing.\n\nHowever, someone who had not been there before has shown up. Perhaps he might know the whereabouts of the shrine's missing piece.", objectives = "Speak with \"Slippery Salton\" and learn what you can about the missing centerpiece.As you peer at the rock altar in front of you, you can't help but revel at the construction of it. Seamlessly constructed with azure jewels placed just so in a radial pattern, collapsing towards a single point.\n\nA single, empty point. An absence you assume to be a mistake. Quickly surveying the area for something that might fit there, you find nothing.\n\nHowever, someone who had not been there before has shown up. Perhaps he might know the whereabouts of the shrine's missing piece." }
WordHunterWoW_QuestEN[49597] = { title = "REUSE ME", description = "", objectives = "" }
WordHunterWoW_QuestEN[49598] = { title = "REUSE ME", description = "Upon your investigation you discover that the shrine has several locations where jewels appeared to have been located, but no longer exist. Checking your notes, the earthen mentions having prospected the jewels from a nearby mountain to the north.\n\nPerhaps you can prospect the earth in that area to find more of those jewels.", objectives = "Go to (NYI POI) and gather $1oa Jewel Shards.Upon your investigation you discover that the shrine has several locations where jewels appeared to have been located, but no longer exist. Checking your notes, the earthen mentions having prospected the jewels from a nearby mountain to the north.\n\nPerhaps you can prospect the earth in that area to find more of those jewels." }
WordHunterWoW_QuestEN[49599] = { title = "The Missing Chapter", description = "<Seshuli puts down the journal and looks back up at you.>\n\nWhile trying to figure out where de shrines reside, I came across an entry dat mentioned him exploring an area dat sounds very similar to Dustwallow Marsh.\n\nIt could be a long shot, given when dis earthen roamed Azeroth, but maybe if you retrace his final steps, you may find something.\n\nI'll mark his last location for you on your map.", objectives = "Travel to the location marked on your map and see what you can find.", progress = "Who knows what you'll find out dere. Hopefully something...", completion = "Did you find anything?\n\n<You hand the final chapter and its transcription over to Seshuli. As she reads through it, she reaches the page with the design for the lens and her eyes go wide.>\n\nYou found it, <name>! We can make a lens now and use it with de shrines.\n\nAlthough, de reagents for dis design are quite... rare. Still, you've done it!\n\nIt was an honor to work with you on dis, <name>." }
WordHunterWoW_QuestEN[49613] = { title = "Silvermoon City", description = "The nightborne have been isolated from the world for thousands of years. Now that they have reemerged, it is up to us to guide them along the right path.\n\nRegent Lord Theron has extended an invitation to the nightborne to meet with us in Silvermoon.\n\nCome, {name}, let us travel to Silvermoon with Thalyssra.", objectives = "Meet with Lady Liadrin in Silvermoon City.", completion = "Good, we're all here. Our guests should be arriving shortly." }
WordHunterWoW_QuestEN[49614] = { title = "The Nightborne", description = "The Warchief will be pleased with our success.\n\nThalyssra and her nightborne will prove strong allies, I am sure.", objectives = "Return to Ji Firepaw in Orgrimmar to hear the end of this tale.", completion = "You return with good news, <name>." }
WordHunterWoW_QuestEN[49615] = { title = "Trust of a King", description = "Well, now dat you are settled in, you had best go speak with my father. You can find him up upon de throne, his advisors close at hand, pouring poison in his ear, no doubt.\n\nDe lift behind you can take you to de Golden Throne above us.", objectives = "Speak with King Rastakhan at the Golden Throne.", completion = "Very prompt. Now, I have need of your hands." }
WordHunterWoW_QuestEN[49661] = { title = "Locally Sourced Eggs", description = "There is nothing in the world greater than food made from the best, freshest ingredients!\n\nMy good friend I am on a hunt. A hunt for the perfect eggs! I have heard tale of eel eggs. A delicate texture, a slight undersea saltiness... such a unique flavor profile! I must have them!\n\nThe eels here lay their eggs on the land before returning to the sea. Please, gather these eggs for me so that I may create only the most elegant of omelets!", objectives = "Collect 10 Coilscale Eggs from Coilscale Nests." }
WordHunterWoW_QuestEN[49662] = { title = "The Missing Key", description = "Korthek has grown spiteful and arrogant over the years, but I realize now that he has grown mad as well.\n\nMythrax will kill all of us if he is released.\n\nFor too long, I've held out hope that I could convince Korthek peacefully to abandon his heresy. I was wrong.\n\nAll of Zandalar is at risk while Korthek and his allies hold even one key to Mythrax's prison.\n\nMeet me outside his fortress in the north. We will confront my old friend \"Emperor\" Korthek and end this together.", objectives = "Meet Vorrik at Bwoljin's Fall.", completion = "We are surrounded by Faithless out here, <name>. We must move quickly." }
WordHunterWoW_QuestEN[49663] = { title = "False Prophecies", description = "Now dat dis nuisance is out of de way, I can return my focus to de city. Zuldazar has languished while I was away.\n\nYou should return to Rastakhan. Let de king know dat his will has been carried out and dat dis false prophet is no more.\n\nYou might think to share Vol'jamba's prophecy with him, if you feel it worth his notice. I cannot say it will change anything at all.", objectives = "Return to King Rastakhan at Dazar'alor.", completion = "Perhaps Zul will remember his place going forward." }
WordHunterWoW_QuestEN[49664] = { title = "Allies in Anarchy", description = "Even after all these years, I can feel the ancient power of Sethraliss in this place. My loa endures.\n\nOur task ahead is great and I will need a clear, focused mind to accomplish it. Allow me a few moments to meditate here, like I did in ages past.\n\nIn the meantime, you should help the vulpera stir up trouble however you can. They seem to know you, and a large enough disturbance will distract the Faithless from our mission.\n\nMeet me back here when you're done and we'll proceed together.", objectives = "Speak with Nisha.", completion = "<name>?! We gotta stop meeting in places like this.\n\nActually, let's ALWAYS meet in places like this!\n\nYou up for killing some Faithless?" }
WordHunterWoW_QuestEN[49665] = { title = "Ready to Riot", description = "Do you remember how we met, {name}? You were trapped in a Faithless cage, just like the ones in the crater below.\n\nTogether, we slaughtered Faithless and earned your freedom in blood.\n\nThe vulpera trapped in shackles below can do the same. They just need to be given the chance.\n\nSteal Faithless weapons and give them to the vulpera slaves below. They'll rise up and help you fight the Faithless.\n\nWe're going to start a revolt right under their arrogant noses.", objectives = "Free and arm 8 Vulpera Slaves in cages.", completion = "Look at my people fighting! The Faithless don't stand a chance!" }
WordHunterWoW_QuestEN[49666] = { title = "Make Them Fear Us", description = "I carry this banner into every battle because I want the Faithless to fear it. To fear my people.\n\nIf I die in the battlefield, surrounded by Faithless, I will die happy.\n\nOn that day, I will not need a burial or prayers. But I will need someone to pick up my banner and carry it into the next battle.\n\nIf you are of the same mind, plant these banners into the corpse of every Faithless you slay. Let the survivors know who's coming for them.", objectives = "Plant 12 Vulpera Banners into dead Faithless.", completion = "And that's just the start! Now the Faithless know who's coming for 'em." }
WordHunterWoW_QuestEN[49667] = { title = "The Little Ones", description = "Just when I thought the Faithless couldn't get any worse, I find out that they're keeping vulpera children trapped down in that crater!\n\nThe other vulpera we rescued told me that a big sethrak, Appraiser Versik, is inspecting them on the central platform to determine what he can sell them for.\n\nSelling vulpera kids! Oooh, those Faithless make me so angry!\n\nPlease, {name}. I'm no fighter. I can't rescue those kids. But if you bring them up here to me, I promise I'll get them out of here safely.", objectives = "Kill Appraiser Versik and lead the vulpera kids back to Meerah.", completion = "Thank you, thank you, thank you!\n\nThese children have already experienced more hate and pain than anyone ever should. I'll make sure they feel love in equal measure." }
WordHunterWoW_QuestEN[49668] = { title = "Light Up the Gulch", description = "Don't mistake my caution for hesitance, {name}. I will defend the vulpera with my dying breath... I'd just prefer to avoid taking that breath today.\n\nWhile Nisha rushes to the front line, I work behind them to ensure our success.\n\nMeet me at the Faithless beast pens if you'd like to help.\n\nOh, and take this torch. You'll be going through their marketplace, where they auction off slaves.\n\nStarting a few well-placed and metaphorically poignant fires along your route will make things easier for all of us.", objectives = "Torch the slave auction sites in Slithering Gulch.", completion = "The fires are spreading quickly. Let's hurry, while the Faithless are distracted." }
WordHunterWoW_QuestEN[49669] = { title = "Unleash the Beasts", description = "The Faithless are arrogant hoarders, capturing people and beasts that can never be truly tamed. All to fuel their endless lust for war.\n\nI've even seen their slavers dragging blood trolls and other dark monsters from the swamps of Nazmir.\n\nI heard terrible noises coming out of a cave while I was scouting the feeding pits up ahead.\n\nWhatever monsters they are hiding in there, find a way to free them and let them exact revenge on the Faithless.", objectives = "Kill Tamer Traskniss to release the crawgs.", completion = "Crawgs are violent, filthy things... Yet another reason to avoid Nazmir." }
WordHunterWoW_QuestEN[49676] = { title = "Dressed for Battle", description = "Kiro's the leader of my caravan. He's always been far too passive.\n\nI warned him we needed to make a preemptive strike against the sethrak, but he insisted that we keep our heads down and continue to quietly do business.\n\nLook where that got us.\n\nOur caravan was completely unprepared for their attack. \n\nNow I'm ready to fight for what's ours, but I'm not exactly dressed for battle.\n\nHelp me scavenge some suitable equipment here among our enemies. We will use their own tools against them.", objectives = "Help Nisha find a war banner, a helmet, and explosives.", progress = "Killing an enemy with their own sword is an even bigger insult, no?", completion = "Now we are ready for a real challenge!" }
WordHunterWoW_QuestEN[49677] = { title = "Plans for Attack", description = "Before we were attacked, I had a plan to take the fight to the sethrak. \n\nIt was devised with flawless intel. I know, because I gathered the information myself. \n\nI surveyed their entire compound and created a map based on my findings. \n\nMy plan relies on that map, but it's now in the hands of Fangcaller Sraka, the brute who's leading this assault on my home.\n\nHelp me kill her so I can take back what's mine!", objectives = "Recover Nisha's Attack Plans from Fangcaller Sraka.", progress = "My plan for attack is both detailed and dangerous.", completion = "These plans will be our key to taking the fight to the sethrak." }
WordHunterWoW_QuestEN[49678] = { title = "I Spy a Spire", description = "It is good you have come. Dol'watha be under attack by these snake-men.\n\nSoon as they arrived they started pulling these weird spire-things out de ground. I seen a bunch of snake-mons with feathers in their caps getting zapped by them, but they not be dying.\n\nIf it not be bad for them, that means it's good for them. And that be bad for us.\n\nDestroy those spires. Hopefully whatever boon they be getting will go away and they will be easier to kill.", objectives = "Destroy 4 Sethrak Spires.", completion = "Not so much static in de air now. That's good. Means we did something right." }
WordHunterWoW_QuestEN[49679] = { title = "The Sethrak Incursion", description = "Dol'watha be a small village. Got a few farms, some beasts, and a decent view of a swamp.\n\nLoa know we not be ready for this...\n\nDe snake-men popped out of de ground by de hundreds. Slaughtered my beasts, my family, my friends. One minute de earth rumbling, de next we be running for our lives.\n\nI heard about snake-men from de deserts of Vol'dun but I never believed I would see them in my life...\n\nHelp us fight back. Kill as many of them as you can. Dol'watha won't be beaten that easily!", objectives = "Slay 12 sethrak in Sandscar Breach.", completion = "Won't bring back de ones we lost, but it show them that not even little Dol'watha be going down without a fight." }
WordHunterWoW_QuestEN[49680] = { title = "Skycaller Soltok", description = "As if snake-men with swords not be bad enough, they brought a powerful skycaller along.\n\n I hear skycallers can tempt great storms into being. They be to blame for de spires and lightning flying everywhere.\n\nThere be one who wear a bigger feather than most, likely de leader. Calls herself Soltok or something equally hissy.\n\nDon't care. Kill her.", objectives = "Slay Skycaller Soltok.", completion = "Good, very good..." }
WordHunterWoW_QuestEN[49681] = { title = "Lil' Tika", description = "<The tiny armored raptor scratches pitifully at the cage's wooden bars. As you approach, the miniscule reptile wiggles frantically and issues a piercing screech for help!\n\nPerhaps you can open the cage and let it free.>", objectives = "Rescue Lil' Tika.", progress = "My poor beasts...", completion = "Why is she covered in blood?\n\nOn secon' thought, nevermind.\n\nPraise all deh loa, at least dis little one made it!" }
WordHunterWoW_QuestEN[49694] = { title = "Turn to Drust", description = "There are blood scribe masters all over the place who'll teach you what you need to know. The first master I'd recommend seeking out is Kronah.\n\nShe's a bit... eccentric to say the least. One of the few tortollan who've experienced a thing or two.\n\nShe's the one who taught me the blood contract I know how to invoke!\n\nShe likes to hang out at the Smuggler's Cove on the western coast of Drustvar. Oh, and could you say hi for me when you see her?!", objectives = "Seek out Kronah at the Smuggler's Cove in Drustvar.", completion = "<Kronah eyes you up and down warily.>\n\nSay ahhh for me, would you young one?\n\n<Kronah peers inside your mouth.>\n\nNice teeth you have there. Would fetch a fine price. But that's not really what you're here for, is it?\n\nNo, you're one of those who think they can handle the trials of the blood contracts, aren't you? Very well." }
WordHunterWoW_QuestEN[49698] = { title = "The Lightforged", description = "Do you wish to hear how the Lightforged draenei joined the Alliance? It might be one of my favorite stories.\n\nMost likely since it involves seeing our beautiful world from space!\n\nIt all began when High Exarch Turalyon invited members of the Alliance onto the Vindicaar...", objectives = "Travel to the Vindicaar.", progress = "This ritual has never been witnessed by an outsider.", completion = "Welcome, <name>. You are about to bear witness to a ritual none but members of the Army of the Light have seen." }
WordHunterWoW_QuestEN[49703] = { title = "House Stormsong", description = "I have little information to offer, I'm afraid. I've scarcely left Brennadam as of late.\n\nWhat they said is true. Our militia now enter town only to collect rations rather than guard traders or keep the quilboar at bay.\n\nThey say they are under orders, but those orders would only come from my brothers at the Shrine. We take oaths to serve our people... it simply does not add up.\n\nBrother Addington is nearby at Mariner's Strand. Perhaps he knows more than I.", objectives = "Meet Brother Pike and Taelia at Mariner's Strand.", completion = "What has become of our people..." }
WordHunterWoW_QuestEN[49704] = { title = "Haywire Harvesters", description = "See the golems down there? Farmers use their sharp claws to reap the harvest, but these are cutting timber... \n\nWhy would they need them here when they have so many laborers on hand?\n\nI think the militia is using them to intimidate their own people!\n\nSee if you can get ahold of an intact mainspring from one. I've helped repair a few back in Boralus. I should be able to figure out who is messing with their innards.", objectives = "Obtain a Drenched Mainspring.", progress = "Any luck? The mainsprings are usually brittle and easily damaged.", completion = "Perfect! Here, let me take a closer look." }
WordHunterWoW_QuestEN[49705] = { title = "Unnecessary Duress", description = "Lord Stormsong has never taken kindly to dissent, but this is madness. These laborers are being worked to death!\n\nAddington was a good man. We cannot stand for such cruelty.\n\nTake this vial and apply it to the laborers. It contains blessed seawater that will rejuvenate their strength.\n\nAvoid engaging what troops you can. They are merely following orders. More death will only worsen matters.", objectives = "Rejuvenate 8 Exhausted Laborers.", completion = "There is much work to be done, but not at the cost of our own people's lives." }
WordHunterWoW_QuestEN[49706] = { title = "Proclamation Investigation", description = "My lord seldom leaves our holdings along the northern coast, and visitors are expressly forbidden. For most, tidesages like myself are their only connection to the house proper.\n\nLord Stormsong usually delivers orders through proclamations posted throughout the valley. None have reached Brennadam, but if there are any posted here we may be able to find some answers.", objectives = "Read 3 Stormsong Proclamations.", completion = "Independence?!\n\nThis is too far. A shattered Kul Tiras will never stand!" }
WordHunterWoW_QuestEN[49710] = { title = "An Offering of Eggs", description = "Our work isn't only to capture and tame gryphons, it's also to preserve them.\n\nRescue any eggs remaining in nearby abandoned nests. Set them in one of the new nests we've built for the displaced gryphons. I am sure one of the gryphon females will adopt them.", objectives = "Collect 4 Spotted Gryphon Eggs.", progress = "You find a safe nest.", completion = "The eggs fit nicely into the new nest." }
WordHunterWoW_QuestEN[49715] = { title = "Trouble at Greystone Keep", description = "A friend of mine, a fellow military courier, had a job at Greystone Keep. The fort lies just outside of Boralus, so I would've expected him to be back by now.\n\nI have another job lined up, so could you go check out the fort for me? I'm probably just being paranoid.", objectives = "Speak with Tallis Skyheart.", completion = "A courier? I think we lost him in the coup." }
WordHunterWoW_QuestEN[49716] = { title = "A Lesson on Trust", description = "The men in the fort were once under my command, and so, they are now my responsibility. Each of them should have a badge we use for identifying individuals under certain circumstances. I would ask you to bring back a number of these as proof of thinning their ranks.\n\nThese men are no longer soldiers of Boralus, and as such, no longer deserve to carry the Proudmoore anchor.", objectives = "Retrieve 8 Marine Identification Badges.", progress = "Did you bring me those badges?", completion = "A grim task, but one that needed to be done." }
WordHunterWoW_QuestEN[49719] = { title = "Getting Paid", description = "Now that we got our mitts good and bloody, I think it's time we head back to camp.\n\nI'll run ahead, so you can finish up whatever business you got. Just remember to meet Tagart for your pay.", objectives = "Meet with Tagart at the Roughneck Camp.", completion = "Here's your pay. You seem suited for the Roughneck life. Come back sometime if you need work." }
WordHunterWoW_QuestEN[49720] = { title = "Free Bird", description = "Skyheart invited me here to teach some of his city boys how to train the local sea hawks. Some of my students went and sided with the mutiny force. Seems these soft marines have forgotten what the consequence is for betraying a Drustvar soldier.\n\nWorse yet, they've locked up quite a few of the younger birds we were training. I've got my hands full with these hawks, so if you could free a few of the young'uns while you're in the fort, I'd appreciate it.", objectives = "Free 5 Juvenile Seahawks.", progress = "Any luck? Hopefully they didn't nip you too much.", completion = "My birds deserve better partners than men who betray their own country." }
WordHunterWoW_QuestEN[49725] = { title = "A Risky Ploy", description = "Things are worse than we thought. These people are about to tear Brennadam apart!\n\nWe'll never get a chance to talk to Brother Pike in this mess.\n\nI have an idea, but if it doesn't work, well... I hope you have your running boots on.\n\nTrust me?", objectives = "Disperse the crowd surrounding Brother Pike.", progress = "We haven't had visitors here in quite some time.", completion = "Ah, Brother Alen sent you. Good." }
WordHunterWoW_QuestEN[49730] = { title = "WANTED: Thundersnout", description = "Thundersnout is the largest of the boars in the valley. She is wreaking havoc on the nearby farms and their crops.\n\nMayor Roz of Brennadam has issued a bounty for proof of her demise.\n\nThundersnout's location is near Briarback kraul, so be on the look out for quilboar!", objectives = "Deliver Thundersnout's Snout to Mayor Roz.", progress = "Yes?", completion = "The death of the matriarch means the next generation of boars will be delayed. Nice work." }
WordHunterWoW_QuestEN[49731] = { title = "Fond Farewells", description = "Dis is where we part ways, {name}.\n\nI'm going to take de name Akunda, and start a new life here. \n\nRakera saved my life, and I'm going to make sure to live a life dat was worth saving. \n\nIf you find yourself back in de city, could you deliver dis note for me? I trust you not to open it, though I doubt you could read my scrawls anyway.", objectives = "Deliver Jorak's Note to B'wizati in Zuldazar.", progress = "What is dis?", completion = "<B'wizati reads the note and wipes a tear from her eye.>\n\nHe may choose to forget, but I choose to remember, no matter what pain it brings me. \n\nAt least he is safe. Loa watch over him." }
WordHunterWoW_QuestEN[49733] = { title = "Patching Up the Rear", description = "Most of my men were injured when we were escaping the fort, those that weren't were injured holding this position.\n\n<Tallis hands you a stack of stained cloth.>\n\nAll of our better supplies are behind those walls, so we've been forced to make do with what we have. Everything that's not being worn on a soldier's person as we speak has been shredded for use as bandages. We don't have the staffing to take care of everyone.\n\nHead out and replace the worst of our injured's bandages.", objectives = "Bandage 5 injured marines.", progress = "My gratitude, that should help alleviate some of the soldiers' pain.", completion = "My gratitude, that should help alleviate some of the soldiers' pain." }
WordHunterWoW_QuestEN[49734] = { title = "Targeting a Turncoat", description = "The instigator of this mutiny is a man named Fernn. He has always shown discontent with House Proudmoore and his position here. But to betray the men he works with? That seems beyond even my expectations of him.\n\nTake him out, and show this mutiny the mistake of crossing truly loyal marines.", objectives = "Slay Fernn the Turncoat.", completion = "Good work. That should be enough help to get my men back in that fort and manning it again." }
WordHunterWoW_QuestEN[49735] = { title = "Protect the Nests", description = "Now that Tagart is done with your hazing... I mean... trials, you can start helping us with some of the work around here.\n\nSome of the nearby gryphon nests have been overrun with saurolisk. I fear that the gryphons will make new roosts elsewhere if we don't clear them out.\n\nHead up the road towards the waterfall and take out those saurolisks. Report to Shawn when you're done. He's posted as a lookout there.", objectives = "Kill 7 Hungry Dewscale.", progress = "Get bit?", completion = "Bloody saurolisks. Good riddance." }
WordHunterWoW_QuestEN[49736] = { title = "For Kul Tiras!", description = "Listen, I'll be frank with you; we're not at full strength here. Many of our soldiers recently left for Boralus on new orders.\n\nIt's like they knew just when to hit us...\n\nBut we're going to hit back! Every able-bodied man and woman in town has stepped up to mount a defense.\n\nTake this battle standard and remind them what they're fighting for!", objectives = "Use the Proudmoore Battle Standard to inspire 15 Vigil Hill Marines or Militia.", completion = "It fills my heart with pride to hear that battlecry ring out across the field." }
WordHunterWoW_QuestEN[49737] = { title = "Air Raid", description = "Those pirates have air support! They're torching our farms and splitting our attention away from the front lines. \n\nTake 'em outta the sky!", objectives = "Slay 6 Irontide Skyriders.", completion = "Damn fine work! I'll recommend you for a medal of valor!" }
WordHunterWoW_QuestEN[49738] = { title = "Hands Off My Booty!", description = "We are dealing with lawless, no-account thugs. As soon as they gained ground, they started looting! Looting right in the middle of a battle!\n\nWell I, for one, am not giving up our booty that easily.\n\nGet up to the top of Vigil Hill and man the main cannon. Rain hellfire down on those blaggards!\n\nDismissed!", objectives = "Man the Vigil Hill Cannon and use it to slay 20 looters.", progress = "What are you waiting for? Get up there and man that cannon!", completion = "They destroyed the main gun?!\n\nThen it's time to advance on foot!" }
WordHunterWoW_QuestEN[49739] = { title = "Enemies at the Gate", description = "", objectives = "We'll recover the loot from that ship later, assuming the whole thing doesn't burn down or sink first!" }
WordHunterWoW_QuestEN[49740] = { title = "Cease Fire!", description = "The enemy has turned our forward cannons around on us.\n\nScuttle that equipment to stop the bombardments!", objectives = "Destroy 4 Captured Cannons.", completion = "The thunder of cannons can strike fear or inspire hope, depending on which end you're standing." }
WordHunterWoW_QuestEN[49741] = { title = "Righteous Retribution", description = "Cyrus taught me how to deal with thugs, bullies, and scum like pirates.\n\nWhen they hit us, we hit back twice as hard.\n\n<Taelia's hand finds the haft of her hammer and grips it tight.>\n\nIt's time to hit back.", objectives = "Help Taelia destroy the pirate ships in Daelin's Gate.", completion = "Those cowards only understand strength. Show them you're not an easy victim and they turn tail and run." }
